#[tauri::command]
fn serial_set_lines(
    state: State<'_, AppState>,
    request: SerialLineRequest,
) -> Result<SessionSummary, String> {
    if request.dtr.is_none() && request.rts.is_none() {
        return Err("串口线路请求必须包含 DTR 或 RTS".to_string());
    }
    let connections = state.serial.lock().map_err(|error| error.to_string())?;
    let writer = connections
        .get(&request.session_id)
        .ok_or_else(|| "串口会话尚未连接".to_string())?
        .writer
        .as_ref()
        .map(Arc::clone)
        .ok_or_else(|| "串口正在重连".to_string())?;
    let mut port = writer.lock().map_err(|error| error.to_string())?;
    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    let (old_dtr, old_rts) = match store.profile(&request.session_id) {
        Some(SessionProfile {
            connection: ConnectionConfig::Serial(serial),
            ..
        }) => (serial.dtr, serial.rts),
        Some(_) => {
            return Err(format!(
                "session is not serial-backed: {}",
                request.session_id
            ))
        }
        None => return Err(format!("unknown session: {}", request.session_id)),
    };
    apply_serial_line_updates_with(old_dtr, old_rts, request.dtr, request.rts, |line, value| {
        match line {
            SerialControlLine::Dtr => port
                .write_data_terminal_ready(value)
                .map_err(|error| error.to_string()),
            SerialControlLine::Rts => port
                .write_request_to_send(value)
                .map_err(|error| error.to_string()),
        }
    })?;
    record_applied_serial_line_state(&mut store, &state.store_path, &request)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SerialControlLine {
    Dtr,
    Rts,
}

impl SerialControlLine {
    fn label(self) -> &'static str {
        match self {
            Self::Dtr => "DTR",
            Self::Rts => "RTS",
        }
    }
}

fn apply_serial_line_updates_with<WriteLine>(
    old_dtr: bool,
    old_rts: bool,
    dtr: Option<bool>,
    rts: Option<bool>,
    mut write_line: WriteLine,
) -> Result<(), String>
where
    WriteLine: FnMut(SerialControlLine, bool) -> Result<(), String>,
{
    let requested = [
        (SerialControlLine::Dtr, dtr, old_dtr),
        (SerialControlLine::Rts, rts, old_rts),
    ];
    let mut applied = Vec::new();
    for (line, value, previous) in requested {
        let Some(value) = value else {
            continue;
        };
        if let Err(error) = write_line(line, value) {
            let mut rollback_errors = Vec::new();
            if let Err(rollback_error) = write_line(line, previous) {
                rollback_errors.push(format!("恢复 {} 失败: {rollback_error}", line.label()));
            }
            for (applied_line, applied_previous) in applied.into_iter().rev() {
                if let Err(rollback_error) = write_line(applied_line, applied_previous) {
                    rollback_errors.push(format!(
                        "恢复 {} 失败: {rollback_error}",
                        applied_line.label()
                    ));
                }
            }
            let error = format!("设置 {} 失败: {error}", line.label());
            return Err(if rollback_errors.is_empty() {
                error
            } else {
                format!("{error}; {}", rollback_errors.join("; "))
            });
        }
        applied.push((line, previous));
    }
    Ok(())
}

fn record_applied_serial_line_state(
    store: &mut SessionStore,
    store_path: &Path,
    request: &SerialLineRequest,
) -> Result<SessionSummary, String> {
    if request.dtr.is_none() && request.rts.is_none() {
        return Err("串口线路请求必须包含 DTR 或 RTS".to_string());
    }
    let profile = store
        .profiles
        .iter_mut()
        .find(|profile| profile.id == request.session_id)
        .ok_or_else(|| format!("unknown session: {}", request.session_id))?;
    let ConnectionConfig::Serial(serial) = &mut profile.connection else {
        return Err(format!(
            "session is not serial-backed: {}",
            request.session_id
        ));
    };
    if let Some(dtr) = request.dtr {
        serial.dtr = dtr;
    }
    if let Some(rts) = request.rts {
        serial.rts = rts;
    }
    store.record_system_event(&request.session_id, "PortMate: serial line state updated");
    let summary = store
        .summaries()
        .into_iter()
        .find(|summary| summary.profile.id == request.session_id)
        .ok_or_else(|| format!("session summary is missing: {}", request.session_id))?;
    persist_applied_store(store, store_path, "serial line state")
        .map_err(|error| format!("串口线路已在设备上更新，但 Profile 状态无法持久化: {error}"))?;
    Ok(summary)
}

#[tauri::command]
fn serial_send_break(state: State<'_, AppState>, session_id: String) -> Result<(), String> {
    let connections = state.serial.lock().map_err(|error| error.to_string())?;
    let writer = connections
        .get(&session_id)
        .ok_or_else(|| "串口会话尚未连接".to_string())?
        .writer
        .as_ref()
        .map(Arc::clone)
        .ok_or_else(|| "串口正在重连".to_string())?;
    let port = writer.lock().map_err(|error| error.to_string())?;
    let clear_retried = pulse_serial_break_with(
        || port.set_break().map_err(|error| error.to_string()),
        || port.clear_break().map_err(|error| error.to_string()),
        || std::thread::sleep(Duration::from_millis(250)),
    )?;
    if clear_retried {
        eprintln!("PortMate: serial Break clear succeeded on retry");
    }

    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    store.record_system_event(&session_id, "PortMate: serial Break sent");
    persist_applied_store(&store, &state.store_path, "serial Break event")
        .map_err(|error| format!("Break 已发送并清除，但系统事件无法持久化: {error}"))?;
    Ok(())
}

fn pulse_serial_break_with<SetBreak, ClearBreak, Wait>(
    mut set_break: SetBreak,
    mut clear_break: ClearBreak,
    wait: Wait,
) -> Result<bool, String>
where
    SetBreak: FnMut() -> Result<(), String>,
    ClearBreak: FnMut() -> Result<(), String>,
    Wait: FnOnce(),
{
    if let Err(error) = set_break() {
        return Err(match clear_break() {
            Ok(()) => format!("发送 Break 失败并已尝试清除线路: {error}"),
            Err(clear_error) => {
                format!("发送 Break 失败: {error}; 清除 Break 也失败: {clear_error}")
            }
        });
    }
    wait();
    let first_error = match clear_break() {
        Ok(()) => return Ok(false),
        Err(error) => error,
    };
    match clear_break() {
        Ok(()) => Ok(true),
        Err(retry_error) => Err(format!(
            "清除 Break 失败: {first_error}; 重试清除 Break 仍失败: {retry_error}"
        )),
    }
}

fn ensure_serial_profile(store: &Arc<Mutex<SessionStore>>, session_id: &str) -> Result<(), String> {
    let store = store.lock().map_err(|error| error.to_string())?;
    match store.profile(session_id).map(|profile| profile.connection) {
        Some(ConnectionConfig::Serial(_)) => Ok(()),
        Some(_) => Err(format!("session is not serial-backed: {session_id}")),
        None => Err(format!("unknown session: {session_id}")),
    }
}

fn serial_capture_snapshot_inner(
    state: &AppState,
    session_id: &str,
    after_id: Option<&str>,
) -> Result<SerialCaptureSnapshot, String> {
    ensure_serial_profile(&state.store, session_id)?;
    let capture = serial_capture_for_session(&state.serial_captures, session_id)?;
    let capture = capture.lock().map_err(|error| error.to_string())?;
    Ok(capture.snapshot_since(after_id))
}

fn serial_capture_history_inner(
    store_path: &Path,
    store: &Arc<Mutex<SessionStore>>,
    session_id: &str,
) -> Result<SerialCaptureHistorySnapshot, String> {
    ensure_serial_profile(store, session_id)?;
    let (enabled, candidates) = {
        let store = store.lock().map_err(|error| error.to_string())?;
        let profile = store
            .profile(session_id)
            .ok_or_else(|| format!("unknown session: {session_id}"))?;
        let enabled = profile.logging.enabled && profile.logging.raw;
        let candidates = if enabled {
            store
                .events
                .iter()
                .filter_map(|event| {
                    let reference = event.bytes_ref.as_ref()?;
                    (event.session_id == session_id
                        && matches!(
                            event.direction,
                            EventDirection::Inbound | EventDirection::Outbound
                        ))
                    .then(|| {
                        (
                            event.id.clone(),
                            event.ts,
                            event.direction,
                            reference.clone(),
                        )
                    })
                })
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        (enabled, candidates)
    };
    if !enabled {
        return Ok(SerialCaptureHistorySnapshot {
            frames: Vec::new(),
            enabled: false,
            total_frames: 0,
            captured_bytes: 0,
            dropped_frames: 0,
            unavailable_frames: 0,
        });
    }

    let total_frames = candidates.len();
    let mut frames = Vec::new();
    let mut captured_bytes = 0_usize;
    let mut unavailable_frames = 0_usize;
    for (id, ts, direction, reference) in candidates.into_iter().rev() {
        if frames.len() >= MAX_SERIAL_CAPTURE_HISTORY_FRAMES {
            break;
        }
        let Ok((relative, _, bytes)) = read_verified_log_bytes_ref(store_path, &reference) else {
            unavailable_frames = unavailable_frames.saturating_add(1);
            continue;
        };
        if Path::new(&relative)
            .extension()
            .and_then(|value| value.to_str())
            != Some("raw")
            || bytes.is_empty()
        {
            unavailable_frames = unavailable_frames.saturating_add(1);
            continue;
        }
        let original_length = bytes.len();
        let captured_length = original_length.min(MAX_SERIAL_CAPTURE_FRAME_BYTES);
        if captured_bytes.saturating_add(captured_length) > MAX_SERIAL_CAPTURE_HISTORY_BYTES {
            break;
        }
        captured_bytes = captured_bytes.saturating_add(captured_length);
        frames.push(SerialCaptureFrame {
            id,
            ts,
            direction,
            bytes: bytes[..captured_length].to_vec(),
            original_length,
            truncated: captured_length != original_length,
        });
    }
    frames.reverse();
    Ok(SerialCaptureHistorySnapshot {
        dropped_frames: total_frames
            .saturating_sub(frames.len())
            .saturating_sub(unavailable_frames),
        frames,
        enabled: true,
        total_frames,
        captured_bytes,
        unavailable_frames,
    })
}

fn serial_capture_hex(bytes: &[u8]) -> String {
    bytes
        .iter()
        .map(|byte| format!("{byte:02X}"))
        .collect::<Vec<_>>()
        .join(" ")
}

fn serial_capture_ascii(bytes: &[u8]) -> String {
    let mut preview = String::new();
    for byte in bytes {
        match byte {
            b'\r' => preview.push_str("\\r"),
            b'\n' => preview.push_str("\\n"),
            b'\t' => preview.push_str("\\t"),
            0x20..=0x7e => preview.push(char::from(*byte)),
            _ => preview.push('.'),
        }
    }
    preview
}

fn export_serial_capture_inner(
    store_path: &Path,
    captures: &SerialCaptureMap,
    request: ExportSerialCaptureRequest,
) -> Result<ExportSerialCaptureResult, String> {
    let requested = serial_capture_export_ids(&request, MAX_SERIAL_CAPTURE_FRAMES)?;
    let capture = {
        let captures = captures.lock().map_err(|error| error.to_string())?;
        captures
            .get(&request.session_id)
            .map(Arc::clone)
            .ok_or_else(|| "serial capture is empty".to_string())?
    };
    let selected = {
        let capture = capture.lock().map_err(|error| error.to_string())?;
        capture
            .frames
            .iter()
            .filter(|frame| requested.contains(&frame.id))
            .cloned()
            .collect::<Vec<_>>()
    };
    if selected.len() != requested.len() {
        return Err("serial capture changed; refresh before exporting".to_string());
    }

    export_serial_capture_frames(store_path, &request.session_id, "live", &selected)
}

fn export_mcp_audit_inner(
    store_path: &Path,
    audit: &[AuditRecord],
    request: ExportMcpAuditRequest,
) -> Result<ExportMcpAuditResult, String> {
    if request.record_ids.is_empty() {
        return Err("select at least one MCP audit record to export".to_string());
    }
    if request.record_ids.len() > MAX_MCP_AUDIT_EXPORT_RECORDS {
        return Err(format!(
            "MCP audit export record limit exceeded ({MAX_MCP_AUDIT_EXPORT_RECORDS})"
        ));
    }
    let mut requested = HashSet::new();
    for id in &request.record_ids {
        if id.trim().is_empty() || id.len() > 128 || id.chars().any(char::is_control) {
            return Err("MCP audit export contains an invalid record ID".to_string());
        }
        if !requested.insert(id.as_str()) {
            return Err("MCP audit export contains duplicate record IDs".to_string());
        }
    }

    let by_id = audit
        .iter()
        .map(|record| (record.id.as_str(), record))
        .collect::<HashMap<_, _>>();
    let selected = request
        .record_ids
        .iter()
        .map(|id| {
            by_id
                .get(id.as_str())
                .copied()
                .ok_or_else(|| "MCP audit changed; refresh before exporting".to_string())
        })
        .collect::<Result<Vec<_>, _>>()?;

    let created_at = Utc::now();
    let mut output = Vec::new();
    append_mcp_audit_jsonl(
        &mut output,
        &serde_json::json!({
            "type": "metadata",
            "format": "portmate-mcp-audit",
            "version": 1,
            "createdAt": created_at.to_rfc3339(),
            "recordCount": selected.len(),
            "containsSecretBodies": false,
        }),
    )?;
    for record in &selected {
        append_mcp_audit_jsonl(
            &mut output,
            &serde_json::json!({ "type": "record", "record": record }),
        )?;
    }

    let export_dir = prepare_export_directory(store_path, "MCP audit")?;
    let timestamp = created_at.format("%Y%m%dT%H%M%SZ");
    let name = format!(
        "portmate-mcp-audit-{timestamp}-{}.jsonl",
        &Uuid::new_v4().simple().to_string()[..8]
    );
    let final_path = export_dir.join(name);
    let finalized = write_atomic_export_with_checksum(&final_path, &output, "MCP audit export")?;
    Ok(ExportMcpAuditResult {
        path: final_path.display().to_string(),
        checksum_path: finalized.checksum_path.display().to_string(),
        sha256: finalized.sha256,
        size: finalized.size,
        records: selected.len(),
    })
}

fn append_mcp_audit_jsonl<T: Serialize>(output: &mut Vec<u8>, value: &T) -> Result<(), String> {
    let encoded = serde_json::to_vec(value)
        .map_err(|error| format!("failed to encode MCP audit export: {error}"))?;
    if encoded.len() > MAX_MCP_AUDIT_EXPORT_RECORD_BYTES {
        return Err(format!(
            "MCP audit export record exceeds {MAX_MCP_AUDIT_EXPORT_RECORD_BYTES} bytes"
        ));
    }
    if encoded.len().saturating_add(1) > MAX_MCP_AUDIT_EXPORT_BYTES.saturating_sub(output.len()) {
        return Err(format!(
            "MCP audit export exceeds {MAX_MCP_AUDIT_EXPORT_BYTES} bytes"
        ));
    }
    output.extend_from_slice(&encoded);
    output.push(b'\n');
    Ok(())
}

fn export_serial_capture_history_inner(
    store_path: &Path,
    store: &Arc<Mutex<SessionStore>>,
    request: ExportSerialCaptureRequest,
) -> Result<ExportSerialCaptureResult, String> {
    let requested = serial_capture_export_ids(&request, MAX_SERIAL_CAPTURE_HISTORY_FRAMES)?;
    let history = serial_capture_history_inner(store_path, store, &request.session_id)?;
    if !history.enabled {
        return Err("Raw logging is not enabled for this serial profile".to_string());
    }
    let selected = history
        .frames
        .into_iter()
        .filter(|frame| requested.contains(&frame.id))
        .collect::<Vec<_>>();
    if selected.len() != requested.len() {
        return Err("serial capture history changed; refresh before exporting".to_string());
    }
    export_serial_capture_frames(store_path, &request.session_id, "raw-log", &selected)
}

fn serial_capture_export_ids(
    request: &ExportSerialCaptureRequest,
    maximum: usize,
) -> Result<HashSet<String>, String> {
    if request.frame_ids.is_empty() {
        return Err("select at least one serial capture frame to export".to_string());
    }
    if request.frame_ids.len() > maximum {
        return Err(format!(
            "serial capture export frame limit exceeded ({maximum})"
        ));
    }
    let requested = request.frame_ids.iter().cloned().collect::<HashSet<_>>();
    if requested.len() != request.frame_ids.len() {
        return Err("serial capture export contains duplicate frame IDs".to_string());
    }
    Ok(requested)
}

fn export_serial_capture_frames(
    store_path: &Path,
    session_id: &str,
    source: &str,
    selected: &[SerialCaptureFrame],
) -> Result<ExportSerialCaptureResult, String> {
    let created_at = Utc::now();
    let mut output = Vec::new();
    serde_json::to_writer(
        &mut output,
        &serde_json::json!({
            "type": "metadata",
            "format": "portmate-serial-capture",
            "version": 1,
            "createdAt": created_at.to_rfc3339(),
            "sessionId": session_id,
            "source": source,
            "rawUnredacted": true,
            "frameCount": selected.len(),
        }),
    )
    .map_err(|error| format!("failed to encode serial capture metadata: {error}"))?;
    output.push(b'\n');
    let mut captured_bytes = 0_usize;
    let mut truncated_frames = 0_usize;
    for frame in selected {
        captured_bytes = captured_bytes.saturating_add(frame.bytes.len());
        truncated_frames += usize::from(frame.truncated);
        serde_json::to_writer(
            &mut output,
            &serde_json::json!({
                "type": "frame",
                "id": frame.id,
                "ts": frame.ts,
                "direction": frame.direction,
                "capturedLength": frame.bytes.len(),
                "originalLength": frame.original_length,
                "truncated": frame.truncated,
                "hex": serial_capture_hex(&frame.bytes),
                "ascii": serial_capture_ascii(&frame.bytes),
            }),
        )
        .map_err(|error| format!("failed to encode serial capture frame: {error}"))?;
        output.push(b'\n');
    }

    let export_dir = prepare_export_directory(store_path, "serial capture")?;
    let timestamp = created_at.format("%Y%m%dT%H%M%SZ");
    let name = format!(
        "{}-{timestamp}-serial-{}.jsonl",
        sanitize_log_path_segment(session_id),
        &Uuid::new_v4().simple().to_string()[..8]
    );
    let final_path = export_dir.join(name);
    let finalized =
        write_atomic_export_with_checksum(&final_path, &output, "serial capture export")?;
    Ok(ExportSerialCaptureResult {
        path: final_path.display().to_string(),
        checksum_path: finalized.checksum_path.display().to_string(),
        sha256: finalized.sha256,
        size: finalized.size,
        frames: selected.len(),
        captured_bytes,
        truncated_frames,
    })
}

fn export_terminal_text_inner(
    store_path: &Path,
    request: ExportTerminalTextRequest,
) -> Result<ExportTerminalTextResult, String> {
    validate_terminal_text_export_request(&request, MAX_TERMINAL_TEXT_EXPORT_BYTES)?;
    let created_at = Utc::now();
    let export_dir = prepare_export_directory(store_path, "terminal text")?;
    let session_name = sanitize_log_path_segment(&request.session_id);
    let timestamp = created_at.format("%Y%m%dT%H%M%SZ");
    let name = format!(
        "{}-{timestamp}-{}-{}.txt",
        if session_name.is_empty() {
            "session"
        } else {
            &session_name
        },
        request.source.as_str(),
        &Uuid::new_v4().simple().to_string()[..8]
    );
    let final_path = export_dir.join(name);
    let finalized = write_atomic_export_with_checksum(
        &final_path,
        request.text.as_bytes(),
        "terminal text export",
    )?;
    Ok(ExportTerminalTextResult {
        path: final_path.display().to_string(),
        checksum_path: finalized.checksum_path.display().to_string(),
        sha256: finalized.sha256,
        size: finalized.size,
        session_id: request.session_id,
        view_id: request.view_id,
        source: request.source,
    })
}

fn validate_terminal_text_export_request(
    request: &ExportTerminalTextRequest,
    max_bytes: usize,
) -> Result<(), String> {
    if request.session_id.trim().is_empty()
        || request.session_id.len() > 256
        || request.session_id.chars().any(char::is_control)
    {
        return Err("invalid terminal export session id".to_string());
    }
    if request.view_id.trim().is_empty()
        || request.view_id.len() > 128
        || request.view_id.chars().any(char::is_control)
    {
        return Err("invalid terminal export view id".to_string());
    }
    if request.text.is_empty() {
        return Err("terminal export text is empty".to_string());
    }
    if request.text.len() > max_bytes {
        return Err(format!("terminal export exceeds {max_bytes} byte limit"));
    }
    Ok(())
}

#[tauri::command]
async fn refresh_sysmon(
    state: State<'_, AppState>,
    session_id: String,
) -> Result<SysmonSnapshot, String> {
    refresh_sysmon_inner(state.inner(), &session_id).await
}

async fn refresh_sysmon_inner(
    state: &AppState,
    session_id: &str,
) -> Result<SysmonSnapshot, String> {
    let _permit = Arc::clone(&state.sysmon_slots)
        .try_acquire_owned()
        .map_err(|_| format!("Sysmon refresh limit reached ({MAX_CONCURRENT_SYSMON_REFRESHES})"))?;
    let profile = {
        let store = state.store.lock().map_err(|error| error.to_string())?;
        store
            .profile(session_id)
            .ok_or_else(|| format!("unknown session: {session_id}"))?
    };

    let snapshot = if matches!(
        profile.connection,
        ConnectionConfig::Ssh(_) | ConnectionConfig::Tmux(_)
    ) {
        let auxiliary = ssh_auxiliary_lease(state, session_id)?;
        collect_remote_sysmon(session_id, auxiliary.handle()).await?
    } else {
        collect_local_sysmon(session_id).await?
    };

    commit_sysmon_snapshot(state, session_id, snapshot)
}

fn commit_sysmon_snapshot(
    state: &AppState,
    session_id: &str,
    snapshot: SysmonSnapshot,
) -> Result<SysmonSnapshot, String> {
    if snapshot.session_id != session_id {
        return Err("Sysmon snapshot session does not match the requested session".to_string());
    }
    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    commit_tracked_store_mutation(&mut store, &state.store_path, |next_store| {
        if next_store.profile(session_id).is_none() {
            return Err(format!("unknown session: {session_id}"));
        }
        next_store.record_sysmon_snapshot(snapshot.clone());
        let event_ids = next_store
            .record_system_event_tracked(session_id, "PortMate: sysmon snapshot refreshed")
            .into_iter()
            .collect();
        Ok((snapshot, event_ids))
    })
}

#[tauri::command]
fn list_sysmon_history(
    state: State<'_, AppState>,
    session_id: String,
    limit: Option<usize>,
) -> Result<Vec<SysmonSnapshot>, String> {
    let limit = validate_sysmon_history_query_limit(limit)?;
    let store = state.store.lock().map_err(|error| error.to_string())?;
    if store.profile(&session_id).is_none() {
        return Err(format!("unknown session: {session_id}"));
    }
    Ok(store.sysmon_history_for(&session_id, limit))
}

fn validate_sysmon_history_query_limit(limit: Option<usize>) -> Result<usize, String> {
    let limit = limit.unwrap_or(DEFAULT_SYSMON_HISTORY_QUERY_LIMIT);
    if !(1..=MAX_SYSMON_HISTORY_QUERY_LIMIT).contains(&limit) {
        return Err(format!(
            "Sysmon history limit must be between 1 and {MAX_SYSMON_HISTORY_QUERY_LIMIT}"
        ));
    }
    Ok(limit)
}

