fn write_private_atomic_file(path: &Path, bytes: &[u8], label: &str) -> Result<(), String> {
    let parent = path.parent().unwrap_or_else(|| Path::new("."));
    fs::create_dir_all(parent).map_err(|error| {
        format!(
            "failed to create {label} directory {}: {error}",
            parent.display()
        )
    })?;
    let prefix = format!(
        ".{}.",
        path.file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("portmate-private")
    );
    let mut temp = tempfile::Builder::new()
        .prefix(&prefix)
        .suffix(".tmp")
        .tempfile_in(parent)
        .map_err(|error| format!("failed to create temporary {label}: {error}"))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(temp.path(), fs::Permissions::from_mode(0o600))
            .map_err(|error| format!("failed to secure temporary {label}: {error}"))?;
    }
    temp.as_file_mut()
        .write_all(bytes)
        .and_then(|_| temp.as_file_mut().flush())
        .and_then(|_| temp.as_file().sync_all())
        .map_err(|error| format!("failed to persist temporary {label}: {error}"))?;
    temp.persist(path)
        .map_err(|error| format!("failed to atomically replace {label}: {}", error.error))?;
    Ok(())
}

fn proxy_target_authority(host: &str, port: u16) -> Result<String, String> {
    let host = host.trim();
    if host.is_empty() {
        return Err("代理目标主机不能为空".to_string());
    }
    if host.bytes().any(|byte| byte == b'\r' || byte == b'\n') {
        return Err("代理目标主机不能包含换行符".to_string());
    }
    if host.parse::<std::net::Ipv6Addr>().is_ok() {
        Ok(format!("[{host}]:{port}"))
    } else {
        Ok(format!("{host}:{port}"))
    }
}

fn normalized_enabled_proxy(proxy: &ProxyConfig) -> Result<Option<ProxyConfig>, String> {
    if !proxy.enabled {
        return Ok(None);
    }
    let mut proxy = proxy.clone();
    proxy.normalize();
    if proxy.host.is_empty() {
        return Err("代理主机不能为空".to_string());
    }
    if proxy
        .host
        .bytes()
        .any(|byte| byte == b'\r' || byte == b'\n')
    {
        return Err("代理主机不能包含换行符".to_string());
    }
    if proxy.port == 0 {
        return Err("代理端口必须在 1-65535 之间".to_string());
    }
    if let Some(secret_ref) = proxy.password_secret_ref.as_deref() {
        if canonical_secret_ref(secret_ref).is_none() {
            return Err("代理密码 secretRef 无效".to_string());
        }
        if proxy.username.is_empty() {
            return Err("已保存代理密码时，代理用户名不能为空".to_string());
        }
    }
    Ok(Some(proxy))
}

fn resolve_proxy_credentials_with<ReadSecret>(
    proxy: &ProxyConfig,
    mut read_secret: ReadSecret,
) -> Result<Option<ProxyCredentials>, String>
where
    ReadSecret: FnMut(&str) -> Result<String, String>,
{
    let Some(secret_ref) = proxy.password_secret_ref.as_deref() else {
        return Ok(None);
    };
    if proxy.username.is_empty() {
        return Err("已保存代理密码时，代理用户名不能为空".to_string());
    }
    let password = Zeroizing::new(
        read_secret(secret_ref).map_err(|error| format!("代理密码读取失败: {error}"))?,
    );
    validate_proxy_credentials(proxy.kind, &proxy.username, password.as_str())?;
    Ok(Some(ProxyCredentials {
        username: proxy.username.clone(),
        password,
    }))
}

async fn connect_target_stream(
    target_host: &str,
    target_port: u16,
    proxy: &ProxyConfig,
    label: &str,
) -> Result<TcpStream, String> {
    let authority = proxy_target_authority(target_host, target_port)?;
    let Some(proxy) = normalized_enabled_proxy(proxy)? else {
        return TcpStream::connect((target_host, target_port))
            .await
            .map_err(|error| format!("{label} 连接失败 {authority}: {error}"));
    };
    let credentials = resolve_proxy_credentials_with(&proxy, read_secret_from_store)?;
    let mut stream = TcpStream::connect((proxy.host.as_str(), proxy.port))
        .await
        .map_err(|error| {
            format!(
                "{label} 代理连接失败 {}:{}: {error}",
                proxy.host, proxy.port
            )
        })?;
    match proxy.kind {
        ProxyKind::HttpConnect => {
            perform_http_connect(&mut stream, &authority, credentials.as_ref(), label).await?;
        }
        ProxyKind::Socks5 => {
            perform_socks5_connect(
                &mut stream,
                target_host.trim(),
                target_port,
                credentials.as_ref(),
                label,
            )
            .await?;
        }
    }
    Ok(stream)
}

#[derive(Debug)]
enum SshTransportConnectError {
    Timeout,
    Transport(String),
    Handshake(String),
}

async fn connect_ssh_transport<H>(
    params: SshTransportConnectParams<'_>,
    handler: H,
) -> Result<client::Handle<H>, SshTransportConnectError>
where
    H: client::Handler + Send + 'static,
    H::Error: std::fmt::Display,
{
    let SshTransportConnectParams {
        config,
        target_host,
        target_port,
        proxy,
        tcp_keepalive_enabled,
        timeout,
        label,
    } = params;
    tokio::time::timeout(timeout, async {
        let stream = connect_target_stream(target_host, target_port, proxy, label)
            .await
            .map_err(SshTransportConnectError::Transport)?;
        if config.nodelay {
            stream
                .set_nodelay(true)
                .map_err(|error| SshTransportConnectError::Transport(error.to_string()))?;
        }
        configure_ssh_tcp_keepalive(&stream, label, tcp_keepalive_enabled)
            .map_err(SshTransportConnectError::Transport)?;
        client::connect_stream(config, stream, handler)
            .await
            .map_err(|error| SshTransportConnectError::Handshake(error.to_string()))
    })
    .await
    .map_err(|_| SshTransportConnectError::Timeout)?
}

fn configure_ssh_tcp_keepalive(
    stream: &TcpStream,
    label: &str,
    enabled: Option<bool>,
) -> Result<(), String> {
    let Some(enabled) = enabled else {
        return Ok(());
    };
    SockRef::from(stream)
        .set_keepalive(enabled)
        .map_err(|error| format!("{label} 设置 TCP keepalive 失败: {error}"))
}

async fn scan_ssh_host_key_inner(
    state: &AppState,
    profile: SessionProfile,
    password: Option<&str>,
    passphrase: Option<&str>,
) -> Result<HostKeyScanResult, String> {
    let ssh = match &profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => ssh.clone(),
        _ => return Err("profile is not SSH-backed".to_string()),
    };
    let host = ssh.endpoint.host.trim().to_string();
    if host.is_empty() {
        return Err("SSH 主机不能为空".to_string());
    }
    if ssh.endpoint.port == 0 {
        return Err("SSH 端口必须在 1-65535 之间".to_string());
    }

    let observed_key = Arc::new(Mutex::new(None));
    let alias = ssh
        .host_key_policy
        .alias
        .clone()
        .filter(|value| !value.trim().is_empty())
        .or_else(|| Some(profile.id.clone()));
    let handler = HostKeyScanHandler {
        host: host.clone(),
        port: ssh.endpoint.port,
        alias,
        observed_key: Arc::clone(&observed_key),
    };
    let config = Arc::new(client::Config {
        keepalive_interval: Some(Duration::from_secs(10)),
        keepalive_max: 1,
        nodelay: true,
        ..Default::default()
    });

    if !ssh.jumps.is_empty() {
        if let Some(result) = scan_ssh_host_key_via_jump(JumpHostKeyScanRequest {
            state,
            profile: &profile,
            ssh: &ssh,
            config,
            target_handler: handler,
            password,
            passphrase,
        })
        .await?
        {
            return Ok(result);
        }
    } else {
        let session = connect_ssh_transport(
            SshTransportConnectParams {
                config,
                target_host: &host,
                target_port: ssh.endpoint.port,
                proxy: &ssh.proxy,
                tcp_keepalive_enabled: ssh.tcp_keepalive_enabled,
                timeout: Duration::from_secs(12),
                label: "SSH host key 扫描",
            },
            handler,
        )
        .await;
        let session = match session {
            Ok(session) => session,
            Err(SshTransportConnectError::Timeout) => {
                return Err(format!(
                    "SSH host key 扫描超时: {host}:{}",
                    ssh.endpoint.port
                ));
            }
            Err(SshTransportConnectError::Transport(error)) => return Err(error),
            Err(SshTransportConnectError::Handshake(error)) => {
                return Err(format!(
                    "SSH host key 扫描失败: {host}:{}: {error}",
                    ssh.endpoint.port
                ));
            }
        };
        let _ = session
            .disconnect(Disconnect::ByApplication, "PortMate host key scan", "en")
            .await;
    }

    let observation = observed_key
        .lock()
        .map_err(|error| error.to_string())?
        .clone()
        .ok_or_else(|| "SSH host key 扫描未收到服务器 host key".to_string())?;
    let mut host_keys = {
        let store = state.store.lock().map_err(|error| error.to_string())?;
        store.host_keys.clone()
    };
    host_keys.keys.extend(ssh.trusted_host_keys.clone());
    host_keys
        .keys
        .extend(one_time_host_keys_snapshot(state, &profile.id)?);
    let evaluation = host_keys
        .evaluate(&profile.id, &ssh.host_key_policy, &observation)
        .map_err(|error| error.to_string())?;
    Ok(HostKeyScanResult {
        label: Some("目标 SSH".to_string()),
        observation,
        evaluation,
    })
}

async fn scan_ssh_host_key_via_jump(
    request: JumpHostKeyScanRequest<'_>,
) -> Result<Option<HostKeyScanResult>, String> {
    let JumpHostKeyScanRequest {
        state,
        profile,
        ssh,
        config,
        target_handler,
        password,
        passphrase,
    } = request;

    let mut host_keys = {
        let store = state.store.lock().map_err(|error| error.to_string())?;
        store.host_keys.clone()
    };
    host_keys.keys.extend(ssh.trusted_host_keys.clone());
    let one_time_host_keys = one_time_host_keys_snapshot(state, &profile.id)?;
    let one_time_host_key_ids = one_time_host_keys
        .iter()
        .map(|key| key.id.clone())
        .collect::<Vec<_>>();
    host_keys.keys.extend(one_time_host_keys);

    let mut jump_sessions: Vec<client::Handle<PortMateSshHandler>> = Vec::new();
    for (index, jump) in ssh.jumps.iter().enumerate() {
        let (jump_host, jump_port, jump_username) = jump_endpoint_details(jump, index)?;
        let jump_policy = jump_host_key_policy(ssh, jump);
        let jump_ssh = jump_ssh_connection(ssh, jump, jump_policy.clone());
        let observed_jump_key = Arc::new(Mutex::new(None));
        let jump_key_error = Arc::new(Mutex::new(None));
        let jump_handler = ssh_handler_for_endpoint(SshHandlerParams {
            profile_id: profile.id.clone(),
            host: jump_host.clone(),
            port: jump_port,
            alias: jump_policy.alias.clone(),
            policy: jump_ssh.host_key_policy.clone(),
            host_keys: host_keys.clone(),
            one_time_host_key_ids: one_time_host_key_ids.clone(),
            observed_key: Arc::clone(&observed_jump_key),
            host_key_error: Arc::clone(&jump_key_error),
            remote_forwards: Arc::new(Mutex::new(HashMap::new())),
        });
        let jump_label = format!("Jump Host 第 {} 跳", index + 1);
        let mut jump_session = if let Some(previous_jump) = jump_sessions.last_mut() {
            let jump_channel = match open_direct_tcpip_with_timeout(
                previous_jump,
                jump_host.clone(),
                jump_port,
                "127.0.0.1".to_string(),
                0,
                Duration::from_secs(12),
                "PortMate jump host key scan channel timeout",
            )
            .await
            {
                Ok(channel) => channel,
                Err(DirectTcpipOpenError::Failed(error)) => {
                    disconnect_jump_sessions(
                        jump_sessions,
                        "PortMate jump host key scan channel failed",
                    )
                    .await;
                    return Err(format!(
                        "Jump Host 第 {} 跳打开 host key 扫描通道到 {jump_host}:{jump_port} 失败: {error}",
                        index + 1
                    ));
                }
                Err(DirectTcpipOpenError::TimedOut {
                    timeout_ms,
                    cleanup_warning,
                }) => {
                    disconnect_jump_sessions(
                        jump_sessions,
                        "PortMate jump host key scan channel timeout",
                    )
                    .await;
                    let cleanup_warning = cleanup_warning
                        .map(|warning| format!("; {warning}"))
                        .unwrap_or_default();
                    return Err(format!(
                        "Jump Host 第 {} 跳打开 host key 扫描通道到 {jump_host}:{jump_port} 超时（{timeout_ms} ms）{cleanup_warning}",
                        index + 1
                    ));
                }
            };
            match tokio::time::timeout(
                Duration::from_secs(12),
                client::connect_stream(config.clone(), jump_channel.into_stream(), jump_handler),
            )
            .await
            {
                Ok(Ok(session)) => session,
                Err(_) => {
                    disconnect_jump_sessions(jump_sessions, "PortMate jump host key scan timeout")
                        .await;
                    return Err(format!(
                        "Jump Host 第 {} 跳 host key 扫描连接超时: {jump_host}:{jump_port}",
                        index + 1
                    ));
                }
                Ok(Err(error)) => {
                    if let Some(result) = host_key_scan_result_for_policy(
                        profile,
                        ssh,
                        &jump_policy,
                        &observed_jump_key,
                        &jump_label,
                        state,
                    )? {
                        disconnect_jump_sessions(
                            jump_sessions,
                            "PortMate jump host key scan needs confirmation",
                        )
                        .await;
                        return Ok(Some(result));
                    }
                    let message = jump_key_error
                        .lock()
                        .ok()
                        .and_then(|reason| reason.clone())
                        .unwrap_or_else(|| {
                            format!(
                                "Jump Host 第 {} 跳 host key 扫描连接失败: {error}",
                                index + 1
                            )
                        });
                    disconnect_jump_sessions(
                        jump_sessions,
                        "PortMate jump host key scan handshake failed",
                    )
                    .await;
                    return Err(message);
                }
            }
        } else {
            match connect_ssh_transport(
                SshTransportConnectParams {
                    config: config.clone(),
                    target_host: &jump_host,
                    target_port: jump_port,
                    proxy: &ssh.proxy,
                    tcp_keepalive_enabled: ssh.tcp_keepalive_enabled,
                    timeout: Duration::from_secs(12),
                    label: &jump_label,
                },
                jump_handler,
            )
            .await
            {
                Ok(session) => session,
                Err(SshTransportConnectError::Timeout) => {
                    return Err(format!(
                        "Jump Host host key 扫描连接超时: {jump_host}:{jump_port}"
                    ));
                }
                Err(SshTransportConnectError::Transport(error)) => return Err(error),
                Err(SshTransportConnectError::Handshake(error)) => {
                    if let Some(result) = host_key_scan_result_for_policy(
                        profile,
                        ssh,
                        &jump_policy,
                        &observed_jump_key,
                        &jump_label,
                        state,
                    )? {
                        return Ok(Some(result));
                    }
                    return Err(jump_key_error
                        .lock()
                        .ok()
                        .and_then(|reason| reason.clone())
                        .unwrap_or_else(|| format!("Jump Host host key 扫描连接失败: {error}")));
                }
            }
        };

        if let Err(error) = authenticate_ssh_with_timeout(
            &mut jump_session,
            SshAuthenticationRequest {
                ssh: jump_ssh,
                username: jump_username,
                password: jump_runtime_credential(password, jump.password_secret_ref.as_deref()),
                passphrase: jump_runtime_credential(
                    passphrase,
                    jump.passphrase_secret_ref.as_deref(),
                ),
                agent_socket_path: None,
                timeout: Duration::from_secs(12),
                disconnect_description: "PortMate jump host key scan authentication timeout",
            },
        )
        .await
        {
            disconnect_jump_sessions(jump_sessions, "PortMate jump host key scan auth failed")
                .await;
            let _ = request_ssh_disconnect_with_timeout(
                &jump_session,
                "PortMate jump host key scan auth failed",
            )
            .await;
            return Err(format!(
                "Jump Host 第 {} 跳 host key 扫描认证失败: {error}",
                index + 1
            ));
        }
        jump_sessions.push(jump_session);
    }

    let target_host = ssh.endpoint.host.trim().to_string();
    let jump_channel = match open_direct_tcpip_with_timeout(
        jump_sessions
            .last()
            .expect("non-empty jumps should create jump sessions"),
        target_host.clone(),
        ssh.endpoint.port,
        "127.0.0.1".to_string(),
        0,
        Duration::from_secs(12),
        "PortMate jump host key scan target channel timeout",
    )
    .await
    {
        Ok(channel) => channel,
        Err(DirectTcpipOpenError::Failed(error)) => {
            disconnect_jump_sessions(
                jump_sessions,
                "PortMate jump host key scan target channel failed",
            )
            .await;
            return Err(format!(
                "Jump Host 打开 host key 扫描通道到 {target_host}:{} 失败: {error}",
                ssh.endpoint.port
            ));
        }
        Err(DirectTcpipOpenError::TimedOut {
            timeout_ms,
            cleanup_warning,
        }) => {
            disconnect_jump_sessions(
                jump_sessions,
                "PortMate jump host key scan target channel timeout",
            )
            .await;
            let cleanup_warning = cleanup_warning
                .map(|warning| format!("; {warning}"))
                .unwrap_or_default();
            return Err(format!(
                "Jump Host 打开 host key 扫描通道到 {target_host}:{} 超时（{timeout_ms} ms）{cleanup_warning}",
                ssh.endpoint.port
            ));
        }
    };
    let target_session = match tokio::time::timeout(
        Duration::from_secs(12),
        client::connect_stream(config, jump_channel.into_stream(), target_handler),
    )
    .await
    {
        Ok(Ok(session)) => session,
        Err(_) => {
            disconnect_jump_sessions(jump_sessions, "PortMate host key scan target timeout").await;
            return Err(format!(
                "SSH 经 Jump Host host key 扫描超时: {target_host}:{}",
                ssh.endpoint.port
            ));
        }
        Ok(Err(error)) => {
            disconnect_jump_sessions(jump_sessions, "PortMate host key scan target failed").await;
            return Err(format!(
                "SSH 经 Jump Host host key 扫描失败: {target_host}:{}: {error}",
                ssh.endpoint.port
            ));
        }
    };
    let _ = target_session
        .disconnect(Disconnect::ByApplication, "PortMate host key scan", "en")
        .await;
    disconnect_jump_sessions(jump_sessions, "PortMate jump host key scan").await;
    Ok(None)
}

fn host_key_scan_result_for_policy(
    profile: &SessionProfile,
    ssh: &SshConnection,
    policy: &portmate_core::HostKeyPolicy,
    observed_key: &Arc<Mutex<Option<HostKeyObservation>>>,
    label: &str,
    state: &AppState,
) -> Result<Option<HostKeyScanResult>, String> {
    let Some(observation) = observed_key
        .lock()
        .map_err(|error| error.to_string())?
        .clone()
    else {
        return Ok(None);
    };
    let mut host_keys = {
        let store = state.store.lock().map_err(|error| error.to_string())?;
        store.host_keys.clone()
    };
    host_keys.keys.extend(ssh.trusted_host_keys.clone());
    host_keys
        .keys
        .extend(one_time_host_keys_snapshot(state, &profile.id)?);
    let evaluation = host_keys
        .evaluate(&profile.id, policy, &observation)
        .map_err(|error| error.to_string())?;
    Ok(Some(HostKeyScanResult {
        label: Some(label.to_string()),
        observation,
        evaluation,
    }))
}

fn bounded_log_query_limit(limit: Option<u64>) -> usize {
    limit
        .unwrap_or(DEFAULT_LOG_QUERY_LIMIT)
        .clamp(1, MAX_LOG_QUERY_LIMIT) as usize
}

fn runtime_tap_receiver(
    state: &AppState,
    session_id: &str,
) -> Result<broadcast::Receiver<Vec<u8>>, String> {
    if let Some(tap) = {
        let connections = state.ssh.lock().map_err(|error| error.to_string())?;
        connections
            .get(session_id)
            .map(|runtime| runtime.tap.clone())
    } {
        return Ok(tap.subscribe());
    }
    if let Some(tap) = {
        let connections = state.shell.lock().map_err(|error| error.to_string())?;
        connections
            .get(session_id)
            .map(|runtime| runtime.tap.clone())
    } {
        return Ok(tap.subscribe());
    }
    if let Some(tap) = {
        let connections = state.tcp.lock().map_err(|error| error.to_string())?;
        connections
            .get(session_id)
            .map(|runtime| runtime.tap.clone())
    } {
        return Ok(tap.subscribe());
    }
    if let Some(tap) = {
        let connections = state.serial.lock().map_err(|error| error.to_string())?;
        connections
            .get(session_id)
            .map(|runtime| runtime.tap.clone())
    } {
        return Ok(tap.subscribe());
    }
    Err("需要先连接会话才能执行 X/Y/ZModem 传输".to_string())
}

fn prepare_local_transfer_target_path(path: &Path, label: &str) -> Result<(), String> {
    reject_local_symlink_components(path, false, label)?;
    if let Some(parent) = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        fs::create_dir_all(parent)
            .map_err(|error| format!("创建{label}目录失败 {}: {error}", parent.display()))?;
    }
    reject_local_symlink_components(path, false, label)
}

fn portable_file_name(path: &str) -> Option<String> {
    let trimmed = path.trim().trim_end_matches(['/', '\\']);
    if trimmed.is_empty() {
        return None;
    }
    let without_drive = if trimmed.len() >= 2
        && trimmed.as_bytes()[0].is_ascii_alphabetic()
        && trimmed.as_bytes()[1] == b':'
    {
        &trimmed[2..]
    } else {
        trimmed
    };
    let name = without_drive
        .rsplit(['/', '\\'])
        .next()
        .unwrap_or_default()
        .trim();
    if name.is_empty()
        || matches!(name, "." | "..")
        || name
            .chars()
            .any(|character| character.is_control() || character == '\0')
    {
        return None;
    }
    Some(name.to_string())
}

enum FileOperation {
    CreateDirectory,
    CreateFile,
    Delete,
}

async fn list_files_inner(
    state: &AppState,
    request: ListFilesRequest,
) -> Result<Vec<FileEntry>, String> {
    if request.remote {
        let session_id = request
            .session_id
            .as_deref()
            .ok_or_else(|| "remote file list requires sessionId".to_string())?;
        let auxiliary = ssh_auxiliary_lease(state, session_id)?;
        let sftp = auxiliary.sftp().await?;
        list_remote_files(&sftp, &request.path).await
    } else {
        list_local_files(&request.path)
    }
}

async fn file_properties_inner(
    state: &AppState,
    request: FilePropertiesRequest,
) -> Result<FileProperties, String> {
    if request.path.trim().is_empty() {
        return Err("属性路径不能为空".to_string());
    }
    if request.remote {
        let session_id = request
            .session_id
            .as_deref()
            .ok_or_else(|| "remote file properties require sessionId".to_string())?;
        let auxiliary = ssh_auxiliary_lease(state, session_id)?;
        let sftp = auxiliary.sftp().await?;
        let result = remote_file_properties(&sftp, request.path.trim()).await;
        result
    } else {
        local_file_properties(request.path.trim())
    }
}

async fn file_operation_inner(
    state: &AppState,
    request: FileOperationRequest,
    operation: FileOperation,
) -> Result<(), String> {
    if request.remote {
        let session_id = request
            .session_id
            .as_deref()
            .ok_or_else(|| "remote file operation requires sessionId".to_string())?;
        let path = validate_remote_mutating_path(&request.path)?;
        let auxiliary = ssh_auxiliary_lease(state, session_id)?;
        let sftp = auxiliary.sftp().await?;
        let result = async {
            match operation {
                FileOperation::CreateDirectory => {
                    reject_remote_symlink_components(&sftp, &path, false, "远端目录创建路径")
                        .await?;
                    sftp_create_dir_all(&sftp, &path).await
                }
                FileOperation::CreateFile => {
                    reject_remote_symlink_components(&sftp, &path, false, "远端文件创建路径")
                        .await?;
                    let mut file = sftp
                        .open_with_flags(
                            path.clone(),
                            OpenFlags::CREATE | OpenFlags::EXCLUDE | OpenFlags::WRITE,
                        )
                        .await
                        .map_err(|error| format!("SFTP 新建远端文件失败 {path}: {error}"))?;
                    file.shutdown()
                        .await
                        .map_err(|error| format!("SFTP 关闭新建远端文件失败 {path}: {error}"))
                }
                FileOperation::Delete => {
                    reject_remote_symlink_components(&sftp, &path, true, "远端删除路径").await?;
                    sftp_remove_recursive(&sftp, &path).await
                }
            }
        }
        .await;
        result
    } else {
        match operation {
            FileOperation::CreateDirectory => {
                let path = validate_local_mutating_path(&request.path)?;
                reject_local_symlink_components(&path, false, "本地目录创建路径")?;
                fs::create_dir_all(&path)
                    .map_err(|error| format!("创建本地目录失败 {}: {error}", path.display()))
            }
            FileOperation::CreateFile => {
                let path = validate_local_mutating_path(&request.path)?;
                reject_local_symlink_components(&path, false, "本地文件创建路径")?;
                let mut options = OpenOptions::new();
                options.write(true).create_new(true);
                #[cfg(unix)]
                options.custom_flags(libc::O_NOFOLLOW);
                options
                    .open(&path)
                    .map(|_| ())
                    .map_err(|error| format!("新建本地文件失败 {}: {error}", path.display()))
            }
            FileOperation::Delete => {
                let path = validate_local_mutating_path(&request.path)?;
                reject_local_symlink_components(&path, true, "本地删除路径")?;
                let metadata = fs::symlink_metadata(&path)
                    .map_err(|error| format!("读取本地路径失败 {}: {error}", path.display()))?;
                if metadata.is_dir() {
                    fs::remove_dir_all(&path)
                        .map_err(|error| format!("删除本地目录失败 {}: {error}", path.display()))
                } else {
                    fs::remove_file(&path)
                        .map_err(|error| format!("删除本地文件失败 {}: {error}", path.display()))
                }
            }
        }
    }
}

#[derive(Debug)]
struct LocalDeletePath {
    source: PathBuf,
    identity: PathBuf,
    source_is_dir: bool,
}

#[derive(Debug)]
struct RemoteDeletePath {
    source: String,
    source_is_dir: bool,
}

fn prepare_local_delete_paths(paths: &[String]) -> Result<Vec<LocalDeletePath>, String> {
    validate_file_batch_path_count(paths)?;
    let mut identities = HashSet::new();
    let mut plan = Vec::with_capacity(paths.len());
    for raw_path in paths {
        let source = validate_local_mutating_path(raw_path)?;
        reject_local_symlink_components(&source, true, "本地批量删除路径")?;
        let metadata = fs::symlink_metadata(&source)
            .map_err(|error| format!("读取本地批量删除路径失败 {}: {error}", source.display()))?;
        let identity = canonical_local_entry_path(&source, "本地批量删除路径")?;
        if !identities.insert(identity.clone()) {
            return Err(format!("批量删除包含重复路径: {}", source.display()));
        }
        plan.push(LocalDeletePath {
            source,
            identity,
            source_is_dir: metadata.is_dir() && !metadata.file_type().is_symlink(),
        });
    }
    for directory in plan.iter().filter(|item| item.source_is_dir) {
        if let Some(nested) = plan.iter().find(|item| {
            item.identity != directory.identity && item.identity.starts_with(&directory.identity)
        }) {
            return Err(format!(
                "批量删除不能同时包含目录及其子项: {} 和 {}",
                directory.source.display(),
                nested.source.display()
            ));
        }
    }
    Ok(plan)
}

async fn prepare_remote_delete_paths(
    sftp: &SftpSession,
    paths: &[String],
) -> Result<Vec<RemoteDeletePath>, String> {
    validate_file_batch_path_count(paths)?;
    let mut sources = HashSet::new();
    let mut plan = Vec::with_capacity(paths.len());
    for raw_path in paths {
        let source = validate_remote_mutating_path(raw_path)?;
        let source = source.trim_end_matches('/').to_string();
        if !sources.insert(source.clone()) {
            return Err(format!("批量删除包含重复路径: {source}"));
        }
        reject_remote_symlink_components(sftp, &source, true, "远端批量删除路径").await?;
        let metadata = sftp
            .symlink_metadata(source.clone())
            .await
            .map_err(|error| format!("SFTP 读取远端批量删除路径失败 {source}: {error}"))?;
        plan.push(RemoteDeletePath {
            source,
            source_is_dir: metadata.is_dir() && !metadata.is_symlink(),
        });
    }
    for directory in plan.iter().filter(|item| item.source_is_dir) {
        if let Some(nested) = plan.iter().find(|item| {
            item.source != directory.source
                && remote_path_is_within(&item.source, &directory.source)
        }) {
            return Err(format!(
                "批量删除不能同时包含目录及其子项: {} 和 {}",
                directory.source, nested.source
            ));
        }
    }
    Ok(plan)
}

async fn delete_paths_inner(state: &AppState, request: DeletePathsRequest) -> Result<(), String> {
    validate_file_batch_path_count(&request.paths)?;
    if request.remote {
        let session_id = request
            .session_id
            .as_deref()
            .ok_or_else(|| "remote batch delete requires sessionId".to_string())?;
        let auxiliary = ssh_auxiliary_lease(state, session_id)?;
        let sftp = auxiliary.sftp().await?;
        let result = async {
            let plan = prepare_remote_delete_paths(&sftp, &request.paths).await?;
            for (completed, item) in plan.into_iter().enumerate() {
                reject_remote_symlink_components(
                    &sftp,
                    &item.source,
                    true,
                    "远端批量删除路径",
                )
                .await
                .map_err(|error| {
                    format!(
                        "SFTP 批量删除失败 {}: {error}; 已完成 {completed} 项，请刷新目录确认当前状态",
                        item.source
                    )
                })?;
                sftp_remove_recursive(&sftp, &item.source)
                    .await
                    .map_err(|error| {
                        format!(
                            "SFTP 批量删除失败 {}: {error}; 已完成 {completed} 项，请刷新目录确认当前状态",
                            item.source
                        )
                    })?;
            }
            Ok(())
        }
        .await;
        result
    } else {
        let plan = prepare_local_delete_paths(&request.paths)?;
        for (completed, item) in plan.into_iter().enumerate() {
            reject_local_symlink_components(&item.source, true, "本地批量删除路径").map_err(
                |error| {
                    format!(
                        "本地批量删除失败 {}: {error}; 已完成 {completed} 项，请刷新目录确认当前状态",
                        item.source.display()
                    )
                },
            )?;
            let metadata = fs::symlink_metadata(&item.source).map_err(|error| {
                format!(
                    "本地批量删除失败 {}: 读取路径失败 {error}; 已完成 {completed} 项，请刷新目录确认当前状态",
                    item.source.display()
                )
            })?;
            let result = if metadata.is_dir() && !metadata.file_type().is_symlink() {
                fs::remove_dir_all(&item.source)
            } else {
                fs::remove_file(&item.source)
            };
            result.map_err(|error| {
                format!(
                    "本地批量删除失败 {}: {error}; 已完成 {completed} 项，请刷新目录确认当前状态",
                    item.source.display()
                )
            })?;
        }
        Ok(())
    }
}

fn ensure_local_path_missing(path: &Path, label: &str) -> Result<(), String> {
    match fs::symlink_metadata(path) {
        Ok(_) => Err(format!("{label}已存在: {}", path.display())),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(format!("检查{label}失败 {}: {error}", path.display())),
    }
}

async fn ensure_remote_path_missing(
    sftp: &SftpSession,
    path: &str,
    label: &str,
) -> Result<(), String> {
    match sftp.symlink_metadata(path.to_string()).await {
        Ok(_) => Err(format!("{label}已存在: {path}")),
        Err(metadata_error) => match sftp.try_exists(path.to_string()).await {
            Ok(false) => Ok(()),
            Ok(true) => Err(format!("无法检查{label} {path}: {metadata_error}")),
            Err(exists_error) => Err(format!(
                "无法检查{label} {path}: {metadata_error}; existence check failed: {exists_error}"
            )),
        },
    }
}

fn rename_local_path_without_overwrite(source: &Path, target: &Path) -> Result<(), String> {
    #[cfg(target_os = "linux")]
    {
        use std::os::unix::ffi::OsStrExt;

        let source = CString::new(source.as_os_str().as_bytes())
            .map_err(|_| format!("本地移动源路径包含 NUL: {}", source.display()))?;
        let target = CString::new(target.as_os_str().as_bytes())
            .map_err(|_| format!("本地移动目标路径包含 NUL: {}", target.display()))?;
        // The C strings own stable NUL-terminated path bytes for this syscall.
        let status = unsafe {
            libc::syscall(
                libc::SYS_renameat2,
                libc::AT_FDCWD,
                source.as_ptr(),
                libc::AT_FDCWD,
                target.as_ptr(),
                libc::RENAME_NOREPLACE,
            )
        };
        if status == 0 {
            Ok(())
        } else {
            Err(std::io::Error::last_os_error().to_string())
        }
    }

    #[cfg(not(target_os = "linux"))]
    {
        fs::rename(source, target).map_err(|error| error.to_string())
    }
}

#[derive(Debug)]
struct LocalMovePath {
    source: PathBuf,
    source_identity: PathBuf,
    target: PathBuf,
    source_is_dir: bool,
}

#[derive(Debug)]
struct RemoteMovePath {
    source: String,
    target: String,
    source_is_dir: bool,
}

fn validate_file_batch_path_count(paths: &[String]) -> Result<(), String> {
    if paths.is_empty() {
        return Err("文件批量操作没有源路径".to_string());
    }
    if paths.len() > MAX_EXTERNAL_DROP_ROOTS {
        return Err(format!(
            "一次最多处理 {MAX_EXTERNAL_DROP_ROOTS} 个顶层路径，当前为 {} 个",
            paths.len()
        ));
    }
    Ok(())
}

fn canonical_local_entry_path(path: &Path, label: &str) -> Result<PathBuf, String> {
    let name = path
        .file_name()
        .filter(|name| !name.is_empty())
        .ok_or_else(|| format!("{label}没有文件名: {}", path.display()))?;
    let parent = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."));
    let parent = parent
        .canonicalize()
        .map_err(|error| format!("解析{label}父目录失败 {}: {error}", parent.display()))?;
    Ok(parent.join(name))
}

fn prepare_local_move_paths(
    paths: &[String],
    destination: &str,
) -> Result<Vec<LocalMovePath>, String> {
    validate_file_batch_path_count(paths)?;
    let destination = validate_local_mutating_path(destination)?;
    reject_local_symlink_components(&destination, false, "本地移动目标目录")?;
    let destination_metadata = fs::symlink_metadata(&destination).map_err(|error| {
        format!(
            "读取本地移动目标目录失败 {}: {error}",
            destination.display()
        )
    })?;
    if !destination_metadata.is_dir() || destination_metadata.file_type().is_symlink() {
        return Err(format!(
            "本地移动目标不是普通目录: {}",
            destination.display()
        ));
    }
    let destination = destination.canonicalize().map_err(|error| {
        format!(
            "解析本地移动目标目录失败 {}: {error}",
            destination.display()
        )
    })?;

    let mut sources = HashSet::new();
    let mut targets = HashSet::new();
    let mut plan = Vec::with_capacity(paths.len());
    for raw_path in paths {
        let source = validate_local_mutating_path(raw_path)?;
        reject_local_symlink_components(&source, true, "本地移动源路径")?;
        let metadata = fs::symlink_metadata(&source)
            .map_err(|error| format!("读取本地移动源路径失败 {}: {error}", source.display()))?;
        let source_identity = canonical_local_entry_path(&source, "本地移动源路径")?;
        if !sources.insert(source_identity.clone()) {
            return Err(format!("移动操作包含重复源路径: {}", source.display()));
        }
        let name = source
            .file_name()
            .filter(|name| !name.is_empty())
            .ok_or_else(|| format!("本地移动源路径没有文件名: {}", source.display()))?;
        let target = destination.join(name);
        if source_identity == target {
            return Err(format!("源路径已位于移动目标目录: {}", source.display()));
        }
        if metadata.is_dir()
            && !metadata.file_type().is_symlink()
            && destination.starts_with(&source_identity)
        {
            return Err(format!(
                "拒绝将目录移动到其自身内部: {} -> {}",
                source.display(),
                destination.display()
            ));
        }
        reject_local_symlink_components(&target, false, "本地移动目标路径")?;
        if !targets.insert(target.clone()) {
            return Err(format!("移动操作包含冲突目标路径: {}", target.display()));
        }
        ensure_local_path_missing(&target, "本地移动目标路径")?;
        plan.push(LocalMovePath {
            source,
            source_identity,
            target,
            source_is_dir: metadata.is_dir() && !metadata.file_type().is_symlink(),
        });
    }

    for directory in plan.iter().filter(|item| item.source_is_dir) {
        if let Some(nested) = plan.iter().find(|item| {
            item.source_identity != directory.source_identity
                && item.source_identity.starts_with(&directory.source_identity)
        }) {
            return Err(format!(
                "移动操作不能同时包含目录及其子项: {} 和 {}",
                directory.source.display(),
                nested.source.display()
            ));
        }
    }
    Ok(plan)
}

async fn prepare_remote_move_paths(
    sftp: &SftpSession,
    paths: &[String],
    destination: &str,
) -> Result<Vec<RemoteMovePath>, String> {
    validate_file_batch_path_count(paths)?;
    let destination = validate_remote_mutating_path(destination)?;
    let destination = destination.trim_end_matches('/').to_string();
    reject_remote_symlink_components(sftp, &destination, false, "远端移动目标目录").await?;
    let destination_metadata = sftp
        .symlink_metadata(destination.clone())
        .await
        .map_err(|error| format!("SFTP 读取远端移动目标目录失败 {destination}: {error}"))?;
    if !destination_metadata.is_dir() || destination_metadata.is_symlink() {
        return Err(format!("远端移动目标不是普通目录: {destination}"));
    }

    let mut sources = HashSet::new();
    let mut targets = HashSet::new();
    let mut plan = Vec::with_capacity(paths.len());
    for raw_path in paths {
        let source = validate_remote_mutating_path(raw_path)?;
        let source = source.trim_end_matches('/').to_string();
        if !sources.insert(source.clone()) {
            return Err(format!("移动操作包含重复源路径: {source}"));
        }
        reject_remote_symlink_components(sftp, &source, true, "远端移动源路径").await?;
        let metadata = sftp
            .symlink_metadata(source.clone())
            .await
            .map_err(|error| format!("SFTP 读取远端移动源路径失败 {source}: {error}"))?;
        let name = portable_file_name(&source)
            .ok_or_else(|| format!("远端移动源路径没有文件名: {source}"))?;
        let target = remote_join_path(&destination, &name);
        if source == target {
            return Err(format!("源路径已位于移动目标目录: {source}"));
        }
        if metadata.is_dir()
            && !metadata.is_symlink()
            && remote_path_is_within(&destination, &source)
        {
            return Err(format!(
                "拒绝将目录移动到其自身内部: {source} -> {destination}"
            ));
        }
        reject_remote_symlink_components(sftp, &target, false, "远端移动目标路径").await?;
        if !targets.insert(target.clone()) {
            return Err(format!("移动操作包含冲突目标路径: {target}"));
        }
        ensure_remote_path_missing(sftp, &target, "远端移动目标路径").await?;
        plan.push(RemoteMovePath {
            source,
            target,
            source_is_dir: metadata.is_dir() && !metadata.is_symlink(),
        });
    }

    for directory in plan.iter().filter(|item| item.source_is_dir) {
        if let Some(nested) = plan.iter().find(|item| {
            item.source != directory.source
                && remote_path_is_within(&item.source, &directory.source)
        }) {
            return Err(format!(
                "移动操作不能同时包含目录及其子项: {} 和 {}",
                directory.source, nested.source
            ));
        }
    }
    Ok(plan)
}

async fn move_paths_inner(state: &AppState, request: MovePathsRequest) -> Result<(), String> {
    if request.remote {
        let session_id = request
            .session_id
            .as_deref()
            .ok_or_else(|| "remote move requires sessionId".to_string())?;
        let auxiliary = ssh_auxiliary_lease(state, session_id)?;
        let sftp = auxiliary.sftp().await?;
        let result = async {
            let plan = prepare_remote_move_paths(&sftp, &request.paths, &request.destination).await?;
            for (completed, item) in plan.into_iter().enumerate() {
                sftp.rename(item.source.clone(), item.target.clone())
                    .await
                    .map_err(|error| {
                        format!(
                            "SFTP 移动失败 {} -> {}: {error}; 已完成 {completed} 项，请刷新目录确认当前状态",
                            item.source, item.target
                        )
                    })?;
            }
            Ok(())
        }
        .await;
        result
    } else {
        let plan = prepare_local_move_paths(&request.paths, &request.destination)?;
        for (completed, item) in plan.into_iter().enumerate() {
            rename_local_path_without_overwrite(&item.source, &item.target).map_err(|error| {
                format!(
                    "本地移动失败 {} -> {}: {error}; 已完成 {completed} 项，请刷新目录确认当前状态",
                    item.source.display(),
                    item.target.display()
                )
            })?;
        }
        Ok(())
    }
}

async fn rename_path_inner(state: &AppState, request: RenamePathRequest) -> Result<(), String> {
    if request.old_path.trim().is_empty() || request.new_path.trim().is_empty() {
        return Err("重命名路径不能为空".to_string());
    }
    if request.remote {
        let session_id = request
            .session_id
            .as_deref()
            .ok_or_else(|| "remote rename requires sessionId".to_string())?;
        let old_path = validate_remote_mutating_path(&request.old_path)?;
        let new_path = validate_remote_mutating_path(&request.new_path)?;
        if old_path.trim_end_matches('/') == new_path.trim_end_matches('/') {
            return Ok(());
        }
        let auxiliary = ssh_auxiliary_lease(state, session_id)?;
        let sftp = auxiliary.sftp().await?;
        let result = async {
            reject_remote_symlink_components(&sftp, &old_path, true, "远端重命名源路径").await?;
            reject_remote_symlink_components(&sftp, &new_path, false, "远端重命名目标路径").await?;
            ensure_remote_path_missing(&sftp, &new_path, "远端重命名目标路径").await?;
            sftp.rename(old_path.clone(), new_path.clone())
                .await
                .map_err(|error| format!("SFTP 重命名失败 {} -> {}: {error}", old_path, new_path))
        }
        .await;
        result
    } else {
        let old_path = validate_local_mutating_path(&request.old_path)?;
        let new_path = validate_local_mutating_path(&request.new_path)?;
        if old_path == new_path {
            return Ok(());
        }
        reject_local_symlink_components(&old_path, true, "本地重命名源路径")?;
        reject_local_symlink_components(&new_path, false, "本地重命名目标路径")?;
        ensure_local_path_missing(&new_path, "本地重命名目标路径")?;
        rename_local_path_without_overwrite(&old_path, &new_path).map_err(|error| {
            format!(
                "本地重命名失败 {} -> {}: {error}",
                old_path.display(),
                new_path.display()
            )
        })
    }
}

async fn chmod_path_inner(state: &AppState, request: ChmodPathRequest) -> Result<(), String> {
    if request.path.trim().is_empty() {
        return Err("权限路径不能为空".to_string());
    }
    if request.mode > 0o7777 {
        return Err("权限模式必须是 0000-7777 八进制范围".to_string());
    }
    if request.remote {
        let session_id = request
            .session_id
            .as_deref()
            .ok_or_else(|| "remote chmod requires sessionId".to_string())?;
        let path = validate_remote_mutating_path(&request.path)?;
        let auxiliary = ssh_auxiliary_lease(state, session_id)?;
        let sftp = auxiliary.sftp().await?;
        let result = async {
            reject_remote_symlink_components(&sftp, &path, false, "远端 chmod 路径").await?;
            let mut metadata = sftp
                .symlink_metadata(path.clone())
                .await
                .map_err(|error| format!("SFTP 读取权限失败 {path}: {error}"))?;
            if metadata.is_symlink() {
                return Err(format!("拒绝修改远端符号链接权限: {path}"));
            }
            let file_type_bits = metadata.permissions.unwrap_or(0) & 0o170000;
            metadata.permissions = Some(file_type_bits | request.mode);
            sftp.set_metadata(path.clone(), metadata)
                .await
                .map_err(|error| format!("SFTP 设置权限失败 {path}: {error}"))
        }
        .await;
        result
    } else {
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let path = validate_local_mutating_path(&request.path)?;
            reject_local_symlink_components(&path, false, "本地 chmod 路径")?;
            let metadata = fs::symlink_metadata(&path)
                .map_err(|error| format!("读取本地权限失败 {}: {error}", path.display()))?;
            if metadata.file_type().is_symlink() {
                return Err(format!("拒绝修改本地符号链接权限: {}", path.display()));
            }
            let mut permissions = metadata.permissions();
            permissions.set_mode(request.mode);
            fs::set_permissions(&path, permissions)
                .map_err(|error| format!("设置本地权限失败 {}: {error}", path.display()))
        }
        #[cfg(not(unix))]
        {
            let _ = state;
            Err("当前平台不支持本地 chmod".to_string())
        }
    }
}

fn ensure_tmux_control_capacity(
    controls: &HashMap<(String, String), TmuxControlRuntime>,
    control_key: &(String, String),
) -> Result<(), String> {
    if controls.contains_key(control_key) {
        return Ok(());
    }
    let session_count = controls
        .keys()
        .filter(|(session_id, _)| session_id == &control_key.0)
        .count();
    if session_count >= MAX_TMUX_CONTROLS_PER_SESSION {
        return Err(format!(
            "tmux control watcher count for session has reached {MAX_TMUX_CONTROLS_PER_SESSION}"
        ));
    }
    if controls.len() >= MAX_ACTIVE_TMUX_CONTROLS {
        return Err(format!(
            "tmux control watcher count has reached app limit ({MAX_ACTIVE_TMUX_CONTROLS})"
        ));
    }
    Ok(())
}

fn install_tmux_control_runtime(
    controls: &mut HashMap<(String, String), TmuxControlRuntime>,
    control_key: &(String, String),
    runtime: TmuxControlRuntime,
) -> Result<TmuxControlInstall, String> {
    if let Some(existing) = controls
        .get(control_key)
        .filter(|existing| !existing.cancel.load(Ordering::SeqCst))
    {
        return Ok(TmuxControlInstall::Existing(existing.clone()));
    }
    ensure_tmux_control_capacity(controls, control_key)?;
    Ok(TmuxControlInstall::Installed(
        controls.insert(control_key.clone(), runtime),
    ))
}

async fn start_tmux_control_inner(
    state: &AppState,
    session_id: &str,
    target: &str,
) -> Result<TmuxControlStatus, String> {
    let target = normalize_tmux_target(target)?.to_string();
    let control_key = (session_id.to_string(), target.clone());
    {
        let controls = state
            .tmux_controls
            .lock()
            .map_err(|error| error.to_string())?;
        if let Some(runtime) = controls
            .get(&control_key)
            .filter(|runtime| !runtime.cancel.load(Ordering::SeqCst))
        {
            return Ok(TmuxControlStatus {
                session_id: session_id.to_string(),
                target,
                active: true,
                runtime_id: Some(runtime.runtime_id.clone()),
            });
        }
        ensure_tmux_control_capacity(&controls, &control_key)?;
    }

    let control_slot = Arc::clone(&state.tmux_control_slots)
        .try_acquire_owned()
        .map_err(|_| format!("tmux control watcher limit reached ({MAX_ACTIVE_TMUX_CONTROLS})"))?;
    {
        let controls = state
            .tmux_controls
            .lock()
            .map_err(|error| error.to_string())?;
        if let Some(runtime) = controls
            .get(&control_key)
            .filter(|runtime| !runtime.cancel.load(Ordering::SeqCst))
        {
            return Ok(TmuxControlStatus {
                session_id: session_id.to_string(),
                target,
                active: true,
                runtime_id: Some(runtime.runtime_id.clone()),
            });
        }
        ensure_tmux_control_capacity(&controls, &control_key)?;
    }

    let auxiliary_lease = ssh_auxiliary_lease(state, session_id)?;
    let handle = auxiliary_lease.handle();
    let command = format!(
        "tmux -C attach-session -t {}",
        shell_quote(normalize_tmux_target(&target)?)
    );
    let mut channel = open_shared_ssh_exec_channel(
        &handle,
        &command,
        SSH_AUXILIARY_SETUP_TIMEOUT,
        "Tmux control-mode",
    )
    .await?;

    let runtime_id = Uuid::new_v4().to_string();
    let cancel = Arc::new(AtomicBool::new(false));
    let install_result = match state.tmux_controls.lock() {
        Ok(mut controls) => install_tmux_control_runtime(
            &mut controls,
            &control_key,
            TmuxControlRuntime {
                runtime_id: runtime_id.clone(),
                target: target.clone(),
                cancel: Arc::clone(&cancel),
            },
        ),
        Err(error) => Err(error.to_string()),
    };
    let previous = match install_result {
        Ok(TmuxControlInstall::Installed(previous)) => previous,
        Ok(TmuxControlInstall::Existing(existing)) => {
            close_ssh_channel_bounded(&channel).await;
            return Ok(TmuxControlStatus {
                session_id: session_id.to_string(),
                target,
                active: true,
                runtime_id: Some(existing.runtime_id),
            });
        }
        Err(error) => {
            close_ssh_channel_bounded(&channel).await;
            return Err(error);
        }
    };
    if let Some(previous) = previous {
        previous.cancel.store(true, Ordering::SeqCst);
    }

    let app_handle = state.app_handle.clone();
    let controls = Arc::clone(&state.tmux_controls);
    let event_context = TmuxControlEventContext {
        session_id: session_id.to_string(),
        target: target.clone(),
        runtime_id: runtime_id.clone(),
    };
    tauri::async_runtime::spawn(async move {
        event_context.emit(app_handle.as_ref(), "started", true, None, None);
        let mut parser = TmuxControlLineParser::default();
        let mut stderr = Vec::new();
        let mut pending_protocol_event = None;
        let mut first_pending_at = None;
        let mut last_pending_at = None;
        let mut stopped_error = None;
        let mut ticker = tokio::time::interval(Duration::from_millis(100));
        ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    if cancel.load(Ordering::SeqCst) {
                        break;
                    }
                    let now = Instant::now();
                    let quiet = last_pending_at
                        .is_some_and(|last: Instant| now.duration_since(last) >= TMUX_CONTROL_EVENT_DEBOUNCE);
                    let overdue = first_pending_at
                        .is_some_and(|first: Instant| now.duration_since(first) >= TMUX_CONTROL_EVENT_MAX_LATENCY);
                    if pending_protocol_event.is_some() && (quiet || overdue) {
                        event_context.emit(
                            app_handle.as_ref(),
                            "state-changed",
                            true,
                            pending_protocol_event,
                            None,
                        );
                        pending_protocol_event = None;
                        first_pending_at = None;
                        last_pending_at = None;
                    }
                }
                message = channel.wait() => {
                    match message {
                        Some(ChannelMsg::Data { data }) => match parser.push(&data) {
                            Ok(parsed) if parsed.changed => {
                                let now = Instant::now();
                                if first_pending_at.is_none() {
                                    first_pending_at = Some(now);
                                }
                                last_pending_at = Some(now);
                                pending_protocol_event = parsed.last_event;
                            }
                            Ok(_) => {}
                            Err(error) => {
                                stopped_error = Some(error);
                                break;
                            }
                        },
                        Some(ChannelMsg::ExtendedData { data, .. }) => {
                            if let Err(error) = append_bounded_ssh_exec_data(
                                &mut stderr,
                                &data,
                                MAX_TMUX_CONTROL_STDERR_BYTES,
                                "tmux control stderr",
                            ) {
                                stopped_error = Some(error);
                                break;
                            }
                        }
                        Some(ChannelMsg::Failure) => {
                            stopped_error = Some("远端拒绝启动 tmux control-mode".to_string());
                            break;
                        }
                        Some(ChannelMsg::ExitStatus { exit_status }) if exit_status != 0 => {
                            let detail = String::from_utf8_lossy(&stderr);
                            stopped_error = Some(if detail.trim().is_empty() {
                                format!("tmux control-mode 返回非零状态 {exit_status}")
                            } else {
                                format!("tmux control-mode 返回非零状态 {exit_status}: {}", detail.trim())
                            });
                            break;
                        }
                        Some(ChannelMsg::Eof | ChannelMsg::Close) | None => break,
                        _ => {}
                    }
                }
            }
        }

        if pending_protocol_event.is_some() {
            event_context.emit(
                app_handle.as_ref(),
                "state-changed",
                true,
                pending_protocol_event,
                None,
            );
        }
        close_ssh_channel_bounded(&channel).await;
        if let Ok(mut controls) = controls.lock() {
            let current = controls
                .get(&control_key)
                .is_some_and(|runtime| runtime.runtime_id == event_context.runtime_id);
            if current {
                controls.remove(&control_key);
            }
        }
        event_context.emit(
            app_handle.as_ref(),
            "stopped",
            false,
            None,
            stopped_error.as_deref(),
        );
        drop(auxiliary_lease);
        drop(control_slot);
    });

    Ok(TmuxControlStatus {
        session_id: session_id.to_string(),
        target,
        active: true,
        runtime_id: Some(runtime_id),
    })
}

fn stop_tmux_control_inner(
    state: &AppState,
    session_id: &str,
    target: Option<&str>,
) -> Result<TmuxControlStatus, String> {
    let (target, runtime_id) = if let Some(target) = target {
        let target = normalize_tmux_target(target)?.to_string();
        let runtime = cancel_tmux_control_runtime(state, session_id, &target)?;
        (target, runtime.map(|runtime| runtime.runtime_id))
    } else {
        let mut runtimes = cancel_tmux_control_runtimes_for_session(state, session_id)?;
        let target = if runtimes.len() == 1 {
            runtimes[0].target.clone()
        } else {
            String::new()
        };
        let runtime_id = if runtimes.len() == 1 {
            Some(runtimes.remove(0).runtime_id)
        } else {
            None
        };
        (target, runtime_id)
    };
    Ok(TmuxControlStatus {
        session_id: session_id.to_string(),
        target,
        active: false,
        runtime_id,
    })
}

fn cancel_tmux_control_runtime(
    state: &AppState,
    session_id: &str,
    target: &str,
) -> Result<Option<TmuxControlRuntime>, String> {
    let controls = state
        .tmux_controls
        .lock()
        .map_err(|error| error.to_string())?;
    let runtime = controls
        .get(&(session_id.to_string(), target.to_string()))
        .cloned();
    if let Some(runtime) = &runtime {
        runtime.cancel.store(true, Ordering::SeqCst);
    }
    Ok(runtime)
}

fn cancel_tmux_control_runtimes_for_session(
    state: &AppState,
    session_id: &str,
) -> Result<Vec<TmuxControlRuntime>, String> {
    let controls = state
        .tmux_controls
        .lock()
        .map_err(|error| error.to_string())?;
    let runtimes = controls
        .iter()
        .filter(|((candidate_session_id, _), _)| candidate_session_id == session_id)
        .map(|(_, runtime)| runtime.clone())
        .collect::<Vec<_>>();
    for runtime in &runtimes {
        runtime.cancel.store(true, Ordering::SeqCst);
    }
    Ok(runtimes)
}

fn shutdown_tmux_controls(state: &AppState) {
    if let Ok(mut controls) = state.tmux_controls.lock() {
        for (_, runtime) in controls.drain() {
            runtime.cancel.store(true, Ordering::SeqCst);
        }
    }
}

async fn list_tmux_state_inner(state: &AppState, session_id: &str) -> Result<TmuxState, String> {
    let auxiliary = ssh_auxiliary_lease(state, session_id)?;
    list_tmux_state_with_handle(auxiliary.handle()).await
}

async fn list_tmux_state_with_handle(
    handle: Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>,
) -> Result<TmuxState, String> {
    let sessions_output = exec_ssh_command_capture(
        Arc::clone(&handle),
        &format!(
            "tmux list-sessions -F '#{{session_name}}{TMUX_FIELD_SEPARATOR}#{{session_windows}}{TMUX_FIELD_SEPARATOR}#{{session_attached}}{TMUX_FIELD_SEPARATOR}#{{session_created}}' 2>/dev/null || true"
        ),
        Duration::from_secs(8),
    )
    .await?;
    let windows_output = exec_ssh_command_capture(
        Arc::clone(&handle),
        &format!(
            "tmux list-windows -a -F '#{{session_name}}{TMUX_FIELD_SEPARATOR}#{{window_index}}{TMUX_FIELD_SEPARATOR}#{{window_id}}{TMUX_FIELD_SEPARATOR}#{{window_name}}{TMUX_FIELD_SEPARATOR}#{{window_panes}}{TMUX_FIELD_SEPARATOR}#{{window_active}}' 2>/dev/null || true"
        ),
        Duration::from_secs(8),
    )
    .await?;
    let panes_output = exec_ssh_command_capture(
        handle,
        &format!(
            "tmux list-panes -a -F '#{{session_name}}{TMUX_FIELD_SEPARATOR}#{{window_index}}{TMUX_FIELD_SEPARATOR}#{{pane_index}}{TMUX_FIELD_SEPARATOR}#{{pane_id}}{TMUX_FIELD_SEPARATOR}#{{pane_active}}{TMUX_FIELD_SEPARATOR}#{{pane_current_command}}{TMUX_FIELD_SEPARATOR}#{{pane_title}}{TMUX_FIELD_SEPARATOR}#{{pane_synchronized}}' 2>/dev/null || true"
        ),
        Duration::from_secs(8),
    )
    .await?;

    let sessions = sessions_output
        .lines()
        .filter_map(parse_tmux_session)
        .collect::<Vec<_>>();
    let mut windows = windows_output
        .lines()
        .filter_map(parse_tmux_window)
        .collect::<Vec<_>>();
    let panes = panes_output
        .lines()
        .filter_map(parse_tmux_pane)
        .collect::<Vec<_>>();
    for window in &mut windows {
        let matching = panes
            .iter()
            .filter(|pane| {
                pane.session == window.session && pane.window_index == window.window_index
            })
            .collect::<Vec<_>>();
        window.synchronized = !matching.is_empty() && matching.iter().all(|pane| pane.synchronized);
    }
    Ok(TmuxState {
        sessions,
        windows,
        panes,
    })
}

async fn set_tmux_pane_sync_inner(
    state: &AppState,
    session_id: &str,
    target: &str,
    enabled: bool,
) -> Result<TmuxState, String> {
    let auxiliary = ssh_auxiliary_lease(state, session_id)?;
    let handle = auxiliary.handle();
    let command = tmux_pane_sync_command(target, enabled)?;
    let event_message = format!(
        "PortMate: tmux pane synchronization {} ({})",
        if enabled { "enabled" } else { "disabled" },
        normalize_tmux_target(target)?
    );
    exec_ssh_command_capture(Arc::clone(&handle), &command, Duration::from_secs(8)).await?;
    record_applied_system_event(
        state,
        session_id,
        event_message,
        "tmux pane synchronization",
    );
    list_tmux_state_with_handle(handle).await
}

async fn mutate_tmux_inner(
    state: &AppState,
    request: TmuxMutationRequest,
) -> Result<TmuxState, String> {
    let command = tmux_mutation_command(&request)?;
    let event_message = format!(
        "PortMate: tmux {} ({})",
        tmux_mutation_label(request.action),
        tmux_mutation_event_scope(&request)?
    );
    let auxiliary = ssh_auxiliary_lease(state, &request.session_id)?;
    let handle = auxiliary.handle();
    exec_ssh_command_capture(Arc::clone(&handle), &command, Duration::from_secs(8)).await?;
    record_applied_system_event(state, &request.session_id, event_message, "tmux mutation");
    list_tmux_state_with_handle(handle).await
}

fn list_local_files(path: &str) -> Result<Vec<FileEntry>, String> {
    let path = validate_native_local_path(if path.trim().is_empty() {
        "."
    } else {
        path.trim()
    })?;
    let mut entries = Vec::new();
    for entry in fs::read_dir(&path)
        .map_err(|error| format!("读取本地目录失败 {}: {error}", path.display()))?
    {
        let entry = entry.map_err(|error| format!("读取本地目录项失败: {error}"))?;
        let metadata = fs::symlink_metadata(entry.path())
            .map_err(|error| format!("读取本地文件元数据失败: {error}"))?;
        let modified = metadata
            .modified()
            .ok()
            .and_then(|time| time.duration_since(std::time::UNIX_EPOCH).ok())
            .map(|duration| {
                chrono::DateTime::<Utc>::from(std::time::UNIX_EPOCH + duration).to_rfc3339()
            });
        entries.push(FileEntry {
            name: entry.file_name().to_string_lossy().to_string(),
            path: entry.path().display().to_string(),
            is_dir: metadata.is_dir() && !metadata.file_type().is_symlink(),
            size: if metadata.is_file() && !metadata.file_type().is_symlink() {
                metadata.len()
            } else {
                0
            },
            modified,
        });
    }
    sort_file_entries(&mut entries);
    Ok(entries)
}

fn local_file_properties(path: &str) -> Result<FileProperties, String> {
    let path = validate_native_local_path(path)?;
    let metadata = fs::symlink_metadata(&path)
        .map_err(|error| format!("读取本地路径属性失败 {}: {error}", path.display()))?;
    let file_type = metadata.file_type();
    #[cfg(unix)]
    let permissions = {
        use std::os::unix::fs::PermissionsExt;
        Some(metadata.permissions().mode())
    };
    #[cfg(not(unix))]
    let permissions = None;
    Ok(FileProperties {
        name: path
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or_else(|| path.to_str().unwrap_or(""))
            .to_string(),
        path: path.display().to_string(),
        remote: false,
        kind: file_kind_label(
            metadata.is_dir(),
            metadata.is_file(),
            file_type.is_symlink(),
        ),
        is_dir: metadata.is_dir(),
        is_file: metadata.is_file(),
        is_symlink: file_type.is_symlink(),
        size: if metadata.is_file() {
            metadata.len()
        } else {
            0
        },
        permissions,
        modified: metadata.modified().ok().and_then(system_time_to_rfc3339),
        accessed: metadata.accessed().ok().and_then(system_time_to_rfc3339),
        created: metadata.created().ok().and_then(system_time_to_rfc3339),
    })
}

async fn list_remote_files(sftp: &SftpSession, path: &str) -> Result<Vec<FileEntry>, String> {
    let path = if path.trim().is_empty() {
        "."
    } else {
        path.trim()
    };
    list_remote_files_via_sftp(sftp, path).await
}

async fn list_remote_files_via_sftp(
    sftp: &SftpSession,
    path: &str,
) -> Result<Vec<FileEntry>, String> {
    let mut entries = Vec::new();
    for entry in sftp
        .read_dir(path.to_string())
        .await
        .map_err(|error| format!("SFTP 读取远端目录失败 {path}: {error}"))?
    {
        let metadata = entry.metadata();
        let name = entry.file_name();
        let modified = metadata
            .mtime
            .and_then(|timestamp| chrono::DateTime::<Utc>::from_timestamp(timestamp.into(), 0))
            .map(|value| value.to_rfc3339());
        entries.push(FileEntry {
            path: remote_join_path(path, &name),
            name,
            is_dir: metadata.is_dir(),
            size: if metadata.is_regular() {
                metadata.len()
            } else {
                0
            },
            modified,
        });
    }
    sort_file_entries(&mut entries);
    Ok(entries)
}

async fn remote_file_properties(sftp: &SftpSession, path: &str) -> Result<FileProperties, String> {
    let metadata = sftp
        .symlink_metadata(path.to_string())
        .await
        .map_err(|error| format!("SFTP 读取远端属性失败 {path}: {error}"))?;
    let is_dir = metadata.is_dir();
    let is_file = metadata.is_regular();
    let is_symlink = metadata.is_symlink();
    Ok(FileProperties {
        name: remote_file_name(path),
        path: path.to_string(),
        remote: true,
        kind: file_kind_label(is_dir, is_file, is_symlink),
        is_dir,
        is_file,
        is_symlink,
        size: if is_file { metadata.len() } else { 0 },
        permissions: metadata.permissions,
        modified: metadata
            .mtime
            .and_then(|timestamp| chrono::DateTime::<Utc>::from_timestamp(timestamp.into(), 0))
            .map(|value| value.to_rfc3339()),
        accessed: None,
        created: None,
    })
}

fn file_kind_label(is_dir: bool, is_file: bool, is_symlink: bool) -> String {
    if is_symlink {
        "symlink"
    } else if is_dir {
        "directory"
    } else if is_file {
        "file"
    } else {
        "other"
    }
    .to_string()
}

fn system_time_to_rfc3339(time: std::time::SystemTime) -> Option<String> {
    time.duration_since(std::time::UNIX_EPOCH)
        .ok()
        .map(|duration| {
            chrono::DateTime::<Utc>::from(std::time::UNIX_EPOCH + duration).to_rfc3339()
        })
}

async fn sftp_remove_recursive(sftp: &SftpSession, path: &str) -> Result<(), String> {
    let path = validate_remote_mutating_path(path)?;
    let mut stack = vec![(path.to_string(), false)];

    while let Some((current, visited)) = stack.pop() {
        let metadata = sftp
            .symlink_metadata(current.clone())
            .await
            .map_err(|error| format!("SFTP 读取远端路径失败 {current}: {error}"))?;
        let is_directory = metadata.is_dir() && !metadata.is_symlink();
        if is_directory && !visited {
            stack.push((current.clone(), true));
            let entries = sftp
                .read_dir(current.clone())
                .await
                .map_err(|error| format!("SFTP 读取远端目录失败 {current}: {error}"))?;
            for entry in entries {
                stack.push((remote_join_path(&current, &entry.file_name()), false));
            }
            continue;
        }

        if is_directory {
            sftp.remove_dir(current.clone())
                .await
                .map_err(|error| format!("SFTP 删除远端目录失败 {current}: {error}"))?;
        } else {
            sftp.remove_file(current.clone())
                .await
                .map_err(|error| format!("SFTP 删除远端文件失败 {current}: {error}"))?;
        }
    }

    Ok(())
}

fn validate_remote_mutating_path(path: &str) -> Result<String, String> {
    let path = path.trim();
    let trimmed = path.trim_end_matches('/');
    if path.is_empty()
        || trimmed.is_empty()
        || matches!(trimmed, "." | ".." | "~" | "/" | "//")
        || path.contains('\0')
    {
        return Err("拒绝操作空路径、根目录或当前目录".to_string());
    }
    if remote_path_has_dot_components(trimmed) {
        return Err("拒绝包含 . 或 .. 路径分量的远端变更路径".to_string());
    }
    Ok(path.to_string())
}

/// Guards local delete/rename endpoints against the two most catastrophic
/// fat-finger paths: an empty/`.`/`~` path, and a path that resolves to a
/// filesystem root or to the user's home directory itself.
fn validate_local_mutating_path(path: &str) -> Result<PathBuf, String> {
    let trimmed = path.trim();
    let trimmed_slashes = trimmed.trim_end_matches(['/', '\\']);
    if trimmed.is_empty()
        || trimmed_slashes.is_empty()
        || matches!(trimmed_slashes, "." | ".." | "~")
        || trimmed.contains('\0')
    {
        return Err("拒绝操作空路径、根目录或当前目录".to_string());
    }
    if trimmed
        .split(['/', '\\'])
        .any(|component| matches!(component, "." | ".."))
    {
        return Err("拒绝包含 . 或 .. 路径分量的本地变更路径".to_string());
    }

    let candidate = validate_native_local_path(trimmed)?;
    if candidate.parent().is_none() || is_local_filesystem_root(&candidate) {
        return Err("拒绝操作文件系统根目录".to_string());
    }
    if candidate.components().any(|component| {
        matches!(
            component,
            std::path::Component::CurDir | std::path::Component::ParentDir
        )
    }) {
        return Err("拒绝包含 . 或 .. 路径分量的本地变更路径".to_string());
    }
    if let Some(home) = std::env::var_os("HOME").or_else(|| std::env::var_os("USERPROFILE")) {
        let home = PathBuf::from(home);
        let candidate_check = candidate
            .canonicalize()
            .unwrap_or_else(|_| candidate.clone());
        let home_check = home.canonicalize().unwrap_or(home);
        if candidate_check == home_check {
            return Err("拒绝操作用户主目录".to_string());
        }
    }
    Ok(candidate)
}

fn reject_local_symlink_components(
    path: &Path,
    allow_final_symlink: bool,
    label: &str,
) -> Result<(), String> {
    let component_count = path.components().count();
    let mut current = PathBuf::new();
    for (index, component) in path.components().enumerate() {
        current.push(component.as_os_str());
        match fs::symlink_metadata(&current) {
            Ok(metadata)
                if metadata.file_type().is_symlink()
                    && !(allow_final_symlink && index + 1 == component_count) =>
            {
                return Err(format!("{label}不能经过符号链接: {}", current.display()));
            }
            Ok(_) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => break,
            Err(error) => {
                return Err(format!("检查{label}失败 {}: {error}", current.display()));
            }
        }
    }
    Ok(())
}

fn validate_native_local_path(path: &str) -> Result<PathBuf, String> {
    let trimmed = path.trim();
    if trimmed.is_empty() || trimmed.contains('\0') {
        return Err("本地路径不能为空或包含 NUL".to_string());
    }
    match classify_local_transfer_path(trimmed, current_local_transfer_path_platform()) {
        LocalTransferPathKind::Relative | LocalTransferPathKind::Absolute => {
            Ok(expand_identity_path(trimmed))
        }
        LocalTransferPathKind::RootedWithoutDrive => {
            Err("Windows 本地路径必须包含盘符或完整 UNC 前缀".to_string())
        }
        LocalTransferPathKind::DriveRelative => {
            Err("Windows 本地路径不能使用 drive-relative 形式".to_string())
        }
        LocalTransferPathKind::ForeignAnchored => Err("本地路径与当前操作系统不兼容".to_string()),
    }
}

fn is_local_filesystem_root(path: &Path) -> bool {
    path.has_root() && path.file_name().is_none()
}

fn sort_file_entries(entries: &mut [FileEntry]) {
    entries.sort_by(|a, b| {
        b.is_dir
            .cmp(&a.is_dir)
            .then_with(|| a.name.to_lowercase().cmp(&b.name.to_lowercase()))
    });
}

async fn close_ssh_channel_bounded(channel: &Channel<client::Msg>) {
    let _ = tokio::time::timeout(SSH_SETUP_TIMEOUT_DISCONNECT_TIMEOUT, channel.close()).await;
}

fn shell_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\\''"))
}

async fn create_tunnel_inner(
    state: &AppState,
    request: CreateTunnelRequest,
) -> Result<TunnelSpec, String> {
    let request = normalize_tunnel_request(request)?;
    ensure_tunnel_creation_capacity(state, &request.session_id)?;
    let tunnel = TunnelSpec {
        id: Uuid::new_v4().to_string(),
        label: request.label.clone().unwrap_or_else(|| {
            tunnel_label(
                request.mode,
                &request.bind_host,
                request.bind_port,
                &request.target_host,
                request.target_port,
            )
        }),
        mode: request.mode,
        bind_host: request.bind_host.clone(),
        bind_port: request.bind_port,
        target_host: request.target_host.clone(),
        target_port: request.target_port,
        enabled: true,
    };
    validate_tunnels(std::slice::from_ref(&tunnel))?;
    let (tunnel, local_addr, ssh_runtime_id) = start_tunnel_runtime(
        state,
        &request.session_id,
        tunnel,
        request.label.is_none(),
        None,
    )
    .await?;
    commit_started_tunnel(
        state,
        &request.session_id,
        tunnel,
        local_addr,
        &ssh_runtime_id,
    )
    .await
}

fn ensure_tunnel_creation_capacity(state: &AppState, session_id: &str) -> Result<(), String> {
    let store = state.store.lock().map_err(|error| error.to_string())?;
    let profile = store
        .profile(session_id)
        .ok_or_else(|| format!("unknown session: {session_id}"))?;
    let tunnels = match profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => ssh.tunnels,
        _ => return Err("tunnels require an SSH or Tmux session".to_string()),
    };
    if tunnels.iter().filter(|tunnel| tunnel.enabled).count() >= MAX_TUNNELS_PER_PROFILE {
        return Err(format!(
            "enabled tunnel count has reached {MAX_TUNNELS_PER_PROFILE}"
        ));
    }
    Ok(())
}

async fn start_tunnel_runtime(
    state: &AppState,
    session_id: &str,
    mut tunnel: TunnelSpec,
    relabel_assigned_port: bool,
    expected_runtime_id: Option<&str>,
) -> Result<(TunnelSpec, Option<std::net::SocketAddr>, String), String> {
    validate_tunnels(std::slice::from_ref(&tunnel))?;
    let (handle, remote_forwards, ssh_runtime_id) = {
        let connections = state.ssh.lock().map_err(|error| error.to_string())?;
        let runtime = connections
            .get(session_id)
            .filter(|runtime| {
                expected_runtime_id.is_none_or(|expected| runtime.runtime_id == expected)
            })
            .ok_or_else(|| "需要先连接 SSH/Tmux 会话才能创建 tunnel".to_string())?;
        let store = state.store.lock().map_err(|error| error.to_string())?;
        if !store.runtimes.iter().any(|summary| {
            summary.session_id == session_id && summary.status == SessionStatus::Connected
        }) {
            return Err("需要先连接 SSH/Tmux 会话才能创建 tunnel".to_string());
        }
        (
            Arc::clone(&runtime.handle),
            Arc::clone(&runtime.remote_forwards),
            runtime.runtime_id.clone(),
        )
    };

    if tunnel.id.trim().is_empty() {
        return Err("tunnel requires an id".to_string());
    }
    {
        let tunnels = state.tunnels.lock().map_err(|error| error.to_string())?;
        ensure_tunnel_runtime_slot(&tunnels, &tunnel.id)?;
    }

    if tunnel.mode == TunnelMode::Remote {
        if tunnel.target_host.trim().is_empty() || tunnel.target_port == 0 {
            return Err("remote tunnel requires a local target host and port".to_string());
        }
        let returned_port = {
            let handle = handle.lock().await;
            handle
                .tcpip_forward(tunnel.bind_host.clone(), u32::from(tunnel.bind_port))
                .await
                .map_err(|error| {
                    format!(
                        "remote SSH tunnel request failed {}:{}: {error}",
                        tunnel.bind_host, tunnel.bind_port
                    )
                })?
        };
        if tunnel.bind_port == 0 && returned_port > 0 {
            tunnel.bind_port = returned_port as u16;
            if relabel_assigned_port {
                tunnel.label = tunnel_label(
                    tunnel.mode,
                    &tunnel.bind_host,
                    tunnel.bind_port,
                    &tunnel.target_host,
                    tunnel.target_port,
                );
            }
        }
        let metrics = Arc::new(TunnelMetrics::default());
        let closed = Arc::new(AtomicBool::new(false));
        let install_result = (|| {
            let connections = state.ssh.lock().map_err(|error| error.to_string())?;
            if connections
                .get(session_id)
                .is_none_or(|runtime| runtime.runtime_id != ssh_runtime_id)
            {
                return Err("SSH runtime changed while creating tunnel".to_string());
            }
            let store = state.store.lock().map_err(|error| error.to_string())?;
            if !store.runtimes.iter().any(|runtime| {
                runtime.session_id == session_id && runtime.status == SessionStatus::Connected
            }) {
                return Err("SSH session disconnected while creating tunnel".to_string());
            }
            let mut tunnels = state.tunnels.lock().map_err(|error| error.to_string())?;
            ensure_tunnel_runtime_slot(&tunnels, &tunnel.id)?;
            let mut forwards = remote_forwards.lock().map_err(|error| error.to_string())?;
            let target = TunnelForwardTarget {
                spec: tunnel.clone(),
                metrics: Arc::clone(&metrics),
                connection_slots: Arc::clone(&state.tunnel_connection_slots),
            };
            forwards.insert(
                remote_forward_key(&tunnel.bind_host, tunnel.bind_port),
                target.clone(),
            );
            forwards.insert(remote_forward_port_key(tunnel.bind_port), target);
            tunnels.insert(
                tunnel.id.clone(),
                TunnelRuntime {
                    session_id: session_id.to_string(),
                    ssh_runtime_id: ssh_runtime_id.clone(),
                    spec: tunnel.clone(),
                    metrics: Arc::clone(&metrics),
                    closed: Arc::clone(&closed),
                },
            );
            Ok::<(), String>(())
        })();
        if let Err(error) = install_result {
            let warnings = cancel_remote_tunnel_forward(
                Arc::clone(&handle),
                Arc::clone(&remote_forwards),
                &tunnel,
            )
            .await;
            return Err(if warnings.is_empty() {
                error
            } else {
                format!(
                    "{error}; remote tunnel cleanup failed: {}",
                    warnings.join("; ")
                )
            });
        }
        spawn_remote_tunnel_health_monitor(state.clone(), tunnel.id.clone(), Arc::clone(&closed));
        return Ok((tunnel, None, ssh_runtime_id));
    }

    let listener = TcpListener::bind((tunnel.bind_host.clone(), tunnel.bind_port))
        .await
        .map_err(|error| {
            format!(
                "SSH tunnel bind failed {}:{}: {error}",
                tunnel.bind_host, tunnel.bind_port
            )
        })?;
    let local_addr = listener
        .local_addr()
        .map_err(|error| format!("SSH tunnel local addr failed: {error}"))?;
    if tunnel.bind_port == 0 {
        tunnel.bind_port = local_addr.port();
        if relabel_assigned_port {
            tunnel.label = tunnel_label(
                tunnel.mode,
                &tunnel.bind_host,
                tunnel.bind_port,
                &tunnel.target_host,
                tunnel.target_port,
            );
        }
    }
    let closed = Arc::new(AtomicBool::new(false));
    let metrics = Arc::new(TunnelMetrics::default());
    let connection_slots = Arc::clone(&state.tunnel_connection_slots);
    {
        let connections = state.ssh.lock().map_err(|error| error.to_string())?;
        if connections
            .get(session_id)
            .is_none_or(|runtime| runtime.runtime_id != ssh_runtime_id)
        {
            return Err("SSH runtime changed while creating tunnel".to_string());
        }
        let store = state.store.lock().map_err(|error| error.to_string())?;
        if !store.runtimes.iter().any(|runtime| {
            runtime.session_id == session_id && runtime.status == SessionStatus::Connected
        }) {
            return Err("SSH session disconnected while creating tunnel".to_string());
        }
        let mut tunnels = state.tunnels.lock().map_err(|error| error.to_string())?;
        ensure_tunnel_runtime_slot(&tunnels, &tunnel.id)?;
        tunnels.insert(
            tunnel.id.clone(),
            TunnelRuntime {
                session_id: session_id.to_string(),
                ssh_runtime_id: ssh_runtime_id.clone(),
                spec: tunnel.clone(),
                metrics: Arc::clone(&metrics),
                closed: Arc::clone(&closed),
            },
        );
    }

    let session_id = session_id.to_string();
    let store = Arc::clone(&state.store);
    let store_path = state.store_path.clone();
    let tunnel_registry = Arc::clone(&state.tunnels);
    let tunnel_for_task = tunnel.clone();
    let ssh_runtime_id_for_task = ssh_runtime_id.clone();
    tauri::async_runtime::spawn(async move {
        loop {
            if closed.load(Ordering::SeqCst) {
                break;
            }
            match tokio::time::timeout(Duration::from_millis(500), listener.accept()).await {
                Ok(Ok((stream, peer))) => {
                    let Some(permit) =
                        try_acquire_tunnel_connection(&connection_slots, metrics.as_ref())
                    else {
                        continue;
                    };
                    let handle = handle.clone();
                    let spec = tunnel_for_task.clone();
                    let metrics = Arc::clone(&metrics);
                    let store = Arc::clone(&store);
                    let store_path = store_path.clone();
                    let session_id = session_id.clone();
                    tauri::async_runtime::spawn(async move {
                        let _permit = permit;
                        metrics.connection_opened();
                        let result = if spec.mode == TunnelMode::Dynamic {
                            handle_dynamic_tunnel_client(handle, stream, peer, Arc::clone(&metrics))
                                .await
                        } else {
                            handle_local_tunnel_client(
                                handle,
                                spec,
                                stream,
                                peer,
                                Arc::clone(&metrics),
                            )
                            .await
                        };
                        match result {
                            Ok(()) => {
                                metrics.clear_error();
                                metrics.connection_closed();
                            }
                            Err(error) => {
                                metrics.record_error(&error);
                                metrics.connection_closed();
                                if let Ok(mut store) = store.lock() {
                                    store.record_system_event(
                                        &session_id,
                                        format!("PortMate: SSH tunnel client failed: {error}"),
                                    );
                                    if let Err(error) = persist_applied_store(
                                        &store,
                                        &store_path,
                                        "tunnel client failure event",
                                    ) {
                                        eprintln!(
                                            "PortMate: failed to persist tunnel client error: {error}"
                                        );
                                    }
                                }
                            }
                        }
                    });
                }
                Ok(Err(error)) => {
                    let message = format!("SSH tunnel accept failed: {error}");
                    let removed = match fail_tunnel_runtime_if_owned(
                        &tunnel_registry,
                        &tunnel_for_task.id,
                        &ssh_runtime_id_for_task,
                        &message,
                    ) {
                        Ok(Some(_)) => true,
                        Ok(None) => false,
                        Err(registry_error) => {
                            closed.store(true, Ordering::SeqCst);
                            metrics.record_error(&format!("{message}; {registry_error}"));
                            false
                        }
                    };
                    if removed {
                        if let Ok(mut store) = store.lock() {
                            let mut stopped = tunnel_for_task.clone();
                            stopped.enabled = false;
                            mark_tunnel_stopped_in_store(&mut store, &session_id, &stopped);
                            store.record_system_event(&session_id, format!("PortMate: {message}"));
                            if let Err(error) = persist_applied_store(
                                &store,
                                &store_path,
                                "failed tunnel listener state",
                            ) {
                                eprintln!(
                                    "PortMate: failed to persist tunnel listener failure: {error}"
                                );
                            }
                        }
                    }
                    break;
                }
                Err(_) => {}
            }
        }
    });

    Ok((tunnel, Some(local_addr), ssh_runtime_id))
}

fn ensure_tunnel_runtime_slot(
    tunnels: &HashMap<String, TunnelRuntime>,
    tunnel_id: &str,
) -> Result<(), String> {
    if tunnels.contains_key(tunnel_id) {
        return Err(format!("tunnel already running: {tunnel_id}"));
    }
    if tunnels.len() >= MAX_ACTIVE_TUNNELS {
        return Err(format!(
            "active tunnel count has reached {MAX_ACTIVE_TUNNELS}"
        ));
    }
    Ok(())
}

async fn commit_started_tunnel(
    state: &AppState,
    session_id: &str,
    tunnel: TunnelSpec,
    local_addr: Option<std::net::SocketAddr>,
    ssh_runtime_id: &str,
) -> Result<TunnelSpec, String> {
    if let Err(commit_error) =
        persist_tunnel_to_profile_and_log(state, session_id, &tunnel, local_addr)
    {
        let cleanup = stop_tunnel_runtime_effects(state, &tunnel.id, ssh_runtime_id).await;
        return Err(match cleanup {
            Ok((_, warnings)) if warnings.is_empty() => format!(
                "tunnel Store commit failed and the uncommitted runtime was closed: {commit_error}"
            ),
            Ok((_, warnings)) => format!(
                "tunnel Store commit failed: {commit_error}; runtime cleanup warnings: {}",
                warnings.join("; ")
            ),
            Err(cleanup_error) => format!(
                "tunnel Store commit failed: {commit_error}; runtime cleanup failed: {cleanup_error}"
            ),
        });
    }
    Ok(tunnel)
}

fn spawn_remote_tunnel_health_monitor(state: AppState, tunnel_id: String, closed: Arc<AtomicBool>) {
    tauri::async_runtime::spawn(async move {
        loop {
            tokio::time::sleep(REMOTE_TUNNEL_HEALTH_INTERVAL).await;
            if closed.load(Ordering::SeqCst) {
                break;
            }
            match check_remote_tunnel_health(&state, &tunnel_id).await {
                Ok(RemoteTunnelHealth::Unsupported) => break,
                Ok(RemoteTunnelHealth::Healthy | RemoteTunnelHealth::Restored) => {}
                Err(error) => {
                    eprintln!("PortMate: remote tunnel health check failed: {error}");
                }
            }
        }
    });
}

async fn check_remote_tunnel_health(
    state: &AppState,
    tunnel_id: &str,
) -> Result<RemoteTunnelHealth, String> {
    let runtime = {
        let tunnels = state.tunnels.lock().map_err(|error| error.to_string())?;
        tunnels
            .get(tunnel_id)
            .cloned()
            .ok_or_else(|| format!("tunnel not found: {tunnel_id}"))?
    };
    if runtime.spec.mode != TunnelMode::Remote {
        return Err(format!("tunnel is not a remote forward: {tunnel_id}"));
    }
    if runtime.closed.load(Ordering::SeqCst) {
        return Err(format!("remote tunnel is closed: {tunnel_id}"));
    }

    let result = probe_remote_tunnel_health(state, &runtime).await;
    match &result {
        Ok(RemoteTunnelHealth::Healthy) => {
            if runtime
                .metrics
                .clear_error_with_prefix(REMOTE_TUNNEL_HEALTH_ERROR_PREFIX)
            {
                record_tunnel_health_event(
                    state,
                    &runtime.session_id,
                    tunnel_id,
                    "remote forward is healthy again",
                );
            }
        }
        Ok(RemoteTunnelHealth::Restored) => {
            runtime
                .metrics
                .clear_error_with_prefix(REMOTE_TUNNEL_HEALTH_ERROR_PREFIX);
            record_tunnel_health_event(
                state,
                &runtime.session_id,
                tunnel_id,
                "remote forward listener was missing and has been restored",
            );
        }
        Ok(RemoteTunnelHealth::Unsupported) => {}
        Err(error) => {
            let message = format!("{REMOTE_TUNNEL_HEALTH_ERROR_PREFIX} {error}");
            if runtime.metrics.record_error_if_changed(&message) {
                record_tunnel_health_event(state, &runtime.session_id, tunnel_id, &message);
            }
        }
    }
    result
}

async fn probe_remote_tunnel_health(
    state: &AppState,
    runtime: &TunnelRuntime,
) -> Result<RemoteTunnelHealth, String> {
    let _auxiliary_slot = acquire_ssh_auxiliary_slot(state)?;
    let (handle, remote_forwards) = {
        let connections = state.ssh.lock().map_err(|error| error.to_string())?;
        connections
            .get(&runtime.session_id)
            .filter(|ssh| ssh.runtime_id == runtime.ssh_runtime_id)
            .map(|ssh| (Arc::clone(&ssh.handle), Arc::clone(&ssh.remote_forwards)))
            .ok_or_else(|| format!("SSH runtime is unavailable for {}", runtime.session_id))?
    };

    let mut routing_restored = false;
    {
        let mut forwards = remote_forwards.lock().map_err(|error| error.to_string())?;
        let exact_key = remote_forward_key(&runtime.spec.bind_host, runtime.spec.bind_port);
        let port_key = remote_forward_port_key(runtime.spec.bind_port);
        if !forwards.contains_key(&exact_key) || !forwards.contains_key(&port_key) {
            let target = TunnelForwardTarget {
                spec: runtime.spec.clone(),
                metrics: Arc::clone(&runtime.metrics),
                connection_slots: Arc::clone(&state.tunnel_connection_slots),
            };
            forwards.insert(exact_key, target.clone());
            forwards.insert(port_key, target);
            routing_restored = true;
        }
    }

    let output = match exec_ssh_command_capture(
        Arc::clone(&handle),
        REMOTE_TUNNEL_PROBE_COMMAND,
        REMOTE_TUNNEL_HEALTH_TIMEOUT,
    )
    .await
    {
        Ok(output) => output,
        Err(error) if error.starts_with("SSH exec 返回非零状态") => {
            return Ok(RemoteTunnelHealth::Unsupported);
        }
        Err(error) => return Err(format!("listener probe failed: {error}")),
    };
    match parse_remote_listener_probe(&output, runtime.spec.bind_port) {
        RemoteListenerProbe::Listening => Ok(if routing_restored {
            RemoteTunnelHealth::Restored
        } else {
            RemoteTunnelHealth::Healthy
        }),
        RemoteListenerProbe::Unsupported => Ok(RemoteTunnelHealth::Unsupported),
        RemoteListenerProbe::Missing => {
            if runtime.closed.load(Ordering::SeqCst) {
                return Err("tunnel closed during listener probe".to_string());
            }
            let returned_port = {
                let handle = handle.lock().await;
                if runtime.closed.load(Ordering::SeqCst) {
                    return Err("tunnel closed before listener restore".to_string());
                }
                handle
                    .tcpip_forward(
                        runtime.spec.bind_host.clone(),
                        u32::from(runtime.spec.bind_port),
                    )
                    .await
                    .map_err(|error| {
                        format!(
                            "listener restore failed {}:{}: {error}",
                            runtime.spec.bind_host, runtime.spec.bind_port
                        )
                    })?
            };
            if returned_port != 0 && returned_port != u32::from(runtime.spec.bind_port) {
                return Err(format!(
                    "listener restore returned unexpected port {returned_port} for {}",
                    runtime.spec.bind_port
                ));
            }
            Ok(RemoteTunnelHealth::Restored)
        }
    }
}

fn parse_remote_listener_probe(output: &str, port: u16) -> RemoteListenerProbe {
    if output.contains("__PORTMATE_UNSUPPORTED__") {
        return RemoteListenerProbe::Unsupported;
    }
    if let Some((_, table)) = output.split_once("__PORTMATE_PROC__") {
        let expected_port = format!("{port:04X}");
        let listening = table.lines().any(|line| {
            let fields = line.split_whitespace().collect::<Vec<_>>();
            fields.len() > 3
                && fields[3] == "0A"
                && fields[1]
                    .rsplit_once(':')
                    .is_some_and(|(_, value)| value.eq_ignore_ascii_case(&expected_port))
        });
        return if listening {
            RemoteListenerProbe::Listening
        } else {
            RemoteListenerProbe::Missing
        };
    }
    if output.contains("__PORTMATE_SOCKSTAT__") {
        let listening = output
            .lines()
            .skip_while(|line| !line.contains("__PORTMATE_SOCKSTAT__"))
            .skip(1)
            .any(|line| {
                !line.to_ascii_uppercase().contains("LOCAL ADDRESS")
                    && line
                        .split_whitespace()
                        .any(|field| socket_endpoint_port(field) == Some(port))
            });
        return if listening {
            RemoteListenerProbe::Listening
        } else {
            RemoteListenerProbe::Missing
        };
    }
    if output.contains("__PORTMATE_SS__")
        || output.contains("__PORTMATE_LSOF__")
        || output.contains("__PORTMATE_NETSTAT__")
    {
        let listening = output.lines().any(|line| {
            line.to_ascii_uppercase().contains("LISTEN")
                && line
                    .split_whitespace()
                    .any(|field| socket_endpoint_port(field) == Some(port))
        });
        return if listening {
            RemoteListenerProbe::Listening
        } else {
            RemoteListenerProbe::Missing
        };
    }
    RemoteListenerProbe::Unsupported
}

fn socket_endpoint_port(endpoint: &str) -> Option<u16> {
    let endpoint = endpoint.trim_matches(|character: char| {
        character == ',' || character == ';' || character == '(' || character == ')'
    });
    endpoint
        .rsplit_once(':')
        .or_else(|| endpoint.rsplit_once('.'))
        .and_then(|(_, port)| port.parse::<u16>().ok())
}

fn record_tunnel_health_event(state: &AppState, session_id: &str, tunnel_id: &str, message: &str) {
    record_applied_system_event(
        state,
        session_id,
        format!("PortMate: remote tunnel {tunnel_id}: {message}"),
        "remote tunnel health event",
    );
}

fn enabled_tunnel_specs(state: &AppState, session_id: &str) -> Result<Vec<TunnelSpec>, String> {
    let store = state.store.lock().map_err(|error| error.to_string())?;
    let profile = store
        .profile(session_id)
        .ok_or_else(|| format!("unknown session: {session_id}"))?;
    let tunnels = match profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => ssh.tunnels,
        _ => Vec::new(),
    };
    Ok(normalize_tunnels(tunnels)
        .into_iter()
        .filter(|tunnel| tunnel.enabled)
        .collect())
}

async fn restore_enabled_tunnels(
    state: &AppState,
    session_id: &str,
    runtime_id: &str,
) -> (usize, usize) {
    if !ssh_runtime_connected(state, session_id, runtime_id) {
        return (0, 0);
    }
    let tunnels = match enabled_tunnel_specs(state, session_id) {
        Ok(tunnels) => tunnels,
        Err(error) => {
            record_tunnel_restore_failure(state, session_id, None, &error);
            return (0, 1);
        }
    };
    let mut restored = 0;
    let mut failed = 0;
    for tunnel in tunnels {
        if !ssh_runtime_connected(state, session_id, runtime_id) {
            break;
        }
        let tunnel_id = tunnel.id.clone();
        match start_tunnel_runtime(state, session_id, tunnel, false, Some(runtime_id)).await {
            Ok((tunnel, local_addr, _)) => {
                if !ssh_runtime_connected(state, session_id, runtime_id) {
                    let _ = fail_tunnel_runtime_if_owned(
                        &state.tunnels,
                        &tunnel_id,
                        runtime_id,
                        "SSH reconnect superseded while restoring tunnel",
                    );
                    break;
                }
                restored += 1;
                if let Err(error) =
                    persist_tunnel_to_profile_and_log(state, session_id, &tunnel, local_addr)
                {
                    record_tunnel_restore_failure(
                        state,
                        session_id,
                        Some(&tunnel_id),
                        &format!("runtime restored but persistence failed: {error}"),
                    );
                }
            }
            Err(error) => {
                if !ssh_runtime_connected(state, session_id, runtime_id) {
                    break;
                }
                failed += 1;
                record_tunnel_restore_failure(state, session_id, Some(&tunnel_id), &error);
            }
        }
    }
    (restored, failed)
}

fn record_tunnel_restore_failure(
    state: &AppState,
    session_id: &str,
    tunnel_id: Option<&str>,
    error: &str,
) {
    let label = tunnel_id.map(|id| format!(" {id}")).unwrap_or_default();
    record_applied_system_event(
        state,
        session_id,
        format!("PortMate: failed to restore SSH tunnel{label}: {error}"),
        "tunnel restore failure event",
    );
}

fn normalize_tunnel_request(
    mut request: CreateTunnelRequest,
) -> Result<CreateTunnelRequest, String> {
    for (label, value) in [
        ("session id", request.session_id.as_str()),
        ("bind host", request.bind_host.as_str()),
        ("target host", request.target_host.as_str()),
    ] {
        if value.chars().any(char::is_control) {
            return Err(format!(
                "tunnel {label} must not contain control characters"
            ));
        }
    }
    if request
        .label
        .as_deref()
        .is_some_and(|label| label.chars().any(char::is_control))
    {
        return Err("tunnel label must not contain control characters".to_string());
    }
    request.session_id = request.session_id.trim().to_string();
    request.bind_host = request.bind_host.trim().to_string();
    request.target_host = request.target_host.trim().to_string();
    request.label = request
        .label
        .as_deref()
        .map(str::trim)
        .filter(|label| !label.is_empty())
        .map(ToOwned::to_owned);

    if request.mode == TunnelMode::Dynamic {
        request.target_host.clear();
        request.target_port = 0;
    }
    validate_tunnel_request_text(
        "session id",
        &request.session_id,
        MAX_SESSION_PROFILE_ID_CHARACTERS,
        false,
        false,
    )?;
    validate_tunnel_request_text(
        "bind host",
        &request.bind_host,
        MAX_TUNNEL_HOST_CHARACTERS,
        request.mode == TunnelMode::Remote,
        true,
    )?;
    if let Some(label) = request.label.as_deref() {
        validate_tunnel_request_text("label", label, MAX_TUNNEL_LABEL_CHARACTERS, false, false)?;
    }
    if request.mode != TunnelMode::Dynamic {
        if request.target_host.is_empty() || request.target_port == 0 {
            return Err("local and remote tunnels require a target host and port".to_string());
        }
        validate_tunnel_request_text(
            "target host",
            &request.target_host,
            MAX_TUNNEL_HOST_CHARACTERS,
            false,
            true,
        )?;
    }
    Ok(request)
}

fn validate_tunnel_request_text(
    label: &str,
    value: &str,
    max_characters: usize,
    allow_empty: bool,
    reject_whitespace: bool,
) -> Result<(), String> {
    if !allow_empty && value.is_empty() {
        return Err(format!("tunnel {label} must not be empty"));
    }
    let mut count = 0_usize;
    for character in value.chars() {
        count = count.saturating_add(1);
        if count > max_characters {
            return Err(format!(
                "tunnel {label} exceeds {max_characters} Unicode characters"
            ));
        }
        if character.is_control() {
            return Err(format!(
                "tunnel {label} must not contain control characters"
            ));
        }
        if reject_whitespace && character.is_whitespace() {
            return Err(format!("tunnel {label} must not contain whitespace"));
        }
    }
    Ok(())
}

fn list_tunnels_inner(
    state: &AppState,
    session_id: Option<&str>,
) -> Result<Vec<TunnelStatus>, String> {
    let tunnels = state.tunnels.lock().map_err(|error| error.to_string())?;
    let mut statuses = tunnels
        .values()
        .filter(|runtime| {
            !runtime.closed.load(Ordering::SeqCst)
                && match session_id {
                    Some(expected) => runtime.session_id == expected,
                    None => true,
                }
        })
        .map(tunnel_status_from_runtime)
        .collect::<Vec<_>>();
    statuses.sort_by(|left, right| {
        left.spec
            .label
            .cmp(&right.spec.label)
            .then_with(|| left.spec.id.cmp(&right.spec.id))
    });
    Ok(statuses)
}

fn fail_tunnel_runtime_if_owned(
    tunnels: &Arc<Mutex<HashMap<String, TunnelRuntime>>>,
    tunnel_id: &str,
    ssh_runtime_id: &str,
    error: &str,
) -> Result<Option<TunnelRuntime>, String> {
    let runtime = remove_tunnel_runtime_if_owned(tunnels, tunnel_id, ssh_runtime_id)?;
    if let Some(runtime) = &runtime {
        runtime.metrics.record_error(error);
        runtime.closed.store(true, Ordering::SeqCst);
    }
    Ok(runtime)
}

fn remove_tunnel_runtime_if_owned(
    tunnels: &Arc<Mutex<HashMap<String, TunnelRuntime>>>,
    tunnel_id: &str,
    ssh_runtime_id: &str,
) -> Result<Option<TunnelRuntime>, String> {
    let mut tunnels = tunnels
        .lock()
        .map_err(|lock_error| lock_error.to_string())?;
    if tunnels
        .get(tunnel_id)
        .is_none_or(|runtime| runtime.ssh_runtime_id != ssh_runtime_id)
    {
        return Ok(None);
    }
    Ok(tunnels.remove(tunnel_id))
}

fn fail_session_tunnel_runtimes(
    tunnels: &Arc<Mutex<HashMap<String, TunnelRuntime>>>,
    session_id: &str,
    error: &str,
) -> Result<usize, String> {
    let mut tunnels = tunnels
        .lock()
        .map_err(|lock_error| lock_error.to_string())?;
    let ids = tunnels
        .iter()
        .filter_map(|(id, runtime)| (runtime.session_id == session_id).then_some(id.clone()))
        .collect::<Vec<_>>();
    let mut removed = 0;
    for id in ids {
        if let Some(runtime) = tunnels.remove(&id) {
            runtime.metrics.record_error(error);
            runtime.closed.store(true, Ordering::SeqCst);
            removed += 1;
        }
    }
    Ok(removed)
}

async fn stop_tunnel_inner(state: &AppState, tunnel_id: &str) -> Result<TunnelStatus, String> {
    let expected_runtime_id = {
        let tunnels = state.tunnels.lock().map_err(|error| error.to_string())?;
        tunnels
            .get(tunnel_id)
            .map(|runtime| runtime.ssh_runtime_id.clone())
            .ok_or_else(|| format!("tunnel not found: {tunnel_id}"))?
    };
    let (runtime, warnings) =
        stop_tunnel_runtime_effects(state, tunnel_id, &expected_runtime_id).await?;

    let mut stopped = runtime.spec.clone();
    stopped.enabled = false;
    let persistence_result =
        persist_stopped_tunnel_to_profile_and_log(state, &runtime.session_id, &stopped);
    if !warnings.is_empty() {
        let warning = warnings.join("; ");
        runtime.metrics.record_error(&warning);
        record_tunnel_health_event(
            state,
            &runtime.session_id,
            tunnel_id,
            &format!("stopped locally with warning: {warning}"),
        );
    }
    if let Err(error) = persistence_result {
        return Err(format!(
            "tunnel stopped locally, but the disabled state could not be persisted: {error}"
        ));
    }
    Ok(runtime.metrics.snapshot(stopped))
}

async fn stop_tunnel_runtime_effects(
    state: &AppState,
    tunnel_id: &str,
    ssh_runtime_id: &str,
) -> Result<(TunnelRuntime, Vec<String>), String> {
    let runtime = remove_tunnel_runtime_if_owned(&state.tunnels, tunnel_id, ssh_runtime_id)?
        .ok_or_else(|| format!("tunnel runtime was superseded: {tunnel_id}"))?;
    runtime.closed.store(true, Ordering::SeqCst);
    let mut warnings = Vec::new();
    if runtime.spec.mode != TunnelMode::Remote {
        return Ok((runtime, warnings));
    }

    let remote_forward = match state.ssh.lock() {
        Ok(connections) => connections
            .get(&runtime.session_id)
            .filter(|ssh| ssh.runtime_id == runtime.ssh_runtime_id)
            .map(|ssh| (Arc::clone(&ssh.handle), Arc::clone(&ssh.remote_forwards))),
        Err(error) => {
            warnings.push(format!(
                "SSH runtime lock failed during remote cancel: {error}"
            ));
            None
        }
    };
    if let Some((handle, remote_forwards)) = remote_forward {
        warnings.extend(cancel_remote_tunnel_forward(handle, remote_forwards, &runtime.spec).await);
    } else if warnings.is_empty() {
        warnings.push("SSH runtime unavailable during remote cancel".to_string());
    }
    Ok((runtime, warnings))
}

async fn cancel_remote_tunnel_forward(
    handle: Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>,
    remote_forwards: Arc<Mutex<HashMap<String, TunnelForwardTarget>>>,
    tunnel: &TunnelSpec,
) -> Vec<String> {
    let mut warnings = Vec::new();
    let cancel = tokio::time::timeout(REMOTE_TUNNEL_HEALTH_TIMEOUT, async {
        let handle = handle.lock().await;
        handle
            .cancel_tcpip_forward(tunnel.bind_host.clone(), u32::from(tunnel.bind_port))
            .await
    })
    .await;
    match cancel {
        Ok(Ok(())) => {}
        Ok(Err(error)) => warnings.push(format!(
            "remote SSH tunnel cancel failed {}:{}: {error}",
            tunnel.bind_host, tunnel.bind_port
        )),
        Err(_) => warnings.push(format!(
            "remote SSH tunnel cancel timed out {}:{}",
            tunnel.bind_host, tunnel.bind_port
        )),
    }
    match remote_forwards.lock() {
        Ok(mut forwards) => {
            forwards.remove(&remote_forward_key(&tunnel.bind_host, tunnel.bind_port));
            forwards.remove(&remote_forward_port_key(tunnel.bind_port));
        }
        Err(error) => warnings.push(format!("remote forward route cleanup failed: {error}")),
    }
    warnings
}

fn tunnel_status_from_runtime(runtime: &TunnelRuntime) -> TunnelStatus {
    runtime.metrics.snapshot(runtime.spec.clone())
}

fn tunnel_label(
    mode: TunnelMode,
    bind_host: &str,
    bind_port: u16,
    target_host: &str,
    target_port: u16,
) -> String {
    let label = match mode {
        TunnelMode::Local => {
            format!("{bind_host}:{bind_port} -> {target_host}:{target_port}")
        }
        TunnelMode::Dynamic => format!("SOCKS5 {bind_host}:{bind_port}"),
        TunnelMode::Remote => {
            format!("remote {bind_host}:{bind_port} -> {target_host}:{target_port}")
        }
    };
    label.chars().take(MAX_TUNNEL_LABEL_CHARACTERS).collect()
}

fn persist_tunnel_to_profile_and_log(
    state: &AppState,
    session_id: &str,
    tunnel: &TunnelSpec,
    local_addr: Option<std::net::SocketAddr>,
) -> Result<(), String> {
    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    commit_tracked_store_mutation(&mut store, &state.store_path, |next_store| {
        let mut profile = next_store
            .profile(session_id)
            .ok_or_else(|| format!("unknown session: {session_id}"))?;
        match &mut profile.connection {
            ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => {
                ssh.tunnels = normalize_tunnels(std::mem::take(&mut ssh.tunnels));
                ssh.tunnels.retain(|item| item.id != tunnel.id);
                if ssh.tunnels.len() >= MAX_TUNNELS_PER_PROFILE {
                    if let Some(index) = ssh.tunnels.iter().position(|item| !item.enabled) {
                        ssh.tunnels.remove(index);
                    }
                }
                if ssh.tunnels.len() >= MAX_TUNNELS_PER_PROFILE {
                    return Err(format!(
                        "enabled tunnel count has reached {MAX_TUNNELS_PER_PROFILE}"
                    ));
                }
                ssh.tunnels.push(tunnel.clone());
                validate_tunnels(&ssh.tunnels)?;
                next_store.upsert_profile(profile);
            }
            _ => return Err("tunnels require an SSH or Tmux session".to_string()),
        }
        let listen = local_addr
            .map(|addr| addr.to_string())
            .unwrap_or_else(|| format!("{}:{}", tunnel.bind_host, tunnel.bind_port));
        let event_ids = next_store
            .record_system_event_tracked(
                session_id,
                format!(
                    "PortMate: SSH {:?} tunnel listening on {} -> {}:{}",
                    tunnel.mode, listen, tunnel.target_host, tunnel.target_port
                ),
            )
            .into_iter()
            .collect();
        Ok(((), event_ids))
    })
}

fn persist_stopped_tunnel_to_profile_and_log(
    state: &AppState,
    session_id: &str,
    stopped: &TunnelSpec,
) -> Result<(), String> {
    let mut store = state.store.lock().map_err(|error| error.to_string())?;
    mark_tunnel_stopped_in_store(&mut store, session_id, stopped);
    store.record_system_event(
        session_id,
        format!(
            "PortMate: SSH {:?} tunnel stopped on {}:{}",
            stopped.mode, stopped.bind_host, stopped.bind_port
        ),
    );
    persist_applied_store(&store, &state.store_path, "stopped tunnel state")
}

fn mark_tunnel_stopped_in_store(store: &mut SessionStore, session_id: &str, stopped: &TunnelSpec) {
    if let Some(mut profile) = store.profile(session_id) {
        match &mut profile.connection {
            ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => {
                if let Some(saved) = ssh.tunnels.iter_mut().find(|item| item.id == stopped.id) {
                    saved.enabled = false;
                }
                ssh.tunnels = normalize_tunnels(std::mem::take(&mut ssh.tunnels));
                let _ = store.upsert_profile(profile);
            }
            _ => {}
        }
    }
}

fn remote_forward_key(host: &str, port: u16) -> String {
    format!("{}:{}", host, port)
}

fn remote_forward_port_key(port: u16) -> String {
    format!("*:{}", port)
}

#[derive(Debug, PartialEq, Eq)]
enum BoundedConnectionStepError {
    TimedOut,
    Failed(String),
}

async fn bounded_connection_step<T, E, F>(
    operation: F,
    timeout: Duration,
) -> Result<T, BoundedConnectionStepError>
where
    E: std::fmt::Display,
    F: std::future::Future<Output = Result<T, E>>,
{
    match tokio::time::timeout(timeout, operation).await {
        Ok(Ok(value)) => Ok(value),
        Ok(Err(error)) => Err(BoundedConnectionStepError::Failed(error.to_string())),
        Err(_) => Err(BoundedConnectionStepError::TimedOut),
    }
}

async fn request_ssh_disconnect_with_timeout<H: client::Handler>(
    handle: &client::Handle<H>,
    disconnect_description: &str,
) -> Option<String> {
    match tokio::time::timeout(
        SSH_SETUP_TIMEOUT_DISCONNECT_TIMEOUT,
        handle.disconnect(Disconnect::ByApplication, disconnect_description, "en"),
    )
    .await
    {
        Ok(Ok(())) => None,
        Ok(Err(error)) => Some(format!("SSH disconnect request failed: {error}")),
        Err(_) => Some(format!(
            "SSH disconnect request timed out after {} ms",
            SSH_SETUP_TIMEOUT_DISCONNECT_TIMEOUT.as_millis()
        )),
    }
}

async fn open_shared_ssh_exec_channel<H: client::Handler>(
    shared_handle: &Arc<tokio::sync::Mutex<client::Handle<H>>>,
    command: &str,
    timeout: Duration,
    label: &str,
) -> Result<Channel<client::Msg>, String> {
    let started = Instant::now();
    let handle = tokio::time::timeout(timeout, shared_handle.lock())
        .await
        .map_err(|_| format!("{label} handle lock 超时（{} ms）", timeout.as_millis()))?;
    let remaining = timeout
        .checked_sub(started.elapsed())
        .filter(|remaining| !remaining.is_zero())
        .ok_or_else(|| format!("{label} setup 超时（{} ms）", timeout.as_millis()))?;

    let setup = async {
        let channel = handle
            .channel_open_session()
            .await
            .map_err(|error| format!("{label} 打开 SSH channel 失败: {error}"))?;
        channel
            .exec(true, command)
            .await
            .map_err(|error| format!("{label} 启动 SSH exec 失败: {error}"))?;
        Ok::<_, String>(channel)
    };
    match bounded_connection_step(setup, remaining).await {
        Ok(channel) => Ok(channel),
        Err(BoundedConnectionStepError::Failed(error)) => Err(error),
        Err(BoundedConnectionStepError::TimedOut) => {
            let cleanup_warning = request_ssh_disconnect_with_timeout(
                &handle,
                "PortMate auxiliary SSH exec setup timeout",
            )
            .await
            .map(|warning| format!("; {warning}"))
            .unwrap_or_default();
            Err(format!(
                "{label} setup 超时（{} ms）{cleanup_warning}",
                timeout.as_millis()
            ))
        }
    }
}

#[derive(Debug, PartialEq, Eq)]
enum DirectTcpipOpenError {
    TimedOut {
        timeout_ms: u128,
        cleanup_warning: Option<String>,
    },
    Failed(String),
}

async fn open_direct_tcpip_with_timeout<H: client::Handler>(
    handle: &client::Handle<H>,
    target_host: String,
    target_port: u16,
    originator_address: String,
    originator_port: u16,
    timeout: Duration,
    disconnect_description: &str,
) -> Result<Channel<client::Msg>, DirectTcpipOpenError> {
    match bounded_connection_step(
        handle.channel_open_direct_tcpip(
            target_host,
            u32::from(target_port),
            originator_address,
            u32::from(originator_port),
        ),
        timeout,
    )
    .await
    {
        Ok(channel) => Ok(channel),
        Err(BoundedConnectionStepError::Failed(error)) => Err(DirectTcpipOpenError::Failed(error)),
        Err(BoundedConnectionStepError::TimedOut) => {
            // Cancelling russh's confirmation wait can orphan its channel entry.
            let cleanup_warning =
                request_ssh_disconnect_with_timeout(handle, disconnect_description).await;
            Err(DirectTcpipOpenError::TimedOut {
                timeout_ms: timeout.as_millis(),
                cleanup_warning,
            })
        }
    }
}

async fn open_tunnel_direct_tcpip(
    shared_handle: &Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>,
    target_host: String,
    target_port: u16,
    peer: std::net::SocketAddr,
    label: &str,
) -> Result<Channel<client::Msg>, String> {
    let handle = tokio::time::timeout(TUNNEL_CONNECT_TIMEOUT, shared_handle.lock())
        .await
        .map_err(|_| {
            format!(
                "{label} handle lock timed out after {} ms",
                TUNNEL_CONNECT_TIMEOUT.as_millis()
            )
        })?;
    match open_direct_tcpip_with_timeout(
        &handle,
        target_host,
        target_port,
        peer.ip().to_string(),
        peer.port(),
        TUNNEL_CONNECT_TIMEOUT,
        "PortMate tunnel channel open timeout",
    )
    .await
    {
        Ok(channel) => Ok(channel),
        Err(DirectTcpipOpenError::Failed(error)) => Err(format!("{label} failed: {error}")),
        Err(DirectTcpipOpenError::TimedOut {
            timeout_ms,
            cleanup_warning,
        }) => {
            let cleanup_warning = cleanup_warning
                .map(|warning| format!("; {warning}"))
                .unwrap_or_default();
            Err(format!(
                "{label} timed out after {timeout_ms} ms{cleanup_warning}"
            ))
        }
    }
}

async fn handle_local_tunnel_client(
    handle: Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>,
    tunnel: TunnelSpec,
    local_stream: TcpStream,
    peer: std::net::SocketAddr,
    metrics: Arc<TunnelMetrics>,
) -> Result<(), String> {
    let channel = open_tunnel_direct_tcpip(
        &handle,
        tunnel.target_host.clone(),
        tunnel.target_port,
        peer,
        "direct-tcpip open",
    )
    .await?;
    let (mut remote_read, remote_write) = channel.split();
    let (mut local_read, mut local_write) = local_stream.into_split();

    let upload_metrics = Arc::clone(&metrics);
    let local_to_remote = async move {
        let mut buffer = vec![0_u8; 16 * 1024];
        loop {
            let size = local_read
                .read(&mut buffer)
                .await
                .map_err(|error| error.to_string())?;
            if size == 0 {
                remote_write
                    .eof()
                    .await
                    .map_err(|error| error.to_string())?;
                break;
            }
            upload_metrics.add_tcp_to_ssh_bytes(size);
            remote_write
                .data(&buffer[..size])
                .await
                .map_err(|error| error.to_string())?;
        }
        Ok::<(), String>(())
    };

    let download_metrics = Arc::clone(&metrics);
    let remote_to_local = async move {
        while let Some(message) = remote_read.wait().await {
            match message {
                ChannelMsg::Data { data } | ChannelMsg::ExtendedData { data, .. } => {
                    download_metrics.add_ssh_to_tcp_bytes(data.len());
                    local_write
                        .write_all(&data)
                        .await
                        .map_err(|error| error.to_string())?;
                }
                ChannelMsg::Eof | ChannelMsg::Close => break,
                _ => {}
            }
        }
        Ok::<(), String>(())
    };

    tokio::try_join!(local_to_remote, remote_to_local)
        .map(|_| ())
        .map_err(|error| format!("local tunnel pipe failed ({}): {error}", tunnel.label))
}

async fn handle_remote_tunnel_client(
    channel: Channel<client::Msg>,
    tunnel: TunnelSpec,
    originator_address: String,
    originator_port: u16,
    metrics: Arc<TunnelMetrics>,
) -> Result<(), String> {
    let target_connect = bounded_connection_step(
        TcpStream::connect((tunnel.target_host.clone(), tunnel.target_port)),
        TUNNEL_CONNECT_TIMEOUT,
    )
    .await;
    let local_stream = match target_connect {
        Ok(stream) => stream,
        Err(error) => {
            close_ssh_channel_bounded(&channel).await;
            return Err(match error {
                BoundedConnectionStepError::Failed(error) => format!(
                    "remote tunnel target connect failed {}:{} for {}:{}: {error}",
                    tunnel.target_host, tunnel.target_port, originator_address, originator_port
                ),
                BoundedConnectionStepError::TimedOut => format!(
                    "remote tunnel target connect timed out after {} ms {}:{} for {}:{}",
                    TUNNEL_CONNECT_TIMEOUT.as_millis(),
                    tunnel.target_host,
                    tunnel.target_port,
                    originator_address,
                    originator_port
                ),
            });
        }
    };
    pipe_ssh_channel_to_tcp(channel, local_stream, tunnel, metrics).await
}

async fn handle_dynamic_tunnel_client(
    handle: Arc<tokio::sync::Mutex<client::Handle<PortMateSshHandler>>>,
    mut local_stream: TcpStream,
    peer: std::net::SocketAddr,
    metrics: Arc<TunnelMetrics>,
) -> Result<(), String> {
    let (target_host, target_port) = read_socks5_connect_request(&mut local_stream).await?;

    let channel = match open_tunnel_direct_tcpip(
        &handle,
        target_host.clone(),
        target_port,
        peer,
        "dynamic direct-tcpip open",
    )
    .await
    {
        Ok(channel) => channel,
        Err(error) => {
            let _ = local_stream.write_all(&socks5_reply(5)).await;
            return Err(error);
        }
    };

    local_stream
        .write_all(&socks5_reply(0))
        .await
        .map_err(|error| format!("SOCKS5 success response failed: {error}"))?;

    let spec = TunnelSpec {
        id: "dynamic-client".to_string(),
        label: format!("SOCKS5 -> {target_host}:{target_port}"),
        mode: TunnelMode::Dynamic,
        bind_host: String::new(),
        bind_port: 0,
        target_host,
        target_port,
        enabled: true,
    };
    pipe_ssh_channel_to_tcp(channel, local_stream, spec, metrics).await
}

async fn pipe_ssh_channel_to_tcp(
    channel: Channel<client::Msg>,
    local_stream: TcpStream,
    tunnel: TunnelSpec,
    metrics: Arc<TunnelMetrics>,
) -> Result<(), String> {
    let (mut remote_read, remote_write) = channel.split();
    let (mut local_read, mut local_write) = local_stream.into_split();

    let upload_metrics = Arc::clone(&metrics);
    let local_to_remote = async move {
        let mut buffer = vec![0_u8; 16 * 1024];
        loop {
            let size = local_read
                .read(&mut buffer)
                .await
                .map_err(|error| error.to_string())?;
            if size == 0 {
                remote_write
                    .eof()
                    .await
                    .map_err(|error| error.to_string())?;
                break;
            }
            upload_metrics.add_tcp_to_ssh_bytes(size);
            remote_write
                .data(&buffer[..size])
                .await
                .map_err(|error| error.to_string())?;
        }
        Ok::<(), String>(())
    };

    let download_metrics = Arc::clone(&metrics);
    let remote_to_local = async move {
        while let Some(message) = remote_read.wait().await {
            match message {
                ChannelMsg::Data { data } | ChannelMsg::ExtendedData { data, .. } => {
                    download_metrics.add_ssh_to_tcp_bytes(data.len());
                    local_write
                        .write_all(&data)
                        .await
                        .map_err(|error| error.to_string())?;
                }
                ChannelMsg::Eof | ChannelMsg::Close => break,
                _ => {}
            }
        }
        Ok::<(), String>(())
    };

    tokio::try_join!(local_to_remote, remote_to_local)
        .map(|_| ())
        .map_err(|error| format!("tunnel pipe failed ({}): {error}", tunnel.label))
}

fn remove_runtime_if_owned<Runtime>(
    registry: &Mutex<HashMap<String, Runtime>>,
    session_id: &str,
    owns_runtime: impl FnOnce(&Runtime) -> bool,
) -> Result<Option<Runtime>, String> {
    let mut runtimes = registry.lock().map_err(|error| error.to_string())?;
    let owned = runtimes.get(session_id).is_some_and(owns_runtime);
    Ok(if owned {
        runtimes.remove(session_id)
    } else {
        None
    })
}

fn mark_session_connected_with_events(
    store: &mut SessionStore,
    profile: &SessionProfile,
    messages: impl IntoIterator<Item = String>,
) -> Result<(SessionSummary, Vec<String>), String> {
    let fallback = store.set_runtime_status(&profile.id, SessionStatus::Connected)?;
    let mut event_ids = Vec::new();
    for message in messages {
        if let Some(event_id) = store.record_system_event_tracked(&profile.id, message) {
            event_ids.push(event_id);
        }
    }
    if let Some(event_id) = store.record_system_event_tracked(
        &profile.id,
        format!(
            "PortMate: connected to {} ({:?})",
            describe_endpoint(profile),
            profile.kind
        ),
    ) {
        event_ids.push(event_id);
    }
    let summary = store
        .summaries()
        .into_iter()
        .find(|summary| summary.profile.id == profile.id)
        .unwrap_or(fallback);
    Ok((summary, event_ids))
}

async fn remove_ssh_runtime_after_failed_open(
    state: &AppState,
    session_id: &str,
    runtime_id: &str,
) -> Result<(), String> {
    let runtime = remove_runtime_if_owned(&state.ssh, session_id, |runtime| {
        runtime.runtime_id == runtime_id
    })?;
    let Some(runtime) = runtime else {
        return Ok(());
    };
    runtime.closed.store(true, Ordering::SeqCst);
    let handle = runtime.handle.lock().await;
    let _ = handle
        .disconnect(
            Disconnect::ByApplication,
            "PortMate connection commit failed",
            "en",
        )
        .await;
    drop(handle);
    for jump_handle in runtime.jump_handles {
        let handle = jump_handle.lock().await;
        let _ = handle
            .disconnect(
                Disconnect::ByApplication,
                "PortMate connection commit failed",
                "en",
            )
            .await;
    }
    Ok(())
}

fn restore_one_time_host_keys(
    state: &AppState,
    profile_id: &str,
    keys: Vec<TrustedHostKey>,
) -> Result<(), String> {
    restore_one_time_host_keys_in(&state.one_time_host_keys, profile_id, keys)
}

fn restore_one_time_host_keys_in(
    one_time: &Arc<Mutex<HashMap<String, Vec<TrustedHostKey>>>>,
    profile_id: &str,
    keys: Vec<TrustedHostKey>,
) -> Result<(), String> {
    if keys.is_empty() {
        return Ok(());
    }
    let mut one_time = one_time.lock().map_err(|error| error.to_string())?;
    let retained = one_time.entry(profile_id.to_string()).or_default();
    for key in keys {
        if !retained.iter().any(|existing| existing.id == key.id) {
            retained.push(key);
        }
    }
    Ok(())
}

async fn open_ssh_session(
    state: &AppState,
    profile: SessionProfile,
    password: Option<String>,
    passphrase: Option<String>,
) -> Result<SessionSummary, String> {
    if let Some(existing) = {
        let mut connections = state.ssh.lock().map_err(|error| error.to_string())?;
        connections.remove(&profile.id)
    } {
        disconnect_registered_ssh_runtime(
            existing,
            "PortMate reconnect",
            "PortMate reconnect jump",
        )
        .await;
    }

    let established = establish_ssh_runtime(state, &profile, password, passphrase).await?;
    let EstablishedSshRuntime {
        runtime_id,
        runtime,
        tap,
        read_half,
        auth_method,
        closed,
        reader_finished,
    } = established;
    {
        let mut connections = state.ssh.lock().map_err(|error| error.to_string())?;
        connections.insert(profile.id.clone(), runtime);
    }
    let (consumed_one_time_host_keys, one_time_cleanup_error) =
        match take_one_time_host_keys(state, &profile.id) {
            Ok(keys) => (keys, None),
            Err(error) => (Vec::new(), Some(error)),
        };

    let finalize_result = match state.store.lock() {
        Ok(mut store) => {
            commit_tracked_store_mutation(&mut store, &state.store_path, |next_store| {
                let _ = next_store.record_auth_success(&profile.id, auth_method);
                let mut messages = vec![format!(
                    "PortMate: SSH authentication succeeded via {auth_method:?}"
                )];
                if let Some(error) = one_time_cleanup_error.as_deref() {
                    messages.push(format!(
                        "PortMate: failed to consume one-time host key trust: {error}"
                    ));
                }
                mark_session_connected_with_events(next_store, &profile, messages)
            })
        }
        Err(error) => Err(error.to_string()),
    };
    let summary = match finalize_result {
        Ok(summary) => summary,
        Err(error) => {
            let mut errors = vec![error];
            if let Err(cleanup_error) =
                remove_ssh_runtime_after_failed_open(state, &profile.id, &runtime_id).await
            {
                errors.push(format!("SSH runtime cleanup failed: {cleanup_error}"));
            }
            if let Err(restore_error) =
                restore_one_time_host_keys(state, &profile.id, consumed_one_time_host_keys)
            {
                errors.push(format!(
                    "one-time host key trust restore failed: {restore_error}"
                ));
            }
            return Err(errors.join("; "));
        }
    };

    tauri::async_runtime::spawn(read_ssh_channel(SshReadTask {
        state: state.clone(),
        profile: profile.clone(),
        runtime_id,
        tap,
        read_half,
        closed,
        reader_finished,
    }));
    Ok(summary)
}

async fn establish_ssh_runtime(
    state: &AppState,
    profile: &SessionProfile,
    password: Option<String>,
    passphrase: Option<String>,
) -> Result<EstablishedSshRuntime, String> {
    establish_ssh_runtime_with_timeout_mode(
        state,
        profile,
        password,
        passphrase,
        SSH_CONNECT_TIMEOUT,
        None,
        false,
    )
    .await
}

async fn establish_ssh_reconnect_runtime(
    state: &AppState,
    profile: &SessionProfile,
) -> Result<EstablishedSshRuntime, String> {
    establish_ssh_runtime_with_timeout_mode(
        state,
        profile,
        None,
        None,
        SSH_CONNECT_TIMEOUT,
        None,
        true,
    )
    .await
}

#[cfg(test)]
async fn establish_ssh_runtime_with_timeout(
    state: &AppState,
    profile: &SessionProfile,
    password: Option<String>,
    passphrase: Option<String>,
    connect_timeout: Duration,
    agent_socket_path: Option<PathBuf>,
) -> Result<EstablishedSshRuntime, String> {
    establish_ssh_runtime_with_timeout_mode(
        state,
        profile,
        password,
        passphrase,
        connect_timeout,
        agent_socket_path,
        false,
    )
    .await
}

async fn establish_ssh_runtime_with_timeout_mode(
    state: &AppState,
    profile: &SessionProfile,
    password: Option<String>,
    passphrase: Option<String>,
    connect_timeout: Duration,
    agent_socket_path: Option<PathBuf>,
    enforce_profile_snapshot: bool,
) -> Result<EstablishedSshRuntime, String> {
    let mut ssh = match &profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => ssh.clone(),
        _ => return Err("profile is not SSH-backed".to_string()),
    };
    ssh.normalize_health_settings();

    let host = ssh.endpoint.host.trim().to_string();
    if host.is_empty() {
        return Err("SSH 主机不能为空".to_string());
    }
    let username = ssh.username.trim().to_string();
    if username.is_empty() {
        return Err("SSH 用户名不能为空；PortMate 不读取系统 ssh_config 的默认用户名".to_string());
    }

    let mut host_keys = {
        let store = state.store.lock().map_err(|error| error.to_string())?;
        store.host_keys.clone()
    };
    host_keys.keys.extend(ssh.trusted_host_keys.clone());
    let one_time_host_keys = one_time_host_keys_snapshot(state, &profile.id)?;
    host_keys.keys.extend(one_time_host_keys.clone());

    let observed_key = Arc::new(Mutex::new(None));
    let host_key_error = Arc::new(Mutex::new(None));
    let remote_forwards = Arc::new(Mutex::new(HashMap::new()));

    let config = Arc::new(ssh_client_config(&ssh));

    let (mut session, jump_sessions) = connect_ssh_target(
        SshConnectRequest {
            config: Arc::clone(&config),
            store: Arc::clone(&state.store),
            store_path: state.store_path.clone(),
            profile,
            ssh: &ssh,
            host_keys,
            one_time_host_keys: one_time_host_keys.clone(),
            observed_key: Arc::clone(&observed_key),
            host_key_error: Arc::clone(&host_key_error),
            remote_forwards: Arc::clone(&remote_forwards),
            password: password.as_deref(),
            passphrase: passphrase.as_deref(),
            enforce_profile_snapshot,
        },
        connect_timeout,
        agent_socket_path.as_deref(),
    )
    .await?;

    let auth_method = authenticate_ssh_with_timeout(
        &mut session,
        SshAuthenticationRequest {
            ssh: ssh.clone(),
            username: username.clone(),
            password,
            passphrase,
            agent_socket_path,
            timeout: connect_timeout,
            disconnect_description: "PortMate target authentication timeout",
        },
    )
    .await;
    let auth_method = match auth_method {
        Ok(method) => method,
        Err(error) => {
            let cleanup_warning = if matches!(error, SshAuthenticationError::Failed(_)) {
                request_ssh_disconnect_with_timeout(
                    &session,
                    "PortMate target authentication failed",
                )
                .await
            } else {
                None
            };
            disconnect_jump_sessions(jump_sessions, "PortMate target authentication failed").await;
            let cleanup_warning = cleanup_warning
                .map(|warning| format!("; {warning}"))
                .unwrap_or_default();
            return Err(format!(
                "SSH 目标认证失败 {host}:{}: {error}{cleanup_warning}",
                ssh.endpoint.port
            ));
        }
    };
    let host_key_persistence = persist_observed_host_key(
        &state.store,
        &state.store_path,
        HostKeyPersistenceGuard {
            profile_id: &profile.id,
            expected_profile: enforce_profile_snapshot.then_some(profile),
        },
        &observed_key,
        &one_time_host_keys,
    );
    if let Err(error) = host_key_persistence {
        let cleanup_warning = request_ssh_disconnect_with_timeout(
            &session,
            "PortMate target host key persistence failed",
        )
        .await;
        disconnect_jump_sessions(jump_sessions, "PortMate target host key persistence failed")
            .await;
        let cleanup_warning = cleanup_warning
            .map(|warning| format!("; {warning}"))
            .unwrap_or_default();
        return Err(format!("{error}{cleanup_warning}"));
    }

    let channel = open_ssh_terminal_channel_with_timeout(
        &session,
        profile,
        &ssh,
        connect_timeout,
        "PortMate terminal channel setup timeout",
    )
    .await;
    let channel = match channel {
        Ok(channel) => channel,
        Err(error) => {
            let cleanup_warning = if matches!(error, SshTerminalSetupError::Failed(_)) {
                request_ssh_disconnect_with_timeout(
                    &session,
                    "PortMate terminal channel setup failed",
                )
                .await
            } else {
                None
            };
            disconnect_jump_sessions(jump_sessions, "PortMate terminal channel setup failed").await;
            let cleanup_warning = cleanup_warning
                .map(|warning| format!("; {warning}"))
                .unwrap_or_default();
            return Err(format!("{error}{cleanup_warning}"));
        }
    };
    let jump_handles = jump_sessions
        .into_iter()
        .map(|session| Arc::new(tokio::sync::Mutex::new(session)))
        .collect();

    let runtime_id = Uuid::new_v4().to_string();
    let (read_half, write_half) = channel.split();
    let writer = Arc::new(tokio::sync::Mutex::new(write_half));
    let (tap, _) = broadcast::channel(1024);
    let closed = Arc::new(AtomicBool::new(false));
    let (reader_finished_sender, reader_finished) = tokio::sync::oneshot::channel();

    Ok(EstablishedSshRuntime {
        runtime_id: runtime_id.clone(),
        runtime: SshRuntime {
            runtime_id: runtime_id.clone(),
            handle: Arc::new(tokio::sync::Mutex::new(session)),
            sftp: Arc::new(tokio::sync::Mutex::new(None)),
            jump_handles,
            writer,
            tap: tap.clone(),
            remote_forwards,
            closed: Arc::clone(&closed),
            reader_finished,
        },
        tap,
        read_half,
        auth_method,
        closed,
        reader_finished: reader_finished_sender,
    })
}

fn ssh_client_config(ssh: &SshConnection) -> client::Config {
    client::Config {
        keepalive_interval: ssh
            .keepalive_enabled
            .then(|| Duration::from_secs(ssh.keepalive_interval_seconds)),
        keepalive_max: ssh.keepalive_max_missed as usize,
        nodelay: true,
        ..Default::default()
    }
}

async fn connect_ssh_target(
    request: SshConnectRequest<'_>,
    connect_timeout: Duration,
    agent_socket_path: Option<&Path>,
) -> Result<
    (
        client::Handle<PortMateSshHandler>,
        Vec<client::Handle<PortMateSshHandler>>,
    ),
    String,
> {
    let SshConnectRequest {
        config,
        store,
        store_path,
        profile,
        ssh,
        host_keys,
        one_time_host_keys,
        observed_key,
        host_key_error,
        remote_forwards,
        password,
        passphrase,
        enforce_profile_snapshot,
    } = request;
    let one_time_host_key_ids = one_time_host_keys
        .iter()
        .map(|key| key.id.clone())
        .collect::<Vec<_>>();

    let target_host = ssh.endpoint.host.trim().to_string();
    if target_host.is_empty() {
        return Err("SSH 主机不能为空".to_string());
    }
    if ssh.endpoint.port == 0 {
        return Err("SSH 端口必须在 1-65535 之间".to_string());
    }

    let target_handler = ssh_handler_for_endpoint(SshHandlerParams {
        profile_id: profile.id.clone(),
        host: target_host.clone(),
        port: ssh.endpoint.port,
        alias: ssh
            .host_key_policy
            .alias
            .clone()
            .filter(|value| !value.trim().is_empty())
            .or_else(|| Some(profile.id.clone())),
        policy: ssh.host_key_policy.clone(),
        host_keys: host_keys.clone(),
        one_time_host_key_ids: one_time_host_key_ids.clone(),
        observed_key: Arc::clone(&observed_key),
        host_key_error: Arc::clone(&host_key_error),
        remote_forwards: Arc::clone(&remote_forwards),
    });

    if ssh.jumps.is_empty() {
        let session = connect_ssh_transport(
            SshTransportConnectParams {
                config,
                target_host: &target_host,
                target_port: ssh.endpoint.port,
                proxy: &ssh.proxy,
                tcp_keepalive_enabled: ssh.tcp_keepalive_enabled,
                timeout: connect_timeout,
                label: "SSH",
            },
            target_handler,
        )
        .await;
        let session = match session {
            Ok(session) => session,
            Err(SshTransportConnectError::Timeout) => {
                return Err(format!("SSH 连接超时: {target_host}:{}", ssh.endpoint.port));
            }
            Err(SshTransportConnectError::Transport(error)) => return Err(error),
            Err(SshTransportConnectError::Handshake(error)) => {
                return Err(host_key_error
                    .lock()
                    .ok()
                    .and_then(|reason| reason.clone())
                    .unwrap_or_else(|| format!("SSH 握手失败: {error}")));
            }
        };
        return Ok((session, Vec::new()));
    }

    let mut jump_sessions: Vec<client::Handle<PortMateSshHandler>> = Vec::new();
    for (index, jump) in ssh.jumps.iter().enumerate() {
        let (jump_host, jump_port, jump_username) = jump_endpoint_details(jump, index)?;
        let jump_policy = jump_host_key_policy(ssh, jump);
        let observed_jump_key = Arc::new(Mutex::new(None));
        let jump_key_error = Arc::new(Mutex::new(None));
        let jump_ssh = jump_ssh_connection(ssh, jump, jump_policy.clone());
        let jump_handler = ssh_handler_for_endpoint(SshHandlerParams {
            profile_id: profile.id.clone(),
            host: jump_host.clone(),
            port: jump_port,
            alias: jump_policy.alias.clone(),
            policy: jump_ssh.host_key_policy.clone(),
            host_keys: host_keys.clone(),
            one_time_host_key_ids: one_time_host_key_ids.clone(),
            observed_key: Arc::clone(&observed_jump_key),
            host_key_error: Arc::clone(&jump_key_error),
            remote_forwards: Arc::new(Mutex::new(HashMap::new())),
        });
        let mut jump_session = if let Some(previous_jump) = jump_sessions.last_mut() {
            let jump_channel = match open_direct_tcpip_with_timeout(
                previous_jump,
                jump_host.clone(),
                jump_port,
                "127.0.0.1".to_string(),
                0,
                connect_timeout,
                "PortMate jump chain channel timeout",
            )
            .await
            {
                Ok(channel) => channel,
                Err(DirectTcpipOpenError::Failed(error)) => {
                    disconnect_jump_sessions(jump_sessions, "PortMate jump chain channel failed")
                        .await;
                    return Err(format!(
                        "Jump Host 第 {} 跳打开 direct-tcpip 到 {jump_host}:{jump_port} 失败: {error}",
                        index + 1
                    ));
                }
                Err(DirectTcpipOpenError::TimedOut {
                    timeout_ms,
                    cleanup_warning,
                }) => {
                    disconnect_jump_sessions(jump_sessions, "PortMate jump chain channel timeout")
                        .await;
                    let cleanup_warning = cleanup_warning
                        .map(|warning| format!("; {warning}"))
                        .unwrap_or_default();
                    return Err(format!(
                        "Jump Host 第 {} 跳打开 direct-tcpip 到 {jump_host}:{jump_port} 超时（{timeout_ms} ms）{cleanup_warning}",
                        index + 1
                    ));
                }
            };
            match tokio::time::timeout(
                connect_timeout,
                client::connect_stream(config.clone(), jump_channel.into_stream(), jump_handler),
            )
            .await
            {
                Ok(Ok(session)) => session,
                Err(_) => {
                    disconnect_jump_sessions(jump_sessions, "PortMate jump chain connect timeout")
                        .await;
                    return Err(format!(
                        "Jump Host 第 {} 跳连接超时: {jump_host}:{jump_port}",
                        index + 1
                    ));
                }
                Ok(Err(error)) => {
                    let reason = jump_key_error
                        .lock()
                        .ok()
                        .and_then(|reason| reason.clone())
                        .unwrap_or_else(|| error.to_string());
                    disconnect_jump_sessions(jump_sessions, "PortMate jump chain handshake failed")
                        .await;
                    return Err(format!(
                        "Jump Host 第 {} 跳 SSH 握手失败 {jump_host}:{jump_port}: {reason}",
                        index + 1
                    ));
                }
            }
        } else {
            let jump_transport_label = format!("Jump Host 第 {} 跳", index + 1);
            match connect_ssh_transport(
                SshTransportConnectParams {
                    config: config.clone(),
                    target_host: &jump_host,
                    target_port: jump_port,
                    proxy: &ssh.proxy,
                    tcp_keepalive_enabled: ssh.tcp_keepalive_enabled,
                    timeout: connect_timeout,
                    label: &jump_transport_label,
                },
                jump_handler,
            )
            .await
            {
                Ok(session) => session,
                Err(SshTransportConnectError::Timeout) => {
                    return Err(format!(
                        "Jump Host 第 {} 跳连接超时: {jump_host}:{jump_port}",
                        index + 1
                    ));
                }
                Err(SshTransportConnectError::Transport(error)) => return Err(error),
                Err(SshTransportConnectError::Handshake(error)) => {
                    let reason = jump_key_error
                        .lock()
                        .ok()
                        .and_then(|reason| reason.clone())
                        .unwrap_or(error);
                    return Err(format!(
                        "Jump Host 第 {} 跳 SSH 握手失败 {jump_host}:{jump_port}: {reason}",
                        index + 1
                    ));
                }
            }
        };

        if let Err(error) = authenticate_ssh_with_timeout(
            &mut jump_session,
            SshAuthenticationRequest {
                ssh: jump_ssh,
                username: jump_username,
                password: jump_runtime_credential(password, jump.password_secret_ref.as_deref()),
                passphrase: jump_runtime_credential(
                    passphrase,
                    jump.passphrase_secret_ref.as_deref(),
                ),
                agent_socket_path: agent_socket_path.map(Path::to_path_buf),
                timeout: connect_timeout,
                disconnect_description: "PortMate jump authentication timeout",
            },
        )
        .await
        {
            disconnect_jump_sessions(jump_sessions, "PortMate jump authentication failed").await;
            let _ = request_ssh_disconnect_with_timeout(
                &jump_session,
                "PortMate jump authentication failed",
            )
            .await;
            return Err(format!(
                "Jump Host 第 {} 跳认证失败 {jump_host}:{jump_port}: {error}",
                index + 1
            ));
        }
        if let Err(error) = persist_observed_host_key_with_policy(
            &store,
            &store_path,
            HostKeyPersistenceGuard {
                profile_id: &profile.id,
                expected_profile: enforce_profile_snapshot.then_some(profile),
            },
            &jump_policy,
            &observed_jump_key,
            &one_time_host_keys,
            &format!("Jump Host #{}", index + 1),
        ) {
            disconnect_jump_sessions(jump_sessions, "PortMate jump host key rejected").await;
            let _ = request_ssh_disconnect_with_timeout(
                &jump_session,
                "PortMate jump host key rejected",
            )
            .await;
            return Err(format!(
                "Jump Host 第 {} 跳 host key 处理失败 {jump_host}:{jump_port}: {error}",
                index + 1
            ));
        }
        jump_sessions.push(jump_session);
    }

    let jump_channel = match open_direct_tcpip_with_timeout(
        jump_sessions
            .last()
            .expect("non-empty jumps should create jump sessions"),
        target_host.clone(),
        ssh.endpoint.port,
        "127.0.0.1".to_string(),
        0,
        connect_timeout,
        "PortMate jump target channel timeout",
    )
    .await
    {
        Ok(channel) => channel,
        Err(DirectTcpipOpenError::Failed(error)) => {
            disconnect_jump_sessions(jump_sessions, "PortMate jump target channel failed").await;
            return Err(format!(
                "Jump Host 打开 direct-tcpip 到 {target_host}:{} 失败: {error}",
                ssh.endpoint.port
            ));
        }
        Err(DirectTcpipOpenError::TimedOut {
            timeout_ms,
            cleanup_warning,
        }) => {
            disconnect_jump_sessions(jump_sessions, "PortMate jump target channel timeout").await;
            let cleanup_warning = cleanup_warning
                .map(|warning| format!("; {warning}"))
                .unwrap_or_default();
            return Err(format!(
                "Jump Host 打开 direct-tcpip 到 {target_host}:{} 超时（{timeout_ms} ms）{cleanup_warning}",
                ssh.endpoint.port
            ));
        }
    };
    let target_session = match tokio::time::timeout(
        connect_timeout,
        client::connect_stream(config, jump_channel.into_stream(), target_handler),
    )
    .await
    {
        Ok(Ok(session)) => session,
        Err(_) => {
            disconnect_jump_sessions(jump_sessions, "PortMate jump target connect timeout").await;
            return Err(format!(
                "SSH 经 Jump Host 连接超时: {target_host}:{}",
                ssh.endpoint.port
            ));
        }
        Ok(Err(error)) => {
            disconnect_jump_sessions(jump_sessions, "PortMate jump target handshake failed").await;
            return Err(host_key_error
                .lock()
                .ok()
                .and_then(|reason| reason.clone())
                .unwrap_or_else(|| format!("SSH 经 Jump Host 握手失败: {error}")));
        }
    };

    Ok((target_session, jump_sessions))
}

fn jump_endpoint_details(
    jump: &portmate_core::JumpHop,
    index: usize,
) -> Result<(String, u16, String), String> {
    let label = format!("Jump Host 第 {} 跳", index + 1);
    let host = jump.host.trim().to_string();
    if host.is_empty() {
        return Err(format!("{label} 主机不能为空"));
    }
    if jump.port == 0 {
        return Err(format!("{label} 端口必须在 1-65535 之间"));
    }
    let username = jump.username.trim().to_string();
    if username.is_empty() {
        return Err(format!("{label} 用户名不能为空"));
    }
    Ok((host, jump.port, username))
}

async fn disconnect_jump_sessions(
    jump_sessions: Vec<client::Handle<PortMateSshHandler>>,
    reason: &str,
) {
    let disconnect_all = async {
        for session in jump_sessions {
            let _ = session
                .disconnect(Disconnect::ByApplication, reason, "en")
                .await;
        }
    };
    if tokio::time::timeout(SSH_SETUP_TIMEOUT_DISCONNECT_TIMEOUT, disconnect_all)
        .await
        .is_err()
    {
        eprintln!(
            "PortMate: Jump Host cleanup did not finish within {} ms: {reason}",
            SSH_SETUP_TIMEOUT_DISCONNECT_TIMEOUT.as_millis()
        );
    }
}

fn ssh_handler_for_endpoint(params: SshHandlerParams) -> PortMateSshHandler {
    PortMateSshHandler {
        profile_id: params.profile_id,
        host: params.host,
        port: params.port,
        alias: params.alias,
        policy: params.policy,
        host_keys: params.host_keys,
        one_time_host_key_ids: params.one_time_host_key_ids,
        observed_key: params.observed_key,
        host_key_error: params.host_key_error,
        remote_forwards: params.remote_forwards,
    }
}

fn trusted_host_key_allowed(
    policy: &portmate_core::HostKeyPolicy,
    matched_key_id: &str,
    one_time_host_key_ids: &[String],
) -> bool {
    policy.mode != HostKeyMode::AskEveryTime
        || one_time_host_key_ids
            .iter()
            .any(|key_id| key_id == matched_key_id)
}

fn jump_host_key_policy(
    ssh: &SshConnection,
    jump: &portmate_core::JumpHop,
) -> portmate_core::HostKeyPolicy {
    let default_alias = format!("jump:{}:{}", jump.host.trim(), jump.port);
    let mut policy = if let Some(custom) = jump.host_key_policy.clone() {
        custom
    } else {
        let mut inherited = ssh.host_key_policy.clone();
        inherited.alias = Some(default_alias.clone());
        inherited.trust_scope = HostKeyScope::Profile;
        inherited
    };
    policy.alias = policy
        .alias
        .as_deref()
        .map(str::trim)
        .filter(|alias| !alias.is_empty())
        .map(str::to_string)
        .or(Some(default_alias));
    policy
}

fn jump_ssh_connection(
    ssh: &SshConnection,
    jump: &portmate_core::JumpHop,
    host_key_policy: portmate_core::HostKeyPolicy,
) -> SshConnection {
    let mut identity_refs = ssh.identity_refs.clone();
    if let Some(identity_ref) = jump
        .identity_ref
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        identity_refs.retain(|identity| identity.id == identity_ref);
    }
    SshConnection {
        endpoint: portmate_core::HostEndpoint {
            host: jump.host.trim().to_string(),
            port: jump.port,
        },
        username: jump.username.trim().to_string(),
        reconnect: ssh.reconnect,
        reconnect_delay_ms: ssh.reconnect_delay_ms,
        keepalive_enabled: ssh.keepalive_enabled,
        keepalive_interval_seconds: ssh.keepalive_interval_seconds,
        keepalive_max_missed: ssh.keepalive_max_missed,
        tcp_keepalive_enabled: ssh.tcp_keepalive_enabled,
        proxy: ssh.proxy.clone(),
        password_secret_ref: jump
            .password_secret_ref
            .as_ref()
            .map(|value| value.trim())
            .filter(|value| !value.is_empty())
            .map(str::to_string)
            .or_else(|| ssh.password_secret_ref.clone()),
        passphrase_secret_ref: jump
            .passphrase_secret_ref
            .as_ref()
            .map(|value| value.trim())
            .filter(|value| !value.is_empty())
            .map(str::to_string)
            .or_else(|| ssh.passphrase_secret_ref.clone()),
        host_key_policy,
        trusted_host_keys: Vec::new(),
        identity_policy: ssh.identity_policy.clone(),
        identity_refs,
        agent_policy: ssh.agent_policy.clone(),
        jumps: Vec::new(),
        tunnels: Vec::new(),
    }
}

fn jump_runtime_credential(
    inherited: Option<&str>,
    jump_secret_ref: Option<&str>,
) -> Option<String> {
    if jump_secret_ref.is_some_and(|value| !value.trim().is_empty()) {
        None
    } else {
        inherited
            .filter(|value| !value.is_empty())
            .map(str::to_string)
    }
}

fn open_shell_session(state: &AppState, profile: SessionProfile) -> Result<SessionSummary, String> {
    let shell = match &profile.connection {
        ConnectionConfig::Shell(shell) => shell.clone(),
        _ => return Err("profile is not shell-backed".to_string()),
    };
    let program = if shell.program.trim().is_empty() {
        default_shell_program()
    } else {
        shell.program.trim().to_string()
    };

    if let Some(existing) = {
        let mut connections = state.shell.lock().map_err(|error| error.to_string())?;
        connections.remove(&profile.id)
    } {
        existing.closed.store(true, Ordering::SeqCst);
        if let Ok(mut child) = existing.child.lock() {
            let _ = child.kill();
        }
    }

    let pty_system = native_pty_system();
    let pair = pty_system
        .openpty(PtySize {
            rows: profile.terminal.rows,
            cols: profile.terminal.cols,
            pixel_width: 0,
            pixel_height: 0,
        })
        .map_err(|error| format!("Shell PTY 打开失败: {error}"))?;

    let mut command = CommandBuilder::new(&program);
    command.args(shell.args.iter());
    apply_shell_terminal_color_env(&mut command, profile.terminal.term.as_str());
    if let Some(cwd) = shell
        .cwd
        .as_deref()
        .filter(|value| !value.trim().is_empty())
    {
        command.cwd(cwd);
    }

    let child = pair
        .slave
        .spawn_command(command)
        .map_err(|error| format!("Shell 启动失败 {program}: {error}"))?;
    drop(pair.slave);

    let reader = pair
        .master
        .try_clone_reader()
        .map_err(|error| format!("Shell PTY reader 创建失败: {error}"))?;
    let writer = pair
        .master
        .take_writer()
        .map_err(|error| format!("Shell PTY writer 创建失败: {error}"))?;

    let runtime_id = Uuid::new_v4().to_string();
    let closed = Arc::new(AtomicBool::new(false));
    let reader_start_gate = Arc::new(ReaderStartGate::default());
    let (tap, _) = broadcast::channel(1024);
    let child = Arc::new(Mutex::new(child));
    let master = Arc::new(Mutex::new(pair.master));
    let writer = Arc::new(Mutex::new(writer));
    {
        let mut connections = state.shell.lock().map_err(|error| error.to_string())?;
        connections.insert(
            profile.id.clone(),
            ShellRuntime {
                runtime_id: runtime_id.clone(),
                master,
                writer,
                tap: tap.clone(),
                child: Arc::clone(&child),
                closed: Arc::clone(&closed),
            },
        );
    }

    if let Err(error) = std::thread::Builder::new()
        .name(format!("portmate-shell-{}", profile.id))
        .spawn(read_shell_pty(ShellReadTask {
            io: state.session_io(),
            session_id: profile.id.clone(),
            runtime_id: runtime_id.clone(),
            program: program.clone(),
            tap,
            closed: Arc::clone(&closed),
            start_gate: Arc::clone(&reader_start_gate),
            child: Arc::clone(&child),
            reader,
        }))
    {
        closed.store(true, Ordering::SeqCst);
        reader_start_gate.cancel();
        if let Ok(mut child) = child.lock() {
            let _ = child.kill();
        }
        remove_runtime_if_owned(&state.shell, &profile.id, |runtime| {
            runtime.runtime_id == runtime_id
        })?;
        return Err(format!("Shell PTY 读取线程启动失败: {error}"));
    }

    let finalize_result = match state.store.lock() {
        Ok(mut store) => {
            commit_tracked_store_mutation(&mut store, &state.store_path, |next_store| {
                mark_session_connected_with_events(
                    next_store,
                    &profile,
                    [format!("PortMate: shell started ({program})")],
                )
            })
        }
        Err(error) => Err(error.to_string()),
    };
    match finalize_result {
        Ok(summary) => {
            reader_start_gate.start();
            Ok(summary)
        }
        Err(error) => {
            closed.store(true, Ordering::SeqCst);
            reader_start_gate.cancel();
            if let Ok(mut child) = child.lock() {
                let _ = child.kill();
            }
            let cleanup_error = remove_runtime_if_owned(&state.shell, &profile.id, |runtime| {
                runtime.runtime_id == runtime_id
            })
            .err();
            if let Some(cleanup_error) = cleanup_error {
                Err(format!(
                    "{error}; Shell runtime cleanup failed: {cleanup_error}"
                ))
            } else {
                Err(error)
            }
        }
    }
}

fn serial_connection_details(
    profile: &SessionProfile,
) -> Result<(portmate_core::SerialConnection, String), String> {
    let mut serial = match &profile.connection {
        ConnectionConfig::Serial(serial) => serial.clone(),
        _ => return Err("profile is not serial-backed".to_string()),
    };
    serial.normalize_health_settings();
    let port_name = serial.port.trim().to_string();
    if port_name.is_empty() {
        return Err("串口不能为空".to_string());
    }
    Ok((serial, port_name))
}

fn serial_reconnect_delay(profile: &SessionProfile) -> Duration {
    match &profile.connection {
        ConnectionConfig::Serial(serial) => Duration::from_millis(serial.reconnect_delay_ms.clamp(
            portmate_core::MIN_SERIAL_RECONNECT_DELAY_MS,
            portmate_core::MAX_SERIAL_RECONNECT_DELAY_MS,
        )),
        _ => Duration::from_millis(portmate_core::DEFAULT_SERIAL_RECONNECT_DELAY_MS),
    }
}

fn serial_reconnect_enabled(profile: &SessionProfile) -> bool {
    match &profile.connection {
        ConnectionConfig::Serial(serial) => serial.reconnect,
        _ => false,
    }
}

fn serial_reconnect_attempt_matches_profile(
    attempt: &SessionProfile,
    latest: &SessionProfile,
) -> bool {
    let attempt = normalize_session_profile(attempt.clone());
    let latest = normalize_session_profile(latest.clone());
    serial_reconnect_enabled(&latest) && attempt.connection == latest.connection
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SerialReconnectProfileState {
    Current,
    Changed,
    Disabled,
}

fn serial_reconnect_profile_state(
    store: &SessionStore,
    session_id: &str,
    attempt: &SessionProfile,
) -> SerialReconnectProfileState {
    let Some(latest) = store.profile(session_id).map(normalize_session_profile) else {
        return SerialReconnectProfileState::Disabled;
    };
    if !serial_reconnect_enabled(&latest) {
        return SerialReconnectProfileState::Disabled;
    }
    if !serial_reconnect_attempt_matches_profile(attempt, &latest) {
        return SerialReconnectProfileState::Changed;
    }
    SerialReconnectProfileState::Current
}

fn latest_serial_reconnect_profile(
    io: &SessionIo,
    session_id: &str,
) -> Result<Option<SessionProfile>, String> {
    let store = io.store.lock().map_err(|error| error.to_string())?;
    let Some(profile) = store.profile(session_id) else {
        return Ok(None);
    };
    let profile = normalize_session_profile(profile);
    Ok(serial_reconnect_enabled(&profile).then_some(profile))
}

fn open_configured_serial_port(
    serial: &portmate_core::SerialConnection,
    port_name: &str,
) -> Result<SerialPortPair, String> {
    let mut port = serialport::new(port_name, serial.baud_rate)
        .data_bits(serial_data_bits(serial.data_bits))
        .stop_bits(serial_stop_bits(serial.stop_bits))
        .parity(serial_parity(&serial.parity))
        .flow_control(serial_flow_control(&serial.flow_control))
        .timeout(Duration::from_millis(100))
        .open()
        .map_err(|error| format!("串口打开失败 {port_name}: {error}"))?;
    if let Err(error) = port.write_data_terminal_ready(serial.dtr) {
        if serial.dtr {
            return Err(format!("设置 DTR 失败: {error}"));
        }
        eprintln!("PortMate: serial device does not support clearing DTR: {error}");
    }
    if let Err(error) = port.write_request_to_send(serial.rts) {
        if serial.rts {
            return Err(format!("设置 RTS 失败: {error}"));
        }
        eprintln!("PortMate: serial device does not support clearing RTS: {error}");
    }

    let reader = port
        .try_clone()
        .map_err(|error| format!("串口 reader 克隆失败: {error}"))?;
    Ok((port, reader))
}

fn open_serial_session(
    state: &AppState,
    profile: SessionProfile,
) -> Result<SessionSummary, String> {
    let (serial, port_name) = serial_connection_details(&profile)?;

    if let Some(existing) = {
        let mut connections = state.serial.lock().map_err(|error| error.to_string())?;
        connections.remove(&profile.id)
    } {
        existing.closed.store(true, Ordering::SeqCst);
    }

    let (port, reader) = open_configured_serial_port(&serial, &port_name)?;
    let runtime_id = Uuid::new_v4().to_string();
    let closed = Arc::new(AtomicBool::new(false));
    let reader_start_gate = Arc::new(ReaderStartGate::default());
    let (tap, _) = broadcast::channel(1024);
    let writer = Arc::new(Mutex::new(port));
    let capture = serial_capture_for_session(&state.serial_captures, &profile.id)?;
    {
        let mut connections = state.serial.lock().map_err(|error| error.to_string())?;
        connections.insert(
            profile.id.clone(),
            SerialRuntime {
                runtime_id: runtime_id.clone(),
                writer: Some(writer),
                tap: tap.clone(),
                closed: Arc::clone(&closed),
                capture: Arc::clone(&capture),
            },
        );
    }

    if let Err(error) = spawn_serial_reader(SerialReadTask {
        io: state.session_io(),
        profile: profile.clone(),
        runtime_id: runtime_id.clone(),
        port_name: port_name.clone(),
        tap,
        closed: Arc::clone(&closed),
        start_gate: Arc::clone(&reader_start_gate),
        reader,
        capture,
        receive_idle_timeout: serial
            .receive_idle_timeout_enabled
            .then(|| Duration::from_secs(serial.receive_idle_timeout_seconds)),
    }) {
        closed.store(true, Ordering::SeqCst);
        reader_start_gate.cancel();
        remove_runtime_if_owned(&state.serial, &profile.id, |runtime| {
            runtime.runtime_id == runtime_id
        })?;
        return Err(format!("串口读取线程启动失败: {error}"));
    }

    let finalize_result = match state.store.lock() {
        Ok(mut store) => {
            commit_tracked_store_mutation(&mut store, &state.store_path, |next_store| {
                mark_session_connected_with_events(
                    next_store,
                    &profile,
                    [format!(
                        "PortMate: serial port connected ({port_name}, {} baud)",
                        serial.baud_rate
                    )],
                )
            })
        }
        Err(error) => Err(error.to_string()),
    };
    match finalize_result {
        Ok(summary) => {
            reader_start_gate.start();
            Ok(summary)
        }
        Err(error) => {
            closed.store(true, Ordering::SeqCst);
            reader_start_gate.cancel();
            let cleanup_error = remove_runtime_if_owned(&state.serial, &profile.id, |runtime| {
                runtime.runtime_id == runtime_id
            })
            .err();
            if let Some(cleanup_error) = cleanup_error {
                Err(format!(
                    "{error}; serial runtime cleanup failed: {cleanup_error}"
                ))
            } else {
                Err(error)
            }
        }
    }
}

#[derive(Debug, PartialEq, Eq)]
enum SshAuthenticationError {
    TimedOut {
        timeout_ms: u128,
        cleanup_warning: Option<String>,
    },
    Failed(String),
}

impl std::fmt::Display for SshAuthenticationError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::TimedOut {
                timeout_ms,
                cleanup_warning,
            } => {
                write!(formatter, "SSH 认证超时（{timeout_ms} ms）")?;
                if let Some(warning) = cleanup_warning {
                    write!(formatter, "; {warning}")?;
                }
                Ok(())
            }
            Self::Failed(error) => formatter.write_str(error),
        }
    }
}

#[derive(Debug, PartialEq, Eq)]
enum SshTerminalSetupError {
    TimedOut {
        timeout_ms: u128,
        cleanup_warning: Option<String>,
    },
    Failed(String),
}

impl std::fmt::Display for SshTerminalSetupError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::TimedOut {
                timeout_ms,
                cleanup_warning,
            } => {
                write!(formatter, "SSH 终端 channel setup 超时（{timeout_ms} ms）")?;
                if let Some(warning) = cleanup_warning {
                    write!(formatter, "; {warning}")?;
                }
                Ok(())
            }
            Self::Failed(error) => formatter.write_str(error),
        }
    }
}

async fn open_ssh_terminal_channel_with_timeout<H: client::Handler>(
    session: &client::Handle<H>,
    profile: &SessionProfile,
    ssh: &SshConnection,
    timeout: Duration,
    disconnect_description: &str,
) -> Result<Channel<client::Msg>, SshTerminalSetupError> {
    let setup = async {
        let channel = session
            .channel_open_session()
            .await
            .map_err(|error| format!("SSH 打开 session channel 失败: {error}"))?;
        channel
            .request_pty(
                true,
                &profile.terminal.term,
                u32::from(profile.terminal.cols),
                u32::from(profile.terminal.rows),
                0,
                0,
                &[],
            )
            .await
            .map_err(|error| format!("SSH 请求 PTY 失败: {error}"))?;
        apply_ssh_terminal_color_env(&channel).await;
        if ssh.agent_policy.forwarding {
            channel
                .agent_forward(false)
                .await
                .map_err(|error| format!("SSH 请求 agent forwarding 失败: {error}"))?;
        }
        channel
            .request_shell(true)
            .await
            .map_err(|error| format!("SSH 请求 shell 失败: {error}"))?;
        if matches!(profile.connection, ConnectionConfig::Tmux(_)) {
            channel
                .data(&b"tmux new-session -A -s portmate\r"[..])
                .await
                .map_err(|_| "Tmux attach 命令发送失败: SSH channel 已关闭".to_string())?;
        }
        Ok::<_, String>(channel)
    };

    match bounded_connection_step(setup, timeout).await {
        Ok(channel) => Ok(channel),
        Err(BoundedConnectionStepError::Failed(error)) => Err(SshTerminalSetupError::Failed(error)),
        Err(BoundedConnectionStepError::TimedOut) => {
            let cleanup_warning =
                request_ssh_disconnect_with_timeout(session, disconnect_description).await;
            Err(SshTerminalSetupError::TimedOut {
                timeout_ms: timeout.as_millis(),
                cleanup_warning,
            })
        }
    }
}

struct SshAuthenticationRequest<'a> {
    ssh: SshConnection,
    username: String,
    password: Option<String>,
    passphrase: Option<String>,
    agent_socket_path: Option<PathBuf>,
    timeout: Duration,
    disconnect_description: &'a str,
}

async fn authenticate_ssh_with_timeout<H: client::Handler>(
    session: &mut client::Handle<H>,
    request: SshAuthenticationRequest<'_>,
) -> Result<AuthMethod, SshAuthenticationError> {
    let SshAuthenticationRequest {
        ssh,
        username,
        password,
        passphrase,
        agent_socket_path,
        timeout,
        disconnect_description,
    } = request;
    match bounded_connection_step(
        authenticate_ssh_with_agent_socket(
            session,
            ssh,
            username,
            password,
            passphrase,
            agent_socket_path,
        ),
        timeout,
    )
    .await
    {
        Ok(method) => Ok(method),
        Err(BoundedConnectionStepError::Failed(error)) => {
            Err(SshAuthenticationError::Failed(error))
        }
        Err(BoundedConnectionStepError::TimedOut) => {
            let cleanup_warning =
                request_ssh_disconnect_with_timeout(session, disconnect_description).await;
            Err(SshAuthenticationError::TimedOut {
                timeout_ms: timeout.as_millis(),
                cleanup_warning,
            })
        }
    }
}

async fn authenticate_ssh_with_agent_socket<H: client::Handler>(
    session: &mut client::Handle<H>,
    ssh: SshConnection,
    username: String,
    password: Option<String>,
    passphrase: Option<String>,
    agent_socket_path: Option<PathBuf>,
) -> Result<AuthMethod, String> {
    let auth_order = ordered_auth_methods(&ssh);
    let mut attempted = Vec::new();
    let mut key_errors = Vec::new();
    let saved_password = if password
        .as_deref()
        .filter(|value| !value.is_empty())
        .is_none()
    {
        read_optional_secret_ref(ssh.password_secret_ref.as_deref(), "SSH password")?
    } else {
        None
    };
    let saved_passphrase = if passphrase
        .as_deref()
        .filter(|value| !value.is_empty())
        .is_none()
    {
        read_optional_secret_ref(
            ssh.passphrase_secret_ref.as_deref(),
            "SSH private-key passphrase",
        )?
    } else {
        None
    };
    let effective_password = password
        .filter(|value| !value.is_empty())
        .or(saved_password);
    let effective_passphrase = passphrase
        .filter(|value| !value.is_empty())
        .or(saved_passphrase);
    let mut agent_attempted = false;

    for method in auth_order {
        match method {
            AuthMethod::PublicKey => {
                if ssh.agent_policy.enabled
                    && !agent_attempted
                    && !ssh.identity_policy.identities_only
                    && ssh.agent_policy.offer_mode
                        == portmate_core::AgentOfferMode::BeforeProfileKeys
                {
                    attempted.push("agent(before-profile-keys)");
                    agent_attempted = true;
                    match authenticate_with_agent(
                        session,
                        username.clone(),
                        ssh.identity_policy.identities_only,
                        ssh.agent_policy.offer_mode,
                        ssh.identity_refs.clone(),
                        agent_socket_path.clone(),
                    )
                    .await
                    {
                        Ok(true) => return Ok(AuthMethod::PublicKey),
                        Ok(false) => {}
                        Err(error) => key_errors.push(error),
                    }
                }

                let identities = ssh
                    .identity_refs
                    .iter()
                    .filter(|identity| {
                        matches!(
                            identity.source,
                            IdentitySource::SystemFile | IdentitySource::ProfileVault
                        )
                    })
                    .collect::<Vec<_>>();
                if !identities.is_empty() {
                    attempted.push("publickey");
                    let rsa_hash = session
                        .best_supported_rsa_hash()
                        .await
                        .map_err(|error| {
                            format!("SSH publickey 认证准备失败，无法查询 RSA 签名算法: {error}")
                        })?
                        .flatten();
                    for identity in identities {
                        let label = identity.label.clone();
                        let key = match load_identity_private_key(
                            identity,
                            effective_passphrase.as_deref(),
                        ) {
                            Ok(Some(key)) => key,
                            Ok(None) => continue,
                            Err(error) => {
                                key_errors.push(format!("{label}: {error}"));
                                continue;
                            }
                        };
                        let result = match session
                            .authenticate_publickey(
                                username.clone(),
                                PrivateKeyWithHashAlg::new(Arc::new(key), rsa_hash),
                            )
                            .await
                        {
                            Ok(result) => result,
                            Err(error) => {
                                key_errors.push(format!("{label}: 认证请求失败: {error}"));
                                break;
                            }
                        };
                        if result.success() {
                            return Ok(AuthMethod::PublicKey);
                        }
                        key_errors.push(format!("{label}: 被服务器拒绝"));
                    }
                }

                if ssh.agent_policy.enabled
                    && !agent_attempted
                    && (ssh.agent_policy.offer_mode
                        == portmate_core::AgentOfferMode::AfterProfileKeys
                        || ssh
                            .identity_refs
                            .iter()
                            .any(|identity| identity.source == IdentitySource::Agent))
                    && (!ssh.identity_policy.identities_only
                        || ssh
                            .identity_refs
                            .iter()
                            .any(|identity| identity.source == IdentitySource::Agent))
                {
                    attempted.push("agent(after-profile-keys)");
                    agent_attempted = true;
                    match authenticate_with_agent(
                        session,
                        username.clone(),
                        ssh.identity_policy.identities_only,
                        ssh.agent_policy.offer_mode,
                        ssh.identity_refs.clone(),
                        agent_socket_path.clone(),
                    )
                    .await
                    {
                        Ok(true) => return Ok(AuthMethod::PublicKey),
                        Ok(false) => {}
                        Err(error) => key_errors.push(error),
                    }
                }
            }
            AuthMethod::KeyboardInteractive => {
                let Some(password) = effective_password.clone() else {
                    continue;
                };
                attempted.push("keyboard-interactive");
                if authenticate_keyboard_interactive(session, username.clone(), password).await? {
                    return Ok(AuthMethod::KeyboardInteractive);
                }
            }
            AuthMethod::Password => {
                let Some(password) = effective_password.clone() else {
                    continue;
                };
                attempted.push("password");
                let result = session
                    .authenticate_password(username.clone(), password)
                    .await
                    .map_err(|error| format!("SSH password 认证失败: {error}"))?;
                if result.success() {
                    return Ok(AuthMethod::Password);
                }
            }
            AuthMethod::None => {
                attempted.push("none");
                let result = session
                    .authenticate_none(username.clone())
                    .await
                    .map_err(|error| format!("SSH none 认证失败: {error}"))?;
                if result.success() {
                    return Ok(AuthMethod::None);
                }
            }
            AuthMethod::GssapiWithMic => {
                attempted.push("gssapi-with-mic(unsupported)");
            }
        }
    }

    let mut message = if attempted.is_empty() {
        "SSH 认证失败：没有可尝试的认证方式。请配置 identityRefs 或在连接时输入密码。".to_string()
    } else {
        format!("SSH 认证失败，已尝试: {}", attempted.join(", "))
    };
    if !key_errors.is_empty() {
        message.push_str(&format!("；密钥详情: {}", key_errors.join(" | ")));
    }
    if ssh.agent_policy.enabled && ssh.identity_policy.identities_only {
        message.push_str("；当前按 IdentitiesOnly 处理，不会遍历系统 ssh-agent 的全部密钥");
    }
    Err(message)
}

async fn authenticate_keyboard_interactive<H: client::Handler>(
    session: &mut client::Handle<H>,
    username: String,
    password: String,
) -> Result<bool, String> {
    let mut response = session
        .authenticate_keyboard_interactive_start(username, None::<String>)
        .await
        .map_err(|error| format!("SSH keyboard-interactive 启动失败: {error}"))?;

    for _ in 0..8 {
        match response {
            KeyboardInteractiveAuthResponse::Success => return Ok(true),
            KeyboardInteractiveAuthResponse::Failure { .. } => return Ok(false),
            KeyboardInteractiveAuthResponse::InfoRequest { prompts, .. } => {
                let responses = prompts
                    .iter()
                    .map(|prompt| {
                        if prompt.echo {
                            String::new()
                        } else {
                            password.clone()
                        }
                    })
                    .collect::<Vec<_>>();
                response = session
                    .authenticate_keyboard_interactive_respond(responses)
                    .await
                    .map_err(|error| format!("SSH keyboard-interactive 响应失败: {error}"))?;
            }
        }
    }

    Err("SSH keyboard-interactive 认证轮次过多，已中止".to_string())
}

fn ordered_auth_methods(ssh: &SshConnection) -> Vec<AuthMethod> {
    let mut ordered = Vec::new();
    if let Some(last) = ssh.identity_policy.last_successful.filter(|method| {
        ssh.identity_policy.record_success && ssh.identity_policy.auth_order.contains(method)
    }) {
        ordered.push(last);
    }
    for method in &ssh.identity_policy.auth_order {
        if !ordered.contains(method) {
            ordered.push(*method);
        }
    }
    if ordered.is_empty() {
        ordered.extend([
            AuthMethod::PublicKey,
            AuthMethod::KeyboardInteractive,
            AuthMethod::Password,
        ]);
    }
    ordered
}

fn load_identity_private_key(
    identity: &IdentityRef,
    passphrase: Option<&str>,
) -> Result<Option<ssh_key::PrivateKey>, String> {
    match identity.source {
        IdentitySource::SystemFile => {
            let Some(path) = identity
                .path
                .as_deref()
                .map(str::trim)
                .filter(|path| !path.is_empty())
            else {
                return Ok(None);
            };
            load_secret_key(expand_identity_path(path), passphrase)
                .map(Some)
                .map_err(|error| format!("system-file {}: {error}", path))
        }
        IdentitySource::ProfileVault => {
            let Some(secret_ref) = identity
                .secret_ref
                .as_deref()
                .map(str::trim)
                .filter(|secret_ref| !secret_ref.is_empty())
            else {
                return Err("profile-vault identity 缺少 secretRef".to_string());
            };
            let private_key = read_secret_from_store(secret_ref)?;
            decode_secret_key(&private_key, passphrase)
                .map(Some)
                .map_err(|error| format!("profile-vault {secret_ref}: {error}"))
        }
        IdentitySource::Agent | IdentitySource::PublicKeyOnly => Ok(None),
    }
}

fn ssh_connection(profile: &SessionProfile) -> Result<&SshConnection, String> {
    match &profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => Ok(ssh),
        _ => Err(format!("Profile {} 不是 SSH/Tmux 会话", profile.id)),
    }
}

fn ssh_connection_mut(profile: &mut SessionProfile) -> Result<&mut SshConnection, String> {
    match &mut profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => Ok(ssh),
        _ => Err(format!("Profile {} 不是 SSH/Tmux 会话", profile.id)),
    }
}

fn profile_proxy(profile: &SessionProfile) -> Option<&ProxyConfig> {
    match &profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => Some(&ssh.proxy),
        ConnectionConfig::Tcp(tcp) | ConnectionConfig::Telnet(tcp) => Some(&tcp.proxy),
        ConnectionConfig::Serial(_) | ConnectionConfig::Shell(_) => None,
    }
}

fn profile_proxy_mut(profile: &mut SessionProfile) -> Option<&mut ProxyConfig> {
    match &mut profile.connection {
        ConnectionConfig::Ssh(ssh) | ConnectionConfig::Tmux(ssh) => Some(&mut ssh.proxy),
        ConnectionConfig::Tcp(tcp) | ConnectionConfig::Telnet(tcp) => Some(&mut tcp.proxy),
        ConnectionConfig::Serial(_) | ConnectionConfig::Shell(_) => None,
    }
}

fn find_client_identity(
    store: &SessionStore,
    profile_id: &str,
    identity_id: &str,
) -> Result<IdentityRef, String> {
    let profile = store
        .profiles
        .iter()
        .find(|profile| profile.id == profile_id)
        .ok_or_else(|| format!("unknown session: {profile_id}"))?;
    let ssh = ssh_connection(profile)?;
    let matches = ssh
        .identity_refs
        .iter()
        .filter(|identity| identity.id == identity_id)
        .collect::<Vec<_>>();
    match matches.as_slice() {
        [identity] => Ok((*identity).clone()),
        [] => Err(format!("unknown client identity: {identity_id}")),
        _ => Err(format!(
            "Profile {profile_id} 中存在重复 identity id: {identity_id}"
        )),
    }
}

fn validate_profile_client_identity_ids(profile: &SessionProfile) -> Result<(), String> {
    let Ok(ssh) = ssh_connection(profile) else {
        return Ok(());
    };
    let mut ids = HashSet::new();
    for identity in &ssh.identity_refs {
        if identity.id.trim().is_empty() {
            return Err(format!("Profile {} 包含空 identity id", profile.id));
        }
        if !ids.insert(identity.id.as_str()) {
            return Err(format!(
                "Profile {} 中存在重复 identity id: {}",
                profile.id, identity.id
            ));
        }
    }
    Ok(())
}

fn normalize_client_identity<F>(
    expected_id: &str,
    mut identity: IdentityRef,
    check_secret: F,
) -> Result<IdentityRef, String>
where
    F: FnOnce(&str) -> Result<(), String>,
{
    if identity.id != expected_id || identity.id.trim().is_empty() {
        return Err("identity id 不可修改且不能为空".to_string());
    }
    identity.label = identity.label.trim().to_string();
    if identity.label.is_empty() {
        return Err("identity label 不能为空".to_string());
    }
    identity.fingerprint_sha256 = identity
        .fingerprint_sha256
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);
    identity.path = identity
        .path
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);
    identity.secret_ref = identity
        .secret_ref
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);

    match identity.source {
        IdentitySource::ProfileVault => {
            let secret_ref = identity
                .secret_ref
                .as_deref()
                .ok_or_else(|| "Profile Vault identity 必须包含 secretRef".to_string())?;
            check_secret(secret_ref)?;
            identity.path = None;
        }
        IdentitySource::SystemFile => {
            if identity.path.is_none() {
                return Err("System File identity 必须包含私钥路径".to_string());
            }
            identity.secret_ref = None;
        }
        IdentitySource::Agent | IdentitySource::PublicKeyOnly => {
            identity.secret_ref = None;
        }
    }
    Ok(identity)
}

fn merge_expected_client_identity_update(
    current_identity: &IdentityRef,
    expected_identity: &IdentityRef,
    incoming_identity: IdentityRef,
) -> Result<IdentityRef, String> {
    if current_identity.id != incoming_identity.id || expected_identity.id != incoming_identity.id {
        return Err("expectedIdentity 与更新目标不是同一个 identity".to_string());
    }
    let expected = serde_json::to_value(expected_identity)
        .map_err(|error| format!("序列化 expectedIdentity 失败: {error}"))?;
    let current = serde_json::to_value(current_identity)
        .map_err(|error| format!("序列化当前 identity 失败: {error}"))?;
    let incoming = serde_json::to_value(&incoming_identity)
        .map_err(|error| format!("序列化待更新 identity 失败: {error}"))?;
    let merged = merge_expected_json_value(
        "Client Identity",
        "identity",
        &expected,
        &current,
        &incoming,
    )?;
    serde_json::from_value(merged)
        .map_err(|error| format!("反序列化合并后的 identity 失败: {error}"))
}

fn replace_client_identity(
    store: &mut SessionStore,
    profile_id: &str,
    identity_id: &str,
    identity: IdentityRef,
) -> Result<(SessionSummary, Option<String>), String> {
    let profile = store
        .profiles
        .iter_mut()
        .find(|profile| profile.id == profile_id)
        .ok_or_else(|| format!("unknown session: {profile_id}"))?;
    let ssh = ssh_connection_mut(profile)?;
    let matching = ssh
        .identity_refs
        .iter()
        .enumerate()
        .filter(|(_, identity)| identity.id == identity_id)
        .map(|(index, _)| index)
        .collect::<Vec<_>>();
    let index = match matching.as_slice() {
        [index] => *index,
        [] => return Err(format!("unknown client identity: {identity_id}")),
        _ => {
            return Err(format!(
                "Profile {profile_id} 中存在重复 identity id: {identity_id}"
            ));
        }
    };
    let old_secret_ref = ssh.identity_refs[index].secret_ref.clone();
    ssh.identity_refs[index] = identity;
    let summary = store
        .summaries()
        .into_iter()
        .find(|summary| summary.profile.id == profile_id)
        .ok_or_else(|| format!("session summary is missing: {profile_id}"))?;
    Ok((summary, old_secret_ref))
}

fn remove_client_identity(
    store: &mut SessionStore,
    profile_id: &str,
    identity_id: &str,
) -> Result<(SessionSummary, Option<String>), String> {
    let current = find_client_identity(store, profile_id, identity_id)?;
    let profile = store
        .profiles
        .iter_mut()
        .find(|profile| profile.id == profile_id)
        .ok_or_else(|| format!("unknown session: {profile_id}"))?;
    let ssh = ssh_connection_mut(profile)?;
    if ssh
        .jumps
        .iter()
        .any(|jump| jump.identity_ref.as_deref() == Some(identity_id))
    {
        return Err("identity 正被 Jump Host 使用，无法移除".to_string());
    }
    ssh.identity_refs
        .retain(|identity| identity.id != identity_id);
    let summary = store
        .summaries()
        .into_iter()
        .find(|summary| summary.profile.id == profile_id)
        .ok_or_else(|| format!("session summary is missing: {profile_id}"))?;
    Ok((summary, current.secret_ref))
}

fn canonical_secret_ref(secret_ref: &str) -> Option<String> {
    let secret_ref = secret_ref.trim();
    if secret_ref.is_empty() || secret_ref.contains('\0') {
        return None;
    }
    if let Some(account) = secret_ref.strip_prefix("stronghold:") {
        return (!account.is_empty()).then(|| format!("stronghold:{account}"));
    }
    let account = secret_ref.strip_prefix("keychain:").unwrap_or(secret_ref);
    (!account.is_empty()).then(|| format!("keychain:{account}"))
}

fn secret_ref_usage_count(store: &SessionStore, secret_ref: &str) -> usize {
    let Some(expected) = canonical_secret_ref(secret_ref) else {
        return 0;
    };
    let profile_count = store
        .profiles
        .iter()
        .flat_map(profile_secret_ref_occurrences)
        .filter(|secret_ref| secret_ref == &expected)
        .count();
    let one_key_count = store
        .one_keys
        .iter()
        .flat_map(one_key_secret_refs)
        .filter(|secret_ref| secret_ref == &expected)
        .count();
    profile_count + one_key_count
}

fn profile_secret_refs(profile: &SessionProfile) -> HashSet<String> {
    profile_secret_ref_occurrences(profile)
        .into_iter()
        .collect()
}

