        request.text.push('!');
        assert!(validate_terminal_text_export_request(&request, 8)
            .unwrap_err()
            .contains("8 byte limit"));
        request.text.clear();
        assert!(validate_terminal_text_export_request(&request, 8)
            .unwrap_err()
            .contains("empty"));
        request.text = "text".to_string();
        request.view_id = "bad\nview".to_string();
