            state
                .store
                .lock()
                .unwrap()
                .open_session(&profile.id)
                .unwrap();
            let (tap, receiver) = broadcast::channel(8);
            let mut reader = ModemByteReader::new(receiver, Arc::new(AtomicBool::new(false)))
                .watch_connection(Arc::clone(&state.store), profile.id.clone());
            state
                .store
                .lock()
                .unwrap()
